		private string formatNumber(double number)
		{
			string text = number.ToString("F6", CultureInfo.InvariantCulture);
			int num = text.IndexOf('.');
			if (num != -1 && text.Length > num + 3)
			{
				text = text.Insert(num + 4, ".");
			}
			return text;
		}

		private string formatElapsedTimeCompact(long elapsedSeconds)
		{
			long num = elapsedSeconds % 60;
			long num2 = elapsedSeconds / 60 % 60;
			long num3 = elapsedSeconds / 3600 % 24;
			long num4 = elapsedSeconds / 86400 % 365;
			long num5 = elapsedSeconds / 31536000;
			if (num5 > 0)
			{
				return $"{num5}yr {num3:D2}:{num2:D2}:{num:D2}";
			}
			if (num4 > 0)
			{
				return $"{num4}d {num3:D2}:{num2:D2}:{num:D2}";
			}
			return $"{num3:D2}:{num2:D2}:{num:D2}";
		}

		private string formatElapsedTime(long elapsedSeconds)
		{
			long num = elapsedSeconds % 60;
			long num2 = elapsedSeconds / 60 % 60;
			long num3 = elapsedSeconds / 3600 % 24;
			long num4 = elapsedSeconds / 86400 % 365;
			long num5 = elapsedSeconds / 31536000;
			if (num5 > 0)
			{
				return string.Format("{0} year{1} {2} day{3} {4} hour{5}", num5, (num5 > 1) ? "s" : "", num4, (num4 > 1) ? "s" : "", num3, (num3 > 1) ? "s" : "");
			}
			if (num4 > 0)
			{
				return string.Format("{0} day{1} {2} hour{3} {4} minute{5}", num4, (num4 > 1) ? "s" : "", num3, (num3 > 1) ? "s" : "", num2, (num2 > 1) ? "s" : "");
			}
			if (num3 > 0)
			{
				return string.Format("{0} hour{1} {2} minute{3} {4} second{5}", num3, (num3 > 1) ? "s" : "", num2, (num2 > 1) ? "s" : "", num, (num > 1) ? "s" : "");
			}
			if (num2 > 0)
			{
				return string.Format("{0} minute{1} {2} second{3}", num2, (num2 > 1) ? "s" : "", num, (num > 1) ? "s" : "");
			}
			return string.Format("{0} second{1}", num, (num > 1) ? "s" : "");
		}

		public List<string> GetPlaceholders(string text)
		{
			List<string> list = new List<string>();
			int length = text.Length;
			for (int i = 0; i < length; i++)
			{
				if (text[i] != '%' || i + 1 >= length)
				{
					continue;
				}
				int num = text.IndexOf('%', i + 1);
				if (num != -1)
				{
					if (num - i > 1)
					{
						list.Add(text.Substring(i + 1, num - i - 1));
					}
					i = num;
				}
			}
			return list;
		}

		public void TakeReading(Reading reading)
		{
			if (_readings_values.ContainsKey(reading))
			{
				_readings_values[reading] = getReading(_rx, reading, bUseReading: true);
			}
		}

		public bool IsCustomString(string custom)
		{
			bool flag = _all_readings_text.Contains(custom);
			if (custom.StartsWith("discord_"))
			{
				flag |= custom.Contains("general");
				flag |= custom.Contains("bot");
			}
			return flag;
		}

		public object GetReading(string reading, clsMeter owningMeter)
		{
			if (!IsCustomString(reading.ToLower()) && Enum.TryParse<Reading>(reading.ToUpper(), out var result))
			{
				if (_readings_values.TryGetValue(result, out var value))
				{
					_readings[_rx].UseReading(result);
					return value;
				}
				return 0f;
			}
			DateTime now = DateTime.Now;
			DateTime utcNow = DateTime.UtcNow;
			string text = reading.ToLower();
			string text2 = text;
			switch (text2)
			{
			default:
				if (text2 != null)
				{
					if (text2.StartsWith("discord_general"))
					{
						int intPart = getIntPart(text, "discord_general");
						_readings_text_objects[text] = ThetisBotDiscord.GetMessagesString(1271453529361481842uL, intPart);
					}
					else if (text2.StartsWith("discord_bot"))
					{
						int intPart2 = getIntPart(text, "discord_bot");
						_readings_text_objects[text] = ThetisBotDiscord.GetMessagesString(1297325528336044144uL, intPart2, include_author: false);
					}
				}
				break;
			case "time_utc":
				_readings_text_objects[text] = utcNow.ToString("HH:mm:ss");
				break;
			case "time_loc":
				_readings_text_objects[text] = now.ToString("HH:mm:ss");
				break;
			case "date_utc":
				_readings_text_objects[text] = utcNow.ToString("ddd d MMM yyyy");
				break;
			case "date_loc":
				_readings_text_objects[text] = now.ToString("ddd d MMM yyyy");
				break;
			case "time_utc_int":
				_readings_text_objects[text] = utcNow.Hour * 10000 + utcNow.Minute * 100 + utcNow.Second;
				break;
			case "time_loc_int":
				_readings_text_objects[text] = now.Hour * 10000 + now.Minute * 100 + now.Second;
				break;
			case "date_utc_int":
				_readings_text_objects[text] = utcNow.Hour * 10000 + utcNow.Minute * 100 + utcNow.Second;
				break;
			case "date_loc_int":
				_readings_text_objects[text] = now.Hour * 10000 + now.Minute * 100 + now.Second;
				break;
			case "vfoa":
				if (_rx == 1)
				{
					_readings_text_objects[text] = formatNumber(owningMeter.VfoA);
				}
				else
				{
					_readings_text_objects[text] = "";
				}
				break;
			case "vfob":
				if (owningMeter.RX2Enabled && _rx == 1)
				{
					_readings_text_objects[text] = "";
				}
				else
				{
					_readings_text_objects[text] = formatNumber(owningMeter.VfoB);
				}
				break;
			case "vfoasub":
				if (owningMeter.VfoSub >= 0.0 && _rx == 1 && owningMeter.RX2Enabled && (owningMeter.Split || owningMeter.MultiRxEnabled))
				{
					_readings_text_objects[text] = formatNumber(owningMeter.VfoSub);
				}
				else
				{
					_readings_text_objects[text] = "";
				}
				break;
			case "vfoa_double":
				if (_rx == 1)
				{
					_readings_text_objects[text] = Math.Round(owningMeter.VfoA, 6);
				}
				else
				{
					_readings_text_objects[text] = "";
				}
				break;
			case "vfob_double":
				if (owningMeter.RX2Enabled && _rx == 1)
				{
					_readings_text_objects[text] = "";
				}
				else
				{
					_readings_text_objects[text] = Math.Round(owningMeter.VfoB, 6);
				}
				break;
			case "vfoasub_double":
				if (owningMeter.VfoSub >= 0.0 && _rx == 1 && owningMeter.RX2Enabled && (owningMeter.Split || owningMeter.MultiRxEnabled))
				{
					_readings_text_objects[text] = Math.Round(owningMeter.VfoSub, 6);
				}
				else
				{
					_readings_text_objects[text] = "";
				}
				break;
			case "band_vfoa":
				_readings_text_objects[text] = BandStackManager.BandToString(owningMeter.BandVfoA).ToLower();
				break;
			case "band_vfob":
				_readings_text_objects[text] = BandStackManager.BandToString(owningMeter.BandVfoB).ToLower();
				break;
			case "band_vfoasub":
				_readings_text_objects[text] = BandStackManager.BandToString(owningMeter.BandVfoASub).ToLower();
				break;
			case "mode_vfoa":
				_readings_text_objects[text] = owningMeter.ModeVfoA.ToString();
				break;
			case "mode_vfob":
				_readings_text_objects[text] = owningMeter.ModeVfoB.ToString();
				break;
			case "subrx":
				_readings_text_objects[text] = (owningMeter.MultiRxEnabled ? "SubRX" : "");
				break;
			case "filter_vfoa":
				_readings_text_objects[text] = owningMeter.FilterVfoA.ToString();
				break;
			case "filter_vfob":
				_readings_text_objects[text] = owningMeter.FilterVfoB.ToString();
				break;
			case "filter_vfoa_name":
				_readings_text_objects[text] = owningMeter.FilterVfoAName;
				break;
			case "filter_vfob_name":
				_readings_text_objects[text] = owningMeter.FilterVfoBName;
				break;
			case "split":
				_readings_text_objects[text] = ((!owningMeter.Split) ? "" : (owningMeter.QuickSplitEnabled ? "QSPLIT" : "SPLIT"));
				break;
			case "qso_time":
				_readings_text_objects[text] = formatElapsedTime(owningMeter.QsoDurationSeconds);
				break;
			case "qso_time_short":
				_readings_text_objects[text] = formatElapsedTimeCompact(owningMeter.QsoDurationSeconds);
				break;
			case "tb_qso_time":
				_readings_text_objects[text] = (_console.QSOTimerEnabled ? formatElapsedTime(_console.QSOTimerSeconds) : "");
				break;
			case "tb_qso_time_short":
				_readings_text_objects[text] = (_console.QSOTimerEnabled ? formatElapsedTimeCompact(_console.QSOTimerSeconds) : "");
				break;
			case "qso_time_int":
			{
				TimeSpan timeSpan = TimeSpan.FromSeconds(owningMeter.QsoDurationSeconds);
				int hours = timeSpan.Hours;
				int minutes = timeSpan.Minutes;
				int seconds = timeSpan.Seconds;
				_readings_text_objects[text] = hours * 10000 + minutes * 100 + seconds;
				break;
			}
			case "tb_qso_time_int":
			{
				TimeSpan timeSpan2 = TimeSpan.FromSeconds(_console.QSOTimerSeconds);
				int hours2 = timeSpan2.Hours;
				int minutes2 = timeSpan2.Minutes;
				int seconds2 = timeSpan2.Seconds;
				_readings_text_objects[text] = hours2 * 10000 + minutes2 * 100 + seconds2;
				break;
			}
			case "mox":
				_readings_text_objects[text] = (owningMeter.MOX ? "MOX" : "");
				break;
			case "cfc":
				_readings_text_objects[text] = (owningMeter.CFCEnabled ? "CFC" : "");
				break;
			case "comp":
				_readings_text_objects[text] = (owningMeter.CompandEnabled ? "COMP" : "");
				break;
			case "lev":
				_readings_text_objects[text] = (owningMeter.LevelerEnabled ? "LEVELER" : "");
				break;
			case "rx2":
				_readings_text_objects[text] = (owningMeter.RX2Enabled ? "RX2 On" : "");
				break;
			case "rxn":
				_readings_text_objects[text] = owningMeter.RX;
				break;
			case "nr":
				_readings_text_objects[text] = owningMeter.NR;
				break;
			case "tx_eq":
				_readings_text_objects[text] = (owningMeter.TXEQEnabled ? "TXEQ" : "");
				break;
			case "bandtext_vfoa":
				_readings_text_objects[text] = owningMeter.VFOABandText;
				break;
			case "bandtext_vfob":
				_readings_text_objects[text] = owningMeter.VFOBBandText;
				break;
			case "nf":
				if (_rx == 1)
				{
					_readings_text_objects[text] = _console.LastNFRX1;
				}
				else
				{
					_readings_text_objects[text] = _console.LastNFRX2;
				}
				break;
			case "tune_step":
				returnTuneStep(text);
				break;
			case "pa_profile":
				returnPAProfile(text);
				break;
			case "bw_vfoa":
				if (owningMeter.RX != 1)
				{
					_readings_text_objects[text] = 0;
				}
				else
				{
					_readings_text_objects[text] = Math.Abs(owningMeter.FilterVfoAhigh - owningMeter.FilterVfoAlow).ToString();
				}
				break;
			case "bw_vfob":
				if (owningMeter.RX == 1 && owningMeter.RX2Enabled)
				{
					if (owningMeter.Split && owningMeter.IsVfoASub)
					{
						_readings_text_objects[text] = Math.Abs(owningMeter.FilterVfoBhigh - owningMeter.FilterVfoBlow).ToString();
					}
					else
					{
						_readings_text_objects[text] = 0;
					}
				}
				else
				{
					_readings_text_objects[text] = Math.Abs(owningMeter.FilterVfoBhigh - owningMeter.FilterVfoBlow).ToString();
				}
				break;
			case "bw_tx":
				_readings_text_objects[text] = Math.Abs(owningMeter.TXFilterHigh - owningMeter.TXFilterLow).ToString();
				break;
			case "on":
				_readings_text_objects[text] = (owningMeter.Power ? "ON" : "OFF");
				break;
			}
			if (_readings_text_objects.ContainsKey(text))
			{
				if (_readings_text_objects.TryGetValue(text, out var value2))
				{
					return value2;
				}
				return "";
			}
			return "";
		}

		private static int getIntPart(string input, string prefix)
		{
			if (input == prefix)
			{
				return 0;
			}
			if (input.StartsWith(prefix + "="))
			{
				string[] array = input.Split('=');
				if (array.Length == 2 && int.TryParse(array[1], out var result))
				{
					return result;
				}
			}
			return 0;
		}

		public void returnTuneStep(string key)
		{
			if (_console != null)
			{
				try
				{
					_readings_text_objects[key] = _console.TuneStepList[_console.TuneStepIndex].Name;
				}
				catch
				{
				}
			}
		}

		public void returnPAProfile(string key)
		{
			if (_console != null)
			{
				try
				{
					_readings_text_objects[key] = _console.PAProfileName;
				}
				catch
				{
				}
			}
		}

		public void UpdateReadings(string text)
		{
			foreach (Reading all_reading in _all_readings)
			{
				addReading(all_reading, text);
			}
			foreach (string item in _all_readings_text)
			{
				addReadingText(item, text);
			}
		}

		private void addReading(Reading reading, string text)
		{
			if (!_readings_values.ContainsKey(reading) && text.Contains("%" + reading.ToString() + "%", StringComparison.OrdinalIgnoreCase))
			{
				_readings_values.TryAdd(reading, 0f);
			}
		}

		private void addReadingText(string reading, string text)
		{
			if (!_readings_text_objects.ContainsKey(reading) && text.Contains("%" + reading + "%", StringComparison.OrdinalIgnoreCase))
			{
				_readings_text_objects.TryAdd(reading, "");
			}
		}

		public List<string> GetAvailableReadings()
		{
			List<string> list = new List<string>();
			List<string> list2 = new List<string>();
			foreach (Reading all_reading in _all_readings)
			{
				list2.Add(all_reading.ToString().ToUpper());
			}
			list2.Sort();
			list.AddRange(list2);
			list2.Clear();
			foreach (string item in _all_readings_text)
			{
				string text = ((!item.StartsWith("discord_bot", StringComparison.OrdinalIgnoreCase) && !item.StartsWith("discord_general", StringComparison.OrdinalIgnoreCase)) ? item : (item + "=0"));
				list2.Add(text.ToLower());
			}
			list2.Add("precis=1");
			list2.Sort();
			list.AddRange(list2);
			return list;
		}
	}

