		public clsIGSettings()
		{
			_settings = new ConcurrentDictionary<string, object>();
			_readingSource = Reading.NONE;
			_barStyle = clsBarItem.BarStyle.None;
			_maxPower = CurrentPowerRating;
			_units = clsBarItem.Units.DBM;
			_ignoreHistoryDuration = 2000;
			_historyDuration = 50;
			_text_1 = "";
			_text_2 = "";
			_font_family_1 = "";
			_font_family_2 = "";
			_mmio_guid = new Guid[10];
			_mmio_variable = new string[10];
			for (int i = 0; i < _mmio_guid.Length; i++)
			{
				_mmio_guid[i] = Guid.Empty;
				_mmio_variable[i] = "--DEFAULT--";
			}
		}

		public void SetSetting(string setting, object value)
		{
			if (_settings.ContainsKey(setting))
			{
				_settings[setting] = value;
			}
			else
			{
				_settings.TryAdd(setting, value);
			}
		}

		public void SetSetting<T>(string setting, T value)
		{
			if (_settings.ContainsKey(setting))
			{
				_settings[setting] = value;
			}
			else
			{
				_settings.TryAdd(setting, value);
			}
		}

		public object GetSetting(string setting, Type type)
		{
			if (_settings.ContainsKey(setting))
			{
				return _settings[setting];
			}
			if (type == typeof(int))
			{
				return 0;
			}
			if (type == typeof(float))
			{
				return 0f;
			}
			if (type == typeof(double))
			{
				return 0.0;
			}
			if (type == typeof(bool))
			{
				return false;
			}
			if (type == typeof(System.Drawing.Color))
			{
				return System.Drawing.Color.Gray;
			}
			if (type == typeof(Guid))
			{
				return Guid.Empty;
			}
			if (type == typeof(Reading))
			{
				return Reading.NONE;
			}
			if (type == typeof(clsBarItem.BarStyle))
			{
				return clsBarItem.BarStyle.None;
			}
			if (type == typeof(clsBarItem.Units))
			{
				return clsBarItem.Units.DBM;
			}
			if (type == typeof(System.Drawing.FontStyle))
			{
				return System.Drawing.FontStyle.Regular;
			}
			return "";
		}

		public T GetSetting<T>(string setting, bool validate = false, T min = default(T), T max = default(T), T defaultValue = default(T))
		{
			T val = ((!_settings.ContainsKey(setting)) ? defaultValue : ((T)_settings[setting]));
			if (validate)
			{
				if (Comparer<T>.Default.Compare(val, min) < 0)
				{
					return min;
				}
				if (Comparer<T>.Default.Compare(val, max) > 0)
				{
					return max;
				}
			}
			return val;
		}

		public string ToString2()
		{
			try
			{
				string text = Common.SerializeToBase64(_settings);
				text = text.Replace("/", "[backslash]");
				return "1|" + text;
			}
			catch
			{
				return "";
			}
		}

		public bool TryParse2(string str)
		{
			try
			{
				string[] array = str.Split('|');
				if (array.Length != 2)
				{
					return false;
				}
				if (array[0] == "1")
				{
					string base64String = array[1].Replace("[backslash]", "/");
					_settings = Common.DeserializeFromBase64<ConcurrentDictionary<string, object>>(base64String);
				}
				return true;
			}
			catch
			{
				return false;
			}
		}

