		public bool RequiresUpdate => DelayUntilNextUpdate <= 0;

		public int DelayUntilNextUpdate
		{
			get
			{
				if (!_updateStopwatch.IsRunning)
				{
					_updateStopwatch.Restart();
				}
				long num = _msUpdateInterval - _updateStopwatch.ElapsedMilliseconds;
				if (num <= 0)
				{
					_updateStopwatch.Stop();
					num = 0L;
				}
				return (int)num;
			}
		}

