			_mouse_entered = false;
			_mouseButtonDown = false;
			_mouseButton = MouseButtons.None;
			_scales_calibKeys = Array.Empty<float>();
			_scales_calibValues = Array.Empty<PointF>();
			_scales_minX = (_scales_minY = (_scales_maxX = (_scales_maxY = 0f)));
		}

		public void PrepareCalibration()
		{
			if (ScaleCalibration == null || ScaleCalibration.Count == 0)
			{
				_scales_calibKeys = Array.Empty<float>();
				_scales_calibValues = Array.Empty<PointF>();
				_scales_minX = (_scales_minY = (_scales_maxX = (_scales_maxY = 0f)));
				return;
			}
			int count = ScaleCalibration.Count;
			_scales_calibKeys = new float[count];
			_scales_calibValues = new PointF[count];
			int num = 0;
			foreach (KeyValuePair<float, PointF> item in ScaleCalibration.OrderBy((KeyValuePair<float, PointF> p) => p.Key))
			{
				_scales_calibKeys[num] = item.Key;
				_scales_calibValues[num] = item.Value;
				num++;
			}
			_scales_minX = _scales_calibValues.Min((PointF p) => p.X);
			_scales_maxX = _scales_calibValues.Max((PointF p) => p.X);
			_scales_minY = _scales_calibValues.Min((PointF p) => p.Y);
			_scales_maxY = _scales_calibValues.Max((PointF p) => p.Y);
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public void AddPerc(clsPercCache pc)
		{
			float num = pc._value * 100f;
			int num2 = (int)(num + ((num >= 0f) ? 0.5f : (-0.5f)));
			if (!_percCache.TryGetValue(num2, out var _))
			{
				_percCache[num2] = pc;
				_percCacheKey.Enqueue(num2);
				if (_percCache.Count > 500)
				{
					int key = _percCacheKey.Dequeue();
					_percCache.Remove(key);
				}
			}
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public clsPercCache GetPerc(float value)
		{
			float num = value * 100f;
			int key = (int)(num + ((num >= 0f) ? 0.5f : (-0.5f)));
			_percCache.TryGetValue(key, out var value2);
			return value2;
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public bool HasPerc(float value)
		{
			float num = value * 100f;
			int key = (int)(num + ((num >= 0f) ? 0.5f : (-0.5f)));
			clsPercCache value2;
			return _percCache.TryGetValue(key, out value2);
		}

