		public override string ToString()
		{
			return base.ID + "|" + base.ParentID + "|" + base.ItemType.ToString() + "|" + base.TopLeft.X.ToString("f4") + "|" + base.TopLeft.Y.ToString("f4") + "|" + base.Size.Width.ToString("f4") + "|" + base.Size.Height.ToString("f4") + "|" + MeterType.ToString() + "|" + Order;
		}

		public override bool TryParse(string str)
		{
			bool flag = false;
			float result = 0f;
			float result2 = 0f;
			float result3 = 0f;
			float result4 = 0f;
			int result5 = 0;
			MeterType result6 = MeterType.LAST;
			if (str != "")
			{
				string[] array = str.Split('|');
				if (array.Length == 9)
				{
					flag = array[0] != "";
					if (flag)
					{
						base.ID = array[0];
					}
					if (flag)
					{
						base.ParentID = array[1];
					}
					if (flag)
					{
						flag = float.TryParse(array[3], out result);
					}
					if (flag)
					{
						flag = float.TryParse(array[4], out result2);
					}
					if (flag)
					{
						flag = float.TryParse(array[5], out result3);
					}
					if (flag)
					{
						flag = float.TryParse(array[6], out result4);
					}
					if (flag)
					{
						flag = Enum.TryParse<MeterType>(array[7], out result6);
					}
					if (flag)
					{
						MeterType = result6;
					}
					if (flag)
					{
						flag = int.TryParse(array[8], out result5);
					}
					if (flag)
					{
						Order = result5;
					}
				}
			}
			return flag;
		}
	}

