		public clsFilterButtonBox(clsMeter owningmeter)
		{
			_owningmeter = owningmeter;
			base.ItemType = MeterItemType.FILTER_BUTTONS;
			Initialise();
		}

		public override void Initialise()
		{
			_click_highlight = false;
			if (_owningmeter.RX == 1)
			{
				_filter = _owningmeter.FilterVfoA;
				base.Buttons = 12;
			}
			else if (_owningmeter.RX == 2)
			{
				_filter = _owningmeter.FilterVfoB;
				base.Buttons = 9;
			}
			setupButtons();
		}

		public override void FilterChanged(Filter f, string name, int low, int high, bool vfoA, bool vfoB, int max_width, int max_shift)
		{
			Filter filter = _filter;
			_filter = f;
			int num = (int)_filter;
			int num2 = (int)filter;
			if (_owningmeter.RX == 2)
			{
				num -= ((num > 6) ? 3 : 0);
				num2 -= ((num2 > 6) ? 3 : 0);
			}
			SetText(1, num, name);
			SetOn(1, num2, on: false);
			SetOn(1, num, on: true);
		}

		public void InitFilterButtons()
		{
			setupButtons();
		}

		private void setupButtons()
		{
			if (!base.RebuildButtons)
			{
				return;
			}
			for (int i = 0; i < base.Buttons; i++)
			{
				SetText(1, i, GetText(0, i));
				SetFontColour(1, i, GetFontColour(0, i));
				SetFontFamily(1, i, GetFontFamily(0, i));
				SetFontSize(1, i, GetFontSize(0, i));
				SetFontStyle(1, i, GetFontStyle(0, i));
				SetUseIndicator(1, i, GetUseIndicator(0, i));
				SetOnColour(1, i, GetOnColour(0, i));
				SetOffColour(1, i, GetOffColour(0, i));
				SetIndicatorWidth(1, i, GetIndicatorWidth(0, i));
				SetEnabled(1, i, enabled: true);
				SetVisible(1, i, enabled: true);
				SetOn(1, i, on: false);
				SetFillColour(1, i, GetFillColour(0, i));
				SetHoverColour(1, i, GetHoverColour(0, i));
				SetBorderColour(1, i, GetBorderColour(0, i));
				SetClickColour(1, i, GetClickColour(0, i));
				SetUseOffColour(1, i, GetUseOffColour(0, i));
				SetIndicatorType(1, i, GetIndicatorType(0, i));
			}
			bool flag = true;
			if (_console != null)
			{
				if (_owningmeter.RX == 1)
				{
					if (_console.RX1DSPMode == DSPMode.FM || _console.RX1DSPMode == DSPMode.DRM || _console.RX1DSPMode == DSPMode.SPEC)
					{
						flag = false;
					}
				}
				else if (_owningmeter.RX == 2 && (_console.RX2DSPMode == DSPMode.FM || _console.RX2DSPMode == DSPMode.DRM || _console.RX2DSPMode == DSPMode.SPEC))
				{
					flag = false;
				}
			}
			if (flag)
			{
				int num = 0;
				System.Drawing.Color fontColour = GetFontColour(0, 0);
				int num2 = 11 - num + 1;
				int num3 = 0;
				for (int j = 0; j < base.Buttons; j++)
				{
					if (j < num2)
					{
						Filter filter = (Filter)(num + j + num3);
						string filterName = getFilterName(_owningmeter.RX, filter);
						SetText(1, j, filterName);
						if (GetEnabled(1, j))
						{
							SetFontColour(1, j, fontColour);
						}
						else
						{
							SetFontColour(1, j, System.Drawing.Color.FromArgb(255, (int)((float)(int)fontColour.R * 0.3f), (int)((float)(int)fontColour.G * 0.3f), (int)((float)(int)fontColour.B * 0.3f)));
						}
						SetFontSize(1, j, 18f);
						SetOn(1, j, filter == _filter);
						if (_owningmeter.RX == 2 && filter == Filter.F7)
						{
							num3 = 3;
						}
					}
				}
			}
			int num4 = base.Buttons / Columns;
			if (base.Buttons % Columns > 0)
			{
				num4++;
			}
			_ = Border / 2f;
			_ = 0.96f / (float)Columns;
			_ = Margin;
			_ = Border;
			float height = 0.96f / (float)Columns * HeightRatio * (float)num4;
			base.Size = new SizeF(base.Size.Width, height);
		}

		private void setupClick(bool setup)
		{
			if (setup)
			{
				_click_timer = new System.Timers.Timer(100.0);
				_click_timer.Elapsed += delegate
				{
					_click_highlight = false;
					if (_click_timer != null)
					{
						_click_timer.Stop();
						_click_timer.Dispose();
						_click_timer = null;
					}
				};
				_click_timer.AutoReset = false;
				_click_timer.Start();
				_click_timer = null;
			}
			else
			{
				if (_click_timer != null)
				{
					_click_timer.Stop();
					_click_timer.Dispose();
				}
				_click_highlight = true;
			}
		}

		public override void MouseDown(MouseEventArgs e)
		{
			if ((!base.FadeOnRx || _owningmeter.MOX) && (!base.FadeOnTx || !_owningmeter.MOX))
			{
				int buttonIndex = base.ButtonIndex;
				if (buttonIndex != -1 && GetEnabled(1, buttonIndex))
				{
					setupClick(setup: false);
				}
			}
		}

		public override void MouseUp(MouseEventArgs e)
		{
			if ((base.FadeOnRx && !_owningmeter.MOX) || (base.FadeOnTx && _owningmeter.MOX) || _console == null)
			{
				return;
			}
			int num = base.ButtonIndex;
			if (num == -1)
			{
				return;
			}
			setupClick(setup: true);
			if (_owningmeter.RX == 2 && !_owningmeter.RX2Enabled)
			{
				return;
			}
			if (e.Button == MouseButtons.Right)
			{
				if (_console != null)
				{
					_console.BeginInvoke((MethodInvoker)delegate
					{
						_console.PopupFilterContextMenu(_owningmeter.RX, e);
					});
				}
				return;
			}
			if (_owningmeter.RX == 2 && num > 6)
			{
				num += 3;
			}
			Filter filter = (Filter)num;
			setFilter(filter);
		}

		private void setFilter(Filter f)
		{
			if (f == Filter.FIRST)
			{
				return;
			}
			if (_owningmeter.RX == 2)
			{
				_console.BeginInvoke((MethodInvoker)delegate
				{
					_console.RX2Filter = f;
					_console.MatchTXFilterToRXFilter();
				});
			}
			else
			{
				_console.BeginInvoke((MethodInvoker)delegate
				{
					_console.RX1Filter = f;
					_console.MatchTXFilterToRXFilter();
				});
			}
		}
	}

	internal class clsTunestepButtons : clsButtonBox
	{
		private clsMeter _owningmeter;

