		public override bool CWXShown
		{
			get
			{
				return base.CWXShown;
			}
			set
			{
				for (OtherButtonId otherButtonId = OtherButtonId.CWX_KEY; otherButtonId <= OtherButtonId.CWX_F9; otherButtonId++)
				{
					(int bit_group, int bit) tuple = OtherButtonIdHelpers.BitFromID(otherButtonId);
					int item = tuple.bit_group;
					int item2 = tuple.bit;
					item2 = item * 32 + item2;
					SetEnabled(1, item2, value);
					System.Drawing.Color fontColour = GetFontColour(0, item2);
					System.Drawing.Color onColour = GetOnColour(0, item2);
					System.Drawing.Color offColour = GetOffColour(0, item2);
					if (value)
					{
						SetFontColour(1, item2, fontColour);
						SetOnColour(1, item2, onColour);
						SetOffColour(1, item2, offColour);
					}
					else
					{
						SetFontColour(1, item2, System.Drawing.Color.FromArgb(255, (int)((float)(int)fontColour.R * 0.3f), (int)((float)(int)fontColour.G * 0.3f), (int)((float)(int)fontColour.B * 0.3f)));
						SetOnColour(1, item2, System.Drawing.Color.FromArgb(255, (int)((float)(int)onColour.R * 0.3f), (int)((float)(int)onColour.G * 0.3f), (int)((float)(int)onColour.B * 0.3f)));
						SetOffColour(1, item2, System.Drawing.Color.FromArgb(255, (int)((float)(int)offColour.R * 0.3f), (int)((float)(int)offColour.G * 0.3f), (int)((float)(int)offColour.B * 0.3f)));
					}
				}
			}
		}

