		public clsOtherButtons(clsMeter owningmeter, clsItemGroup ig)
		{
			_has_macro_buttons = false;
			_cat_inter = null;
			_text_overlay_to_use_parser = new clsTextOverlay(owningmeter);
			_owningmeter = owningmeter;
			_click_highlight = false;
			_ig = ig;
			_dragging_index = -1;
			_last_draged_to = -1;
			_console.ARP.RecordingChanged += onRecordingChanged;
			_console.ARP.PlayingChanged += onPlayingChanged;
			_global_recording = _console.ARP.IsRecording;
			_global_playing = _console.ARP.IsPlaying;
			_process_in_update_buttons = new Dictionary<OtherButtonId, int>();
			base.ItemType = MeterItemType.OTHER_BUTTONS;
			base.Buttons = 384;
			_visible_bits = new int[12];
			for (int i = 0; i < 12; i++)
			{
				_visible_bits[i] = 0;
			}
			_map = new short[base.Buttons];
			_map_copy = new short[base.Buttons];
			for (short num = 0; num < _map.Length; num++)
			{
				_map[num] = num;
				_map_copy[num] = num;
			}
			_map_changed = false;
			_macro_settings = new OtherButtonMacroSettings[31];
			for (int j = 0; j < 31; j++)
			{
				_macro_settings[j] = new OtherButtonMacroSettings();
				_macro_settings[j].Number = j;
			}
			CatStateHandlers = (CatState)Delegate.Combine(CatStateHandlers, new CatState(OnCatState));
			ContainerVisibleHandlers = (ContainerVisible)Delegate.Combine(ContainerVisibleHandlers, new ContainerVisible(OnContainerVisible));
			Initialise();
		}

		public override void Removing()
		{
			_console.ARP.RecordingChanged -= onRecordingChanged;
			_console.ARP.PlayingChanged -= onPlayingChanged;
			ContainerVisibleHandlers = (ContainerVisible)Delegate.Remove(ContainerVisibleHandlers, new ContainerVisible(OnContainerVisible));
			CatStateHandlers = (CatState)Delegate.Remove(CatStateHandlers, new CatState(OnCatState));
		}

		private void onPlayingChanged(bool playing, string id, string filename, bool isWdsp)
		{
			_global_playing = playing;
			(int bit_group, int bit) tuple = OtherButtonIdHelpers.BitFromID(OtherButtonId.WAVE_RECORD);
			int item = tuple.bit_group;
			int item2 = tuple.bit;
			item2 = item * 32 + item2;
			SetEnabled(0, item2, !playing);
			(int bit_group, int bit) tuple2 = OtherButtonIdHelpers.BitFromID(OtherButtonId.REC);
			item = tuple2.bit_group;
			item2 = tuple2.bit;
			item2 = item * 32 + item2;
			SetEnabled(0, item2, !playing);
			setupButtons();
		}

		private void onRecordingChanged(bool recording, string id, string filename)
		{
			_global_recording = recording;
			if (id.StartsWith("waverecord"))
			{
				(int bit_group, int bit) tuple = OtherButtonIdHelpers.BitFromID(OtherButtonId.REC);
				int item = tuple.bit_group;
				int item2 = tuple.bit;
				item2 = item * 32 + item2;
				SetEnabled(0, item2, !recording);
				(int bit_group, int bit) tuple2 = OtherButtonIdHelpers.BitFromID(OtherButtonId.PLAY);
				item = tuple2.bit_group;
				item2 = tuple2.bit;
				item2 = item * 32 + item2;
				SetEnabled(0, item2, !recording);
			}
			else if (id.StartsWith("quick"))
			{
				(int bit_group, int bit) tuple3 = OtherButtonIdHelpers.BitFromID(OtherButtonId.WAVE_RECORD);
				int item3 = tuple3.bit_group;
				int item4 = tuple3.bit;
				item4 = item3 * 32 + item4;
				SetEnabled(0, item4, !recording);
				(int bit_group, int bit) tuple4 = OtherButtonIdHelpers.BitFromID(OtherButtonId.PLAY);
				item3 = tuple4.bit_group;
				item4 = tuple4.bit;
				item4 = item3 * 32 + item4;
				SetEnabled(0, item4, !recording);
			}
			else
			{
				(int bit_group, int bit) tuple5 = OtherButtonIdHelpers.BitFromID(OtherButtonId.WAVE_RECORD);
				int item5 = tuple5.bit_group;
				int item6 = tuple5.bit;
				item6 = item5 * 32 + item6;
				SetEnabled(0, item6, !recording);
				(int bit_group, int bit) tuple6 = OtherButtonIdHelpers.BitFromID(OtherButtonId.REC);
				item5 = tuple6.bit_group;
				item6 = tuple6.bit;
				item6 = item5 * 32 + item6;
				SetEnabled(0, item6, !recording);
				(int bit_group, int bit) tuple7 = OtherButtonIdHelpers.BitFromID(OtherButtonId.PLAY);
				item5 = tuple7.bit_group;
				item6 = tuple7.bit;
				item6 = item5 * 32 + item6;
				SetEnabled(0, item6, !recording);
			}
			setupButtons();
		}

		private void OnContainerVisible(string id, bool visible)
		{
			if (!_has_macro_buttons)
			{
				return;
			}
			for (int i = 0; i < _macro_settings.Length - 1; i++)
			{
				(int bit_group, int bit) tuple = OtherButtonIdHelpers.BitFromID((OtherButtonId)(162 + i));
				int item = tuple.bit_group;
				int item2 = tuple.bit;
				item2 = item * 32 + item2;
				OtherButtonMacroSettings otherButtonMacroSettings = _macro_settings[i];
				if (otherButtonMacroSettings.ButtonStateType == OtherButtonMacroSettings.OB_ButtonState.CONT_VIS && otherButtonMacroSettings.ContainerVisibleID == id)
				{
					SetOn(1, item2, visible);
					otherButtonMacroSettings.OnState = visible;
				}
				else
				{
					if (!((otherButtonMacroSettings.ButtonStateType == OtherButtonMacroSettings.OB_ButtonState.CAT && otherButtonMacroSettings.ContainerVisibleID == id && otherButtonMacroSettings.RunStateCommandOnVisible) & visible))
					{
						continue;
					}
					if (_cat_inter == null)
					{
						_cat_inter = new CATScriptInterpreter();
					}
					ScriptResult scriptResult = _cat_inter.run(otherButtonMacroSettings.CatMacro);
					if (!scriptResult.is_valid || scriptResult.commands.Count <= 0)
					{
						continue;
					}
					int num = 0;
					for (; i < otherButtonMacroSettings.CatMacroSend.Length; i++)
					{
						if (!otherButtonMacroSettings.CatMacroSend[num])
						{
							continue;
						}
						foreach (ScriptCommand command in scriptResult.commands)
						{
							if (command.type == ScriptCommandType.CatState)
							{
								MessageQueueSystem.MessageBatch messageBatch = _cat_queue_system.createBatch();
								command.ID = base.ID;
								command.macro = i;
								command.button_index = item2;
								messageBatch.add(command);
								_cat_queue_system.sendBatch(i, messageBatch);
								break;
							}
						}
					}
				}
			}
		}

		private void OnCatState(int queue, Guid id, ScriptCommand sc, string cat_result)
		{
			if (sc.ID != base.ID)
			{
				return;
			}
			lock (_macro_settings_lock)
			{
				if (sc.macro >= 0 && sc.macro <= _macro_settings.Length - 1 && _macro_settings[sc.macro].ButtonStateType == OtherButtonMacroSettings.OB_ButtonState.CAT)
				{
					OtherButtonMacroSettings otherButtonMacroSettings = _macro_settings[sc.macro];
					bool flag = string.Compare(otherButtonMacroSettings.ButtonStateCatReply, cat_result, ignoreCase: true) == 0;
					(int bit_group, int bit) tuple = OtherButtonIdHelpers.BitFromID((OtherButtonId)(162 + sc.macro));
					int item = tuple.bit_group;
					int item2 = tuple.bit;
					item2 = item * 32 + item2;
					SetOn(1, item2, flag);
					_macro_settings[sc.macro].OnState = flag;
					string text = GetText(1, item2);
					if (flag && !string.IsNullOrEmpty(otherButtonMacroSettings.OnText))
					{
						text = otherButtonMacroSettings.OnText;
					}
					else if (!flag && !string.IsNullOrEmpty(otherButtonMacroSettings.OffText))
					{
						text = otherButtonMacroSettings.OffText;
					}
					SetText(1, item2, text);
				}
			}
		}

		public override OtherButtonMacroSettings GetMacroSettings(int macro)
		{
			lock (_macro_settings_lock)
			{
				if (macro < 0 || macro > _macro_settings.Length - 1)
				{
					return null;
				}
				return _macro_settings[macro];
			}
		}

		public override void SetMacroSettings(int macro, OtherButtonMacroSettings settings)
		{
			lock (_macro_settings_lock)
			{
				if (macro < 0 || macro > _macro_settings.Length - 1)
				{
					return;
				}
				_macro_settings[macro] = new OtherButtonMacroSettings(settings);
				if (!_macro_settings[macro].CatMacroSend[0] || string.IsNullOrEmpty(_macro_settings[macro].CatMacro))
				{
					return;
				}
				if (_cat_inter == null)
				{
					_cat_inter = new CATScriptInterpreter();
				}
				ScriptResult scriptResult = _cat_inter.run(_macro_settings[macro].CatMacro);
				if (!scriptResult.is_valid)
				{
					return;
				}
				foreach (ScriptCommand command in scriptResult.commands)
				{
					if (command.type == ScriptCommandType.CatMessageVar)
					{
						_cat_variables.AddOrUpdate(command.variable_name, "", (string a, string b) => "");
					}
				}
			}
		}

		public override void ContainerHiddenByMacro(string id, bool hidden)
		{
			lock (_macro_settings_lock)
			{
				bool flag = !hidden;
				for (OtherButtonId otherButtonId = OtherButtonId._MACRO_0; otherButtonId <= OtherButtonId._MACRO_30; otherButtonId++)
				{
					(int bit_group, int bit) tuple = OtherButtonIdHelpers.BitFromID(otherButtonId);
					int item = tuple.bit_group;
					int item2 = tuple.bit;
					item2 = item * 32 + item2;
					int num = (int)(otherButtonId - 162);
					if (_macro_settings[num].ButtonStateType == OtherButtonMacroSettings.OB_ButtonState.CONT_VIS && _macro_settings[num].ContainerVisibleID == id)
					{
						SetOn(1, item2, flag);
						string text = GetText(1, item2);
						if (flag && !string.IsNullOrEmpty(_macro_settings[num].OnText))
						{
							text = _macro_settings[num].OnText;
						}
						else if (!flag && !string.IsNullOrEmpty(_macro_settings[num].OffText))
						{
							text = _macro_settings[num].OffText;
						}
						SetText(1, item2, text);
					}
				}
			}
		}

		private void updateOn(OtherButtonId id, bool val)
		{
			(int bit_group, int bit) tuple = OtherButtonIdHelpers.BitFromID(id);
			int item = tuple.bit_group;
			int item2 = tuple.bit;
			item2 = item * 32 + item2;
			SetOn(1, item2, val);
		}

		public override void Initialise()
		{
			setupButtons(init: true);
		}

		public override int GetVisibleBits(int bit_group)
		{
			if (bit_group < 0 || bit_group > 11)
			{
				return 0;
			}
			return _visible_bits[bit_group];
		}

		public override void SetVisibleBits(int bit_group, int bit_field)
		{
			if (bit_group >= 0 && bit_group <= 11)
			{
				_visible_bits[bit_group] = bit_field;
				setupButtons();
			}
		}

		private bool isVisible(int bit_group, int bit)
		{
			if (bit_group < 0 || bit_group > 11)
			{
				return false;
			}
			if (bit < 0 || bit > 30)
			{
				return false;
			}
			return (_visible_bits[bit_group] & (1 << bit)) != 0;
		}

		private bool try_index_from_group_bit(int bit_group, int bit, out int index)
		{
			if (bit_group < 0 || bit_group > 11 || bit < 0 || bit > 30)
			{
				index = -1;
				return false;
			}
			index = bit_group * 32 + bit;
			return true;
		}

		private void setupButtons(bool init = false)
		{
			if (!base.RebuildButtons)
			{
				return;
			}
			_has_macro_buttons = false;
			lock (_process_in_update_buttons_lock)
			{
				_process_in_update_buttons.Clear();
			}
			for (int i = 0; i < base.Buttons; i++)
			{
				int num = i % 32;
				int bit_group = i / 32;
				OtherButtonId otherButtonId = OtherButtonIdHelpers.BitToID(bit_group, num);
				if (num == 32 || otherButtonId == OtherButtonId.UNKNOWN || !isVisible(bit_group, num))
				{
					SetVisible(1, i, enabled: false);
					continue;
				}
				bool flag = true;
				bool enabled = isVisible(bit_group, num);
				bool flag2 = otherButtonId >= OtherButtonId._MACRO_0 && otherButtonId <= OtherButtonId._MACRO_30;
				int num2 = (int)(otherButtonId - 162);
				string text;
				switch (otherButtonId)
				{
				case OtherButtonId.TUN:
				case OtherButtonId.MOX:
				case OtherButtonId.TWOTON:
					lock (_process_in_update_buttons_lock)
					{
						_process_in_update_buttons[otherButtonId] = i;
					}
					text = OtherButtonIdHelpers.BitToText(bit_group, num);
					flag = _owningmeter.Power;
					break;
				case OtherButtonId.NR:
				{
					int selectedNR = _console.GetSelectedNR(_owningmeter.RX);
					text = ((selectedNR > 1) ? ("NR" + selectedNR) : "NR");
					break;
				}
				case OtherButtonId.NB:
				{
					int selectedNB = _console.GetSelectedNB(_owningmeter.RX);
					text = ((selectedNB > 1) ? ("NB" + selectedNB) : "NB");
					break;
				}
				case OtherButtonId.SPLT:
					text = ((!_owningmeter.RX2Enabled) ? ((!_owningmeter.QuickSplitEnabled) ? "SPLT" : "QSPL") : "SPLT");
					break;
				case OtherButtonId.XPA:
					text = OtherButtonIdHelpers.BitToText(bit_group, num);
					enabled = _console.GetXPAStatus().in_use && isVisible(bit_group, num);
					break;
				case OtherButtonId.SQL:
					text = ((_owningmeter.SqlMode != SquelchState.VSQL) ? "SQL" : "VSQL");
					break;
				case OtherButtonId.CWX_KEY:
				case OtherButtonId.CWX_STOP:
				case OtherButtonId.CWX_F1:
				case OtherButtonId.CWX_F2:
				case OtherButtonId.CWX_F3:
				case OtherButtonId.CWX_F4:
				case OtherButtonId.CWX_F5:
				case OtherButtonId.CWX_F6:
				case OtherButtonId.CWX_F7:
				case OtherButtonId.CWX_F8:
				case OtherButtonId.CWX_F9:
					flag = _owningmeter.CWXShown;
					text = OtherButtonIdHelpers.BitToText(bit_group, num);
					break;
				case OtherButtonId.REC:
				case OtherButtonId.PLAY:
				case OtherButtonId.WAVE_RECORD:
					flag = GetEnabled(0, i) && _owningmeter.Power;
					text = OtherButtonIdHelpers.BitToText(bit_group, num);
					break;
				default:
					text = OtherButtonIdHelpers.BitToText(bit_group, num);
					break;
				}
				OtherButtonMacroSettings otherButtonMacroSettings = null;
				if (flag2)
				{
					lock (_macro_settings_lock)
					{
						otherButtonMacroSettings = new OtherButtonMacroSettings(_macro_settings[num2]);
					}
					bool flag3 = false;
					switch (otherButtonMacroSettings.ButtonStateType)
					{
					case OtherButtonMacroSettings.OB_ButtonState.OFF:
						flag3 = false;
						break;
					case OtherButtonMacroSettings.OB_ButtonState.ON:
						flag3 = true;
						break;
					case OtherButtonMacroSettings.OB_ButtonState.TOGGLE:
						flag3 = otherButtonMacroSettings.OnState;
						break;
					case OtherButtonMacroSettings.OB_ButtonState.LED:
						flag3 = false;
						break;
					case OtherButtonMacroSettings.OB_ButtonState.CONT_VIS:
						flag3 = !ContainerIsHidden(otherButtonMacroSettings.ContainerVisibleID);
						break;
					case OtherButtonMacroSettings.OB_ButtonState.CAT:
						flag3 = otherButtonMacroSettings.OnState;
						break;
					}
					SetOn(1, i, flag3);
					otherButtonMacroSettings.OnState = flag3;
					if (flag3 && !string.IsNullOrEmpty(otherButtonMacroSettings.OnText))
					{
						text = otherButtonMacroSettings.OnText;
					}
					else if (!flag3 && !string.IsNullOrEmpty(otherButtonMacroSettings.OffText))
					{
						text = otherButtonMacroSettings.OffText;
					}
				}
				if (base.UseIcons)
				{
					var (text2, text3) = OtherButtonIdHelpers.BitToIcon(bit_group, num);
					if (!string.IsNullOrEmpty(text2))
					{
						SetIconOn(1, i, text2);
						SetIconOff(1, i, text3);
						SetUseIcon(1, i, icon: true);
					}
					else
					{
						SetUseIcon(1, i, icon: false);
					}
				}
				else
				{
					SetUseIcon(1, i, icon: false);
				}
				SetText(1, i, text);
				System.Drawing.Color fontColour = GetFontColour(0, i);
				System.Drawing.Color onColour = GetOnColour(0, i);
				System.Drawing.Color offColour = GetOffColour(0, i);
				if (flag)
				{
					SetFontColour(1, i, fontColour);
					SetOnColour(1, i, onColour);
					SetOffColour(1, i, offColour);
				}
				else
				{
					SetFontColour(1, i, System.Drawing.Color.FromArgb(255, (int)((float)(int)fontColour.R * 0.3f), (int)((float)(int)fontColour.G * 0.3f), (int)((float)(int)fontColour.B * 0.3f)));
					SetOnColour(1, i, System.Drawing.Color.FromArgb(255, (int)((float)(int)onColour.R * 0.3f), (int)((float)(int)onColour.G * 0.3f), (int)((float)(int)onColour.B * 0.3f)));
					SetOffColour(1, i, System.Drawing.Color.FromArgb(255, (int)((float)(int)offColour.R * 0.3f), (int)((float)(int)offColour.G * 0.3f), (int)((float)(int)offColour.B * 0.3f)));
				}
				SetFontFamily(1, i, GetFontFamily(0, i));
				SetFontSize(1, i, GetFontSize(0, i));
				SetFontStyle(1, i, GetFontStyle(0, i));
				SetUseIndicator(1, i, GetUseIndicator(0, i));
				SetIndicatorWidth(1, i, GetIndicatorWidth(0, i));
				SetEnabled(1, i, flag);
				SetVisible(1, i, enabled);
				if (init && !flag2)
				{
					SetOn(1, i, _console.GetOtherButtonState(otherButtonId, _owningmeter.RX));
				}
				SetOn(1, i, GetOn(1, i));
				SetFillColour(1, i, GetFillColour(0, i));
				SetHoverColour(1, i, GetHoverColour(0, i));
				SetBorderColour(1, i, GetBorderColour(0, i));
				SetClickColour(1, i, GetClickColour(0, i));
				SetUseOffColour(1, i, GetUseOffColour(0, i));
				SetIndicatorType(1, i, GetIndicatorType(0, i));
				if (flag2)
				{
					_has_macro_buttons |= isVisible(bit_group, num);
					lock (_macro_settings_lock)
					{
						_macro_settings[num2] = new OtherButtonMacroSettings(otherButtonMacroSettings);
					}
				}
			}
			int num3 = 0;
			for (int j = 0; j < base.Buttons; j++)
			{
				if (GetVisible(1, j))
				{
					num3++;
				}
			}
			int num4 = num3 / Columns;
			if (num3 % Columns > 0)
			{
				num4++;
			}
			_ = Border / 2f;
			_ = 0.96f / (float)Columns;
			_ = Margin;
			_ = Border;
			float num5 = 0.96f / (float)Columns * HeightRatio * (float)num4;
			base.Size = new SizeF(base.Size.Width, num5);
			float num6 = 0.04f;
			float num7 = 0.05f;
			_ig.Size = new SizeF(_ig.Size.Width, num5 + (num6 - num7 * 0.75f));
			_owningmeter.Rebuild();
		}

		private void setupClick(bool setup)
		{
			if (setup)
			{
				_click_timer = new System.Timers.Timer(100.0);
				_click_timer.Elapsed += delegate
				{
					_click_highlight = false;
					if (_click_timer != null)
					{
						_click_timer.Stop();
						_click_timer.Dispose();
						_click_timer = null;
					}
				};
				_click_timer.AutoReset = false;
				_click_timer.Start();
			}
			else
			{
				if (_click_timer != null)
				{
					_click_timer.Stop();
					_click_timer.Dispose();
					_click_timer = null;
				}
				_click_highlight = true;
			}
		}

		public override void MouseDown(MouseEventArgs e)
		{
			if ((base.FadeOnRx && !_owningmeter.MOX) || (base.FadeOnTx && _owningmeter.MOX))
			{
				return;
			}
			int buttonIndex = base.ButtonIndex;
			if (buttonIndex == -1)
			{
				return;
			}
			_last_draged_to = -1;
			if (Common.AltlKeyDown)
			{
				_dragging_index = buttonIndex;
				return;
			}
			_dragging_index = -1;
			if (GetEnabled(1, buttonIndex))
			{
				setupClick(setup: false);
			}
		}

		public override void MouseUp(MouseEventArgs e)
		{
			if ((base.FadeOnRx && !_owningmeter.MOX) || (base.FadeOnTx && _owningmeter.MOX) || _console == null)
			{
				return;
			}
			if (_dragging_index != -1)
			{
				if (_last_draged_to != -1 && _dragging_index != _last_draged_to)
				{
					lock (_map_lock)
					{
						if (Common.ShiftKeyDown)
						{
							short num = _map[_last_draged_to];
							_map[_last_draged_to] = _map[_dragging_index];
							_map[_dragging_index] = num;
						}
						else
						{
							short num2 = _map[_dragging_index];
							if (_dragging_index < _last_draged_to)
							{
								Array.Copy(_map, _dragging_index + 1, _map, _dragging_index, _last_draged_to - _dragging_index);
								_map[_last_draged_to] = num2;
							}
							else
							{
								Array.Copy(_map, _last_draged_to, _map, _last_draged_to + 1, _dragging_index - _last_draged_to);
								_map[_last_draged_to] = num2;
							}
						}
						_map_changed = true;
					}
					setupButtons();
				}
				_dragging_index = -1;
				_last_draged_to = -1;
				return;
			}
			setupClick(setup: true);
			int index = base.ButtonIndex;
			if (index == -1)
			{
				return;
			}
			lock (_map_lock)
			{
				index = _map[index];
			}
			if (!GetEnabled(1, index))
			{
				return;
			}
			int num3 = index % 32;
			int bit_group = index / 32;
			if (num3 == 31)
			{
				return;
			}
			OtherButtonId id = OtherButtonIdHelpers.BitToID(bit_group, num3);
			if (id == OtherButtonId.UNKNOWN)
			{
				return;
			}
			if (id >= OtherButtonId._MACRO_0 && id <= OtherButtonId._MACRO_30)
			{
				int macro = (int)(id - 162);
				handleMacroButtonPress(macro, index);
			}
			else if (!_console.BusyDoingOtherbuttonAction)
			{
				_console.BeginInvoke((MethodInvoker)delegate
				{
					_console.DoOtherButtonAction(_owningmeter.RX, id, e.Button, force: false, GetOn(1, index));
				});
			}
		}

		private void handleMacroButtonPress(int macro, int index)
		{
			if (macro < 0 || macro > _macro_settings.Length - 1)
			{
				return;
			}
			OtherButtonMacroSettings otherButtonMacroSettings;
			lock (_macro_settings)
			{
				otherButtonMacroSettings = new OtherButtonMacroSettings(_macro_settings[macro]);
			}
			if (otherButtonMacroSettings.ClosesParent)
			{
				HiddenByMacro(_owningmeter.ID, hide: true);
			}
			if (otherButtonMacroSettings.ButtonStateType == OtherButtonMacroSettings.OB_ButtonState.TOGGLE)
			{
				bool flag = !GetOn(1, index);
				SetOn(1, index, flag);
				_macro_settings[macro].OnState = flag;
				string text = GetText(1, index);
				if (flag && !string.IsNullOrEmpty(_macro_settings[macro].OnText))
				{
					text = _macro_settings[macro].OnText;
				}
				else if (!flag && !string.IsNullOrEmpty(_macro_settings[macro].OffText))
				{
					text = _macro_settings[macro].OffText;
				}
				SetText(1, index, text);
			}
			for (int i = 0; i <= 3; i++)
			{
				if (otherButtonMacroSettings.ClosesContainer[i] && otherButtonMacroSettings.OpensContainer[i] && otherButtonMacroSettings.CloseContainerID[i] == otherButtonMacroSettings.OpenContainerID[i])
				{
					bool flag2 = ContainerIsHidden(otherButtonMacroSettings.CloseContainerID[i]);
					HiddenByMacro(otherButtonMacroSettings.CloseContainerID[i], !flag2);
				}
				else
				{
					if (otherButtonMacroSettings.OpensContainer[i])
					{
						string sId_copy_size = ((otherButtonMacroSettings.OpenUsesLocation[i] && !string.IsNullOrEmpty(otherButtonMacroSettings.CloseContainerID[i])) ? otherButtonMacroSettings.CloseContainerID[i] : null);
						HiddenByMacro(otherButtonMacroSettings.OpenContainerID[i], hide: false, sId_copy_size);
					}
					if (otherButtonMacroSettings.ClosesContainer[i])
					{
						HiddenByMacro(otherButtonMacroSettings.CloseContainerID[i], hide: true);
					}
				}
				if (!otherButtonMacroSettings.SendsViaMMIO[i] || string.IsNullOrEmpty(otherButtonMacroSettings.MMICFourChar[i]))
				{
					continue;
				}
				Guid guid = MultiMeterIO.GuidfromFourChar(otherButtonMacroSettings.MMICFourChar[i]);
				if (guid != Guid.Empty)
				{
					if (GetOn(1, index))
					{
						_text_overlay_to_use_parser.Text1 = otherButtonMacroSettings.MMIOMessageON[i];
					}
					else
					{
						_text_overlay_to_use_parser.Text1 = otherButtonMacroSettings.MMIOMessageOFF[i];
					}
					MultiMeterIO.SendDataMMIO(guid, _text_overlay_to_use_parser.ParsedText1);
				}
			}
			if (string.IsNullOrEmpty(otherButtonMacroSettings.CatMacro))
			{
				return;
			}
			if (_cat_inter == null)
			{
				_cat_inter = new CATScriptInterpreter();
			}
			ScriptResult scriptResult = _cat_inter.run(otherButtonMacroSettings.CatMacro);
			if (!scriptResult.is_valid || scriptResult.commands.Count <= 0)
			{
				return;
			}
			for (int j = 0; j < otherButtonMacroSettings.CatMacroSend.Length; j++)
			{
				if (!otherButtonMacroSettings.CatMacroSend[j])
				{
					continue;
				}
				MessageQueueSystem.MessageBatch messageBatch = _cat_queue_system.createBatch();
				foreach (ScriptCommand command in scriptResult.commands)
				{
					command.ID = base.ID;
					command.macro = macro;
					command.button_index = index;
					messageBatch.add(command);
				}
				_cat_queue_system.sendBatch(j, messageBatch);
			}
		}

		public override void MoveButton(int button_index)
		{
			if (button_index != _last_draged_to)
			{
				_last_draged_to = button_index;
			}
		}

		public override void Update(int rx, ref List<Reading> readingsUsed, Dictionary<Reading, object> all_list_item_readings = null)
		{
			lock (_macro_settings_lock)
			{
				for (int i = 0; i < _macro_settings.Length; i++)
				{
					OtherButtonMacroSettings otherButtonMacroSettings = _macro_settings[i];
					if (otherButtonMacroSettings.ButtonStateType != OtherButtonMacroSettings.OB_ButtonState.LED || string.IsNullOrEmpty(otherButtonMacroSettings.LedIndiciatorFourChar))
					{
						continue;
					}
					clsLed ledFrom4Char = GetLedFrom4Char(otherButtonMacroSettings.LedIndiciatorFourChar);
					if (ledFrom4Char != null)
					{
						(int bit_group, int bit) tuple = OtherButtonIdHelpers.BitFromID((OtherButtonId)(162 + i));
						int item = tuple.bit_group;
						int item2 = tuple.bit;
						item2 = item * 32 + item2;
						bool conditionResult = ledFrom4Char.ConditionResult;
						SetOn(1, item2, conditionResult);
						otherButtonMacroSettings.OnState = conditionResult;
						string text = GetText(1, item2);
						if (conditionResult && !string.IsNullOrEmpty(otherButtonMacroSettings.OnText))
						{
							text = otherButtonMacroSettings.OnText;
						}
						else if (!conditionResult && !string.IsNullOrEmpty(otherButtonMacroSettings.OffText))
						{
							text = otherButtonMacroSettings.OffText;
						}
						SetText(1, item2, text);
					}
				}
			}
			lock (_process_in_update_buttons_lock)
			{
				foreach (KeyValuePair<OtherButtonId, int> process_in_update_button in _process_in_update_buttons)
				{
					if (GetEnabled(1, process_in_update_button.Value) != _owningmeter.Power)
					{
						int value = process_in_update_button.Value;
						System.Drawing.Color fontColour = GetFontColour(0, value);
						System.Drawing.Color onColour = GetOnColour(0, value);
						System.Drawing.Color offColour = GetOffColour(0, value);
						if (_owningmeter.Power)
						{
							SetFontColour(1, value, fontColour);
							SetOnColour(1, value, onColour);
							SetOffColour(1, value, offColour);
						}
						else
						{
							SetFontColour(1, value, System.Drawing.Color.FromArgb(255, (int)((float)(int)fontColour.R * 0.3f), (int)((float)(int)fontColour.G * 0.3f), (int)((float)(int)fontColour.B * 0.3f)));
							SetOnColour(1, value, System.Drawing.Color.FromArgb(255, (int)((float)(int)onColour.R * 0.3f), (int)((float)(int)onColour.G * 0.3f), (int)((float)(int)onColour.B * 0.3f)));
							SetOffColour(1, value, System.Drawing.Color.FromArgb(255, (int)((float)(int)offColour.R * 0.3f), (int)((float)(int)offColour.G * 0.3f), (int)((float)(int)offColour.B * 0.3f)));
						}
						SetEnabled(1, value, _owningmeter.Power);
					}
				}
			}
		}
	}

	internal class clsAntennaButtonBox : clsButtonBox
