		private void setupButtons()
		{
			if (!base.RebuildButtons || _rx1_band == Band.FIRST || _tx_band == Band.FIRST)
			{
				return;
			}
			for (int i = 0; i < base.Buttons; i++)
			{
				SetText(1, i, GetText(0, i));
				SetFontColour(1, i, GetFontColour(0, i));
				SetFontFamily(1, i, GetFontFamily(0, i));
				SetFontSize(1, i, GetFontSize(0, i));
				SetFontStyle(1, i, GetFontStyle(0, i));
				SetUseIndicator(1, i, GetUseIndicator(0, i));
				SetOnColour(1, i, GetOnColour(0, i));
				SetOffColour(1, i, GetOffColour(0, i));
				SetIndicatorWidth(1, i, GetIndicatorWidth(0, i));
				SetEnabled(1, i, enabled: true);
				SetVisible(1, i, GetVisible(0, i));
				SetOn(1, i, on: false);
				SetFillColour(1, i, GetFillColour(0, i));
				SetHoverColour(1, i, GetHoverColour(0, i));
				SetBorderColour(1, i, GetBorderColour(0, i));
				SetClickColour(1, i, GetClickColour(0, i));
				SetUseOffColour(1, i, GetUseOffColour(0, i));
				SetIndicatorType(1, i, GetIndicatorType(0, i));
			}
			Band band = _rx1_band;
			Band b = _tx_band;
			bool flag = band >= Band.VHF0 && band <= Band.VHF13;
			bool flag2 = false;
			if (flag)
			{
				band = _console.GetTransverterTranslatedRXBand(_vfoa_freq);
				flag2 = GetRXAuxState(band, 2);
				b = _console.GetTransverterTranslatedRXBand(_tx_freq);
			}
			bool flag3 = !flag && (GetRXAuxState(band, 0) || GetRXAuxState(band, 1));
			SetText(1, 0, "Rx Ant 1");
			SetFontColour(1, 0, System.Drawing.Color.LimeGreen);
			if (!flag3 && !flag2)
			{
				SetOn(1, 0, GetRXAntState(band, 0));
			}
			SetText(1, 1, "Rx Ant 2");
			SetFontColour(1, 1, System.Drawing.Color.LimeGreen);
			if (!flag3 && !flag2)
			{
				SetOn(1, 1, GetRXAntState(band, 1));
			}
			SetText(1, 2, "Rx Ant 3");
			SetFontColour(1, 2, System.Drawing.Color.LimeGreen);
			if (!flag3 && !flag2)
			{
				SetOn(1, 2, GetRXAntState(band, 2));
			}
			SetText(1, 3, formatAux(GetRXAuxName(0)));
			SetFontColour(1, 3, System.Drawing.Color.Orange);
			if (!flag2 & flag3)
			{
				SetOn(1, 3, GetRXAuxState(band, 0));
			}
			SetText(1, 4, formatAux(GetRXAuxName(1)));
			SetFontColour(1, 4, System.Drawing.Color.Orange);
			if (!flag2 & flag3)
			{
				SetOn(1, 4, GetRXAuxState(band, 1));
			}
			SetText(1, 5, formatAux(GetRXAuxName(2)));
			SetFontColour(1, 5, System.Drawing.Color.Orange);
			if (!flag3 & flag)
			{
				SetOn(1, 5, GetRXAuxState(band, 2));
			}
			int rXAnt = GetRXAnt(band, flag);
			int tXAnt = GetTXAnt(b);
			int rXAnt2 = GetRXAnt(b, xvtr: false);
			SetText(1, 6, "Tx Ant 1");
			if (rXAnt2 == 0 && GetNoTX(0))
			{
				SetFontColour(1, 6, System.Drawing.Color.Gray);
			}
			else
			{
				SetFontColour(1, 6, System.Drawing.Color.Red);
				SetOn(1, 6, GetTXAntState(b, 0));
			}
			SetText(1, 7, "Tx Ant 2");
			if (rXAnt2 == 1 && GetNoTX(1))
			{
				SetFontColour(1, 7, System.Drawing.Color.Gray);
			}
			else
			{
				SetFontColour(1, 7, System.Drawing.Color.Red);
				SetOn(1, 7, GetTXAntState(b, 1));
			}
			SetText(1, 8, "Tx Ant 3");
			if (rXAnt2 == 2 && GetNoTX(2))
			{
				SetFontColour(1, 8, System.Drawing.Color.Gray);
			}
			else
			{
				SetFontColour(1, 8, System.Drawing.Color.Red);
				SetOn(1, 8, GetTXAntState(b, 2));
			}
			if (((rXAnt == tXAnt) | flag) || GetNoTX(tXAnt) || rXAnt > 4)
			{
				SetText(1, 9, "Rx Ant");
				SetFontColour(1, 9, System.Drawing.Color.Gray);
			}
			else if (_rxtx_swap)
			{
				SetText(1, 9, "Tx Ant");
				SetOn(1, 9, on: true);
				SetFontColour(1, 9, System.Drawing.Color.Yellow);
			}
			else
			{
				SetText(1, 9, "Rx Ant");
				SetOn(1, 9, on: false);
				SetFontColour(1, 9, System.Drawing.Color.LimeGreen);
			}
			int num = 0;
			for (int j = 0; j < base.Buttons; j++)
			{
				if (GetVisible(1, j))
				{
					num++;
				}
			}
			int num2 = num / Columns;
			if (num % Columns > 0)
			{
				num2++;
			}
			_ = Border / 2f;
			_ = 0.96f / (float)Columns;
			_ = Margin;
			_ = Border;
			float num3 = 0.96f / (float)Columns * HeightRatio * (float)num2;
			base.Size = new SizeF(base.Size.Width, num3);
			float num4 = 0.04f;
			float num5 = 0.05f;
			_ig.Size = new SizeF(_ig.Size.Width, num3 + (num4 - num5 * 0.75f));
			_owningmeter.Rebuild();
		}

		private string formatAux(string name)
		{
			if (name.Length < 2)
			{
				return "";
			}
			string text = name.ToLower();
			text = char.ToUpper(text[0]) + text.Substring(1);
			if (text == "Byps")
			{
				text = "Bypass";
			}
			return text;
		}

		public void AntennasChanged(Band rx1_band, Band tx_band, double vfoa_freq, double tx_freq, int rxtx_swap)
		{
			bool flag = false;
			bool flag2 = rx1_band == Band.FIRST && tx_band == Band.FIRST && vfoa_freq == -1.0 && tx_freq == -1.0;
			bool num = (rx1_band >= Band.B160M && rx1_band <= Band.B6M) || (rx1_band >= Band.VHF0 && rx1_band <= Band.VHF13);
			bool flag3 = (tx_band >= Band.B160M && tx_band <= Band.B6M) || (tx_band >= Band.VHF0 && tx_band <= Band.VHF13);
			flag = num | flag3 | flag2;
			if (!num && vfoa_freq != -1.0)
			{
				rx1_band = Alex.AntBandFromFreq(vfoa_freq);
				flag = true;
			}
			if (!flag3 && tx_freq != -1.0)
			{
				tx_band = Alex.AntBandFromFreq(tx_freq);
				flag = true;
			}
			if (flag)
			{
				if (rx1_band != Band.FIRST && rx1_band != _rx1_band)
				{
					_rx1_band = rx1_band;
				}
				if (tx_band != Band.FIRST && tx_band != _tx_band)
				{
					_tx_band = tx_band;
				}
				if (vfoa_freq > -1.0 && vfoa_freq != _vfoa_freq)
				{
					_vfoa_freq = vfoa_freq;
				}
				if (tx_freq > -1.0 && tx_freq != _tx_freq)
				{
					_tx_freq = tx_freq;
				}
				int num2 = ((!_rxtx_swap) ? 1 : 2);
				if (rxtx_swap > 0 && rxtx_swap != num2)
				{
					_rxtx_swap = rxtx_swap == 2;
				}
			}
			lock (_timerLock)
			{
				if (_timer == null)
				{
					_timer = new System.Threading.Timer(delegate
					{
						setupButtons();
					}, null, 250, -1);
				}
				else
				{
					_timer.Change(100, -1);
				}
			}
		}

		private void setupClick(bool setup)
		{
			if (setup)
			{
				_click_timer = new System.Timers.Timer(100.0);
				_click_timer.Elapsed += delegate
				{
					_click_highlight = false;
					if (_click_timer != null)
					{
						_click_timer.Stop();
						_click_timer.Dispose();
						_click_timer = null;
					}
				};
				_click_timer.AutoReset = false;
				_click_timer.Start();
			}
			else
			{
				if (_click_timer != null)
				{
					_click_timer.Stop();
					_click_timer.Dispose();
					_click_timer = null;
				}
				_click_highlight = true;
			}
		}

		public override void MouseDown(MouseEventArgs e)
		{
			if ((!base.FadeOnRx || _owningmeter.MOX) && (!base.FadeOnTx || !_owningmeter.MOX))
			{
				int buttonIndex = base.ButtonIndex;
				if (buttonIndex != -1 && GetEnabled(1, buttonIndex))
				{
					setupClick(setup: false);
				}
			}
		}

		public override void MouseUp(MouseEventArgs e)
		{
			if ((base.FadeOnRx && !_owningmeter.MOX) || (base.FadeOnTx && _owningmeter.MOX) || _console == null || _console.IsSetupFormNull)
			{
				return;
			}
			int buttonIndex = base.ButtonIndex;
			if (buttonIndex != -1)
			{
				setupClick(setup: true);
				if (buttonIndex >= 0 && buttonIndex <= 2)
				{
					setRXAntenna(buttonIndex, _rx1_band);
				}
				if (buttonIndex >= 3 && buttonIndex <= 4)
				{
					setAuxAntenna(buttonIndex, _rx1_band, buttonIndex == 3, buttonIndex == 4, buttonIndex == 5);
				}
				if (buttonIndex >= 6 && buttonIndex <= 8)
				{
					setTXAntenna(buttonIndex - 6, _tx_band);
				}
				if (buttonIndex == 9)
				{
					toggleTxRxAnt();
				}
			}
		}

		private void toggleTxRxAnt()
		{
			if (_console != null && !_console.IsSetupFormNull)
			{
				_console.BeginInvoke((MethodInvoker)delegate
				{
					_console.ToggleRxTxAnt();
				});
			}
		}

		private void setRXAntenna(int antenna, Band b)
		{
			if (_console != null && !_console.IsSetupFormNull)
			{
				_console.BeginInvoke((MethodInvoker)delegate
				{
					_console.SetupForm.SetRXAntenna(antenna + 1, b);
				});
			}
		}

		private void setAuxAntenna(int antenna, Band b, bool byp, bool ext1, bool xvtr)
		{
			if (_console != null && !_console.IsSetupFormNull)
			{
				_console.BeginInvoke((MethodInvoker)delegate
				{
					_console.SetupForm.SetAuxAntenna(antenna + 1, b, byp, ext1);
				});
			}
		}

		private void setTXAntenna(int antenna, Band b)
		{
			if (_console != null && !_console.IsSetupFormNull)
			{
				_console.BeginInvoke((MethodInvoker)delegate
				{
					_console.SetupForm.SetTXAntenna(antenna + 1, b);
				});
			}
		}
	}

	internal class clsModeButtonBox : clsButtonBox
	{
		private DSPMode _mode;

		private clsMeter _owningmeter;

		private bool _click_highlight;

		private System.Timers.Timer _click_timer;

		public override bool ClickHighlight => _click_highlight;

		public override bool MouseEntered
		{
			get
			{
				return base.MouseEntered;
			}
			set
			{
				if (!value && _click_highlight)
				{
					if (_click_timer != null)
					{
						_click_timer.Stop();
						_click_timer.Dispose();
					}
					_click_highlight = false;
				}
				base.MouseEntered = value;
			}
		}

		public override int Columns
		{
			get
			{
				return base.Columns;
			}
			set
			{
				base.Columns = value;
				setupButtons();
			}
		}

		public override float Border
		{
			get
			{
				return base.Border;
			}
			set
			{
				base.Border = value;
				setupButtons();
			}
		}

		public override float Margin
		{
			get
			{
				return base.Margin;
			}
			set
			{
				base.Margin = value;
				setupButtons();
			}
		}

		public override float Radius
		{
			get
			{
				return base.Radius;
			}
			set
			{
				base.Radius = value;
				setupButtons();
			}
		}

		public override float HeightRatio
		{
			get
			{
				return base.HeightRatio;
			}
			set
			{
				base.HeightRatio = value;
				setupButtons();
			}
		}

		public clsModeButtonBox(clsMeter owningmeter)
		{
			_owningmeter = owningmeter;
			base.ItemType = MeterItemType.MODE_BUTTONS;
			Initialise();
		}

		public override void Initialise()
		{
			_click_highlight = false;
			if (_owningmeter.RX == 1)
			{
				_mode = _owningmeter.ModeVfoA;
			}
			else if (_owningmeter.RX == 2)
			{
				_mode = _owningmeter.ModeVfoB;
			}
			base.Buttons = 12;
			setupButtons();
		}

		public override void ModeChanged(DSPMode oldMode, DSPMode newMode)
		{
			DSPMode mode = _mode;
			_mode = newMode;
			int mode2 = (int)_mode;
			int button = (int)mode;
			SetOn(1, button, on: false);
			SetOn(1, mode2, on: true);
		}

		private void setupButtons()
		{
			if (!base.RebuildButtons)
			{
				return;
			}
			for (int i = 0; i < base.Buttons; i++)
			{
				SetText(1, i, GetText(0, i));
				SetFontColour(1, i, GetFontColour(0, i));
				SetFontFamily(1, i, GetFontFamily(0, i));
				SetFontSize(1, i, GetFontSize(0, i));
				SetFontStyle(1, i, GetFontStyle(0, i));
				SetUseIndicator(1, i, GetUseIndicator(0, i));
				SetOnColour(1, i, GetOnColour(0, i));
				SetOffColour(1, i, GetOffColour(0, i));
				SetIndicatorWidth(1, i, GetIndicatorWidth(0, i));
				SetEnabled(1, i, enabled: true);
				SetVisible(1, i, enabled: true);
				SetOn(1, i, on: false);
				SetFillColour(1, i, GetFillColour(0, i));
				SetHoverColour(1, i, GetHoverColour(0, i));
				SetBorderColour(1, i, GetBorderColour(0, i));
				SetClickColour(1, i, GetClickColour(0, i));
				SetUseOffColour(1, i, GetUseOffColour(0, i));
				SetIndicatorType(1, i, GetIndicatorType(0, i));
			}
			int num = 0;
			System.Drawing.Color fontColour = GetFontColour(0, 0);
			int num2 = 11 - num + 1;
			for (int j = 0; j < base.Buttons; j++)
			{
				if (j < num2)
				{
					DSPMode dSPMode = (DSPMode)(num + j);
					string text = dSPMode.ToString();
					SetText(1, j, text);
					if (GetEnabled(1, j))
					{
						SetFontColour(1, j, fontColour);
					}
					else
					{
						SetFontColour(1, j, System.Drawing.Color.FromArgb(255, (int)((float)(int)fontColour.R * 0.3f), (int)((float)(int)fontColour.G * 0.3f), (int)((float)(int)fontColour.B * 0.3f)));
					}
					SetFontSize(1, j, 18f);
					SetOn(1, j, dSPMode == _mode);
				}
			}
			int num3 = base.Buttons / Columns;
			if (base.Buttons % Columns > 0)
			{
				num3++;
			}
			_ = Border / 2f;
			_ = 0.96f / (float)Columns;
			_ = Margin;
			_ = Border;
			float height = 0.96f / (float)Columns * HeightRatio * (float)num3;
			base.Size = new SizeF(base.Size.Width, height);
		}

		private void setupClick(bool setup)
		{
			if (setup)
			{
				_click_timer = new System.Timers.Timer(100.0);
				_click_timer.Elapsed += delegate
				{
					_click_highlight = false;
					if (_click_timer != null)
					{
						_click_timer.Stop();
						_click_timer.Dispose();
						_click_timer = null;
					}
				};
				_click_timer.AutoReset = false;
				_click_timer.Start();
			}
			else
			{
				if (_click_timer != null)
				{
					_click_timer.Stop();
					_click_timer.Dispose();
					_click_timer = null;
				}
				_click_highlight = true;
			}
		}

		public override void MouseDown(MouseEventArgs e)
		{
			if ((!base.FadeOnRx || _owningmeter.MOX) && (!base.FadeOnTx || !_owningmeter.MOX))
			{
				int buttonIndex = base.ButtonIndex;
				if (buttonIndex != -1 && GetEnabled(1, buttonIndex))
				{
					setupClick(setup: false);
				}
			}
		}

		public override void MouseUp(MouseEventArgs e)
		{
			if ((base.FadeOnRx && !_owningmeter.MOX) || (base.FadeOnTx && _owningmeter.MOX) || _console == null)
			{
				return;
			}
			int buttonIndex = base.ButtonIndex;
			if (buttonIndex != -1)
			{
				setupClick(setup: true);
				if (_owningmeter.RX != 2 || _owningmeter.RX2Enabled)
				{
					DSPMode mode = (DSPMode)buttonIndex;
					setMode(mode);
				}
			}
		}

		private bool abortForLockedVFO()
		{
			bool result = false;
			if (_owningmeter.RX == 1)
			{
				return _owningmeter.VFOALock;
			}
			if (_owningmeter.RX == 2)
			{
				return _owningmeter.VFOBLock;
			}
			return result;
		}

		private void setMode(DSPMode m)
		{
			if (abortForLockedVFO() || m == DSPMode.FIRST)
			{
				return;
			}
			if (_owningmeter.RX == 2)
			{
				_console.BeginInvoke((MethodInvoker)delegate
				{
					_console.RX2DSPMode = m;
				});
			}
			else
			{
				_console.BeginInvoke((MethodInvoker)delegate
				{
					_console.RX1DSPMode = m;
				});
			}
		}
	}

