			}
			set
			{
				if (value)
				{
					clearRunningRepeat(-1, force: true);
				}
			}
		}

		public string[] SlotFilepaths
		{
			get
			{
				return _slot_filepath;
			}
			set
			{
				if (value == null)
				{
					for (int i = 0; i < base.Buttons; i++)
					{
						_slot_filepath[i] = null;
						_slot_duration_seconds[i] = 0f;
						_activate_time[i] = DateTime.MinValue;
					}
				}
				else
				{
					int num = value.Length;
					for (int j = 0; j < base.Buttons; j++)
					{
						if (j < num)
						{
							_slot_filepath[j] = value[j];
							_slot_duration_seconds[j] = 0f;
							_activate_time[j] = DateTime.MinValue;
						}
						else
						{
							_slot_filepath[j] = null;
							_slot_duration_seconds[j] = 0f;
							_activate_time[j] = DateTime.MinValue;
						}
					}
				}
				for (int k = 0; k < base.Buttons; k++)
				{
					if (string.IsNullOrEmpty(_slot_filepath[k]))
					{
						continue;
					}
					if (_console.ARP.GetJSONDetailsFromFile(_slot_filepath[k], out var json_data))
					{
						if (json_data != null)
						{
							_slot_duration_seconds[k] = (float)json_data.play_duration_seconds;
						}
					}
					else
					{
						_slot_filepath[k] = null;
					}
				}
			}
		}

		public bool HasLockedSlots
		{
			get
			{
				bool result = false;
				for (int i = 0; i < _slots; i++)
				{
					if (_slot_locked[i])
					{
						result = true;
						break;
					}
				}
				return result;
			}
		}

		public string UniqueID
		{
