				lock (_map_lock)
				{
					return _map;
				}
			}
			set
			{
				lock (_map_lock)
				{
					if (value == null)
					{
						_map = new short[base.Buttons];
						for (short num = 0; num < _map.Length; num++)
						{
							_map[num] = num;
						}
					}
					else
					{
						int length = Math.Min(value.Length, _map.Length);
						Array.Copy(value, _map, length);
					}
					_map_changed = true;
				}
				setupButtons();
			}
		}

		public override short[] MapCopy
		{
			get
			{
				lock (_map_lock)
				{
					if (_map_changed)
					{
						lock (_map_copy)
						{
							_map_copy = new short[_map.Length];
							Array.Copy(_map, _map_copy, _map.Length);
						}
						_map_changed = false;
					}
				}
				lock (_map_copy)
				{
					return _map_copy;
