		public clsVoiceRecordPlay(clsMeter owningmeter, clsItemGroup ig)
		{
			if (!Guid.TryParse(ig.ID, out var result))
			{
				result = Guid.NewGuid();
			}
			_four_char = Common.FourChar("ledindicator", 0, result);
			_alt_pressed = Common.AltlKeyDown;
			_ctrl_pressed = Common.CtrlKeyDown;
			_shift_pressed = Common.ShiftKeyDown;
			_ig = ig;
			_owningmeter = owningmeter;
			base.ItemType = MeterItemType.VOICE_RECORD_PLAY_BUTTONS;
			_unique_id = Guid.NewGuid().ToString();
			base.Buttons = 64;
			_slots = 8;
			_map = new short[base.Buttons];
			_map_copy = new short[base.Buttons];
			for (short num = 0; num < _map.Length; num++)
			{
				_map[num] = num;
				_map_copy[num] = num;
			}
			_map_changed = false;
			_dragging_index = -1;
			_last_draged_to = -1;
			_slot_playing = -1;
			_slot_recording = -1;
			_mode_record = false;
			_wdsp = true;
			_console.ARP.PlayingChanged += onPlayingChanged;
			_console.ARP.RecordingChanged += onRecordingChanged;
			_console.ARP.RecordingJsonWritten += onJsonWritten;
			_global_playing = _console.ARP.IsPlaying;
			_global_recording = _console.ARP.IsRecording;
			_uses_keybinds = false;
			_uses_keybinds_settime = DateTime.UtcNow;
			_slot_press_time = DateTime.UtcNow;
			_slot_filepath = new string[base.Buttons];
			_slot_duration_seconds = new float[base.Buttons];
			_activate_time = new DateTime[base.Buttons];
			_slot_locked = new bool[base.Buttons];
			_keybind = new Keys[base.Buttons];
			_useskeybind = new bool[base.Buttons];
			_slot_can_repeat = new bool[base.Buttons];
			_slot_repeat_delay = new int[base.Buttons];
			_slot_repeat_enabled = new bool[base.Buttons];
			_slot_gain_adjust = new double[base.Buttons];
			_slot_ignore_play_temp_changes = new bool[base.Buttons];
			_slot_ignore_record_temp_changes = new bool[base.Buttons];
			for (int i = 0; i < base.Buttons; i++)
			{
				SetText(0, i, "Slot " + (i + 1));
				_slot_filepath[i] = null;
				_slot_duration_seconds[i] = 0f;
				_activate_time[i] = DateTime.MinValue;
				_slot_locked[i] = false;
				_keybind[i] = Keys.None;
				_useskeybind[i] = false;
				_slot_can_repeat[i] = false;
				_slot_repeat_delay[i] = 10;
				_slot_repeat_enabled[i] = false;
				_slot_gain_adjust[i] = 0.0;
				_slot_ignore_play_temp_changes[i] = true;
				_slot_ignore_record_temp_changes[i] = true;
			}
			_start_repeat_time = DateTime.MinValue;
			_repeat_slot = -1;
			_ignore_next_restart = false;
			_from_quick_shift_record = false;
			Initialise();
		}

		public override void Removing()
		{
			clearRunningRepeat(-1, force: true);
			_console.ARP.PlayingChanged -= onPlayingChanged;
			_console.ARP.RecordingChanged -= onRecordingChanged;
			_console.ARP.RecordingJsonWritten -= onJsonWritten;
			string error;
			if (_slot_playing > -1 && _console.ARP.IsPlaying)
			{
				_console.ARP.StopPlayback(out error);
			}
			if (_slot_recording > -1 && _console.ARP.IsRecording)
			{
				_console.ARP.StopRecord(out error);
			}
			_console.ARP.DeleteRecording(_unique_id, out var _, delete_containing_folder_if_empty: true);
		}

		public void RecordToSlot(int slot)
		{
			if (slot >= 0 && slot <= _slots - 1)
			{
				_mode_record = true;
				_from_quick_shift_record = true;
				_console.Invoke((MethodInvoker)delegate
				{
					handleClicked(slot, right_click: false, long_hold: false);
				});
			}
		}

		public void PlayFromSlot(int slot)
		{
			if (slot >= 0 && slot <= _slots - 1)
			{
				_mode_record = false;
				_console.Invoke((MethodInvoker)delegate
				{
					handleClicked(slot, right_click: false, long_hold: false);
				});
			}
		}

		public override void KeyUp(Keys keycode)
		{
			switch (keycode)
			{
			case Keys.Menu:
			case Keys.LMenu:
			case Keys.RMenu:
			case Keys.Alt:
				_alt_pressed = false;
				break;
			case Keys.ControlKey:
			case Keys.LControlKey:
			case Keys.RControlKey:
			case Keys.Control:
				_ctrl_pressed = false;
				break;
			case Keys.ShiftKey:
			case Keys.LShiftKey:
			case Keys.RShiftKey:
			case Keys.Shift:
				_shift_pressed = false;
				break;
			}
			if (!((DateTime.UtcNow - _uses_keybinds_settime).TotalMilliseconds > 750.0) || !_uses_keybinds || _mode_record)
			{
				return;
			}
			Keys keys = keycode & Keys.KeyCode;
			if (_alt_pressed)
			{
				keys |= Keys.Alt;
			}
			if (_ctrl_pressed)
			{
				keys |= Keys.Control;
			}
			if (_shift_pressed)
			{
				keys |= Keys.Shift;
			}
			for (int n = 0; n < Slots; n++)
			{
				if (_useskeybind[n] && _keybind[n] == keys && GetEnabled(1, n))
				{
					double totalMilliseconds = (DateTime.UtcNow - _slot_press_time).TotalMilliseconds;
					bool long_hold = totalMilliseconds >= 750.0;
					_console.Invoke((MethodInvoker)delegate
					{
						handleClicked(n, right_click: false, long_hold, from_repeat_timer: false, from_keybind: true);
					});
					break;
				}
			}
		}

		public override void KeyDown(Keys keycode)
		{
			switch (keycode)
			{
			case Keys.Menu:
			case Keys.LMenu:
			case Keys.RMenu:
			case Keys.Alt:
				_alt_pressed = true;
				break;
			case Keys.ControlKey:
			case Keys.LControlKey:
			case Keys.RControlKey:
			case Keys.Control:
				_ctrl_pressed = true;
				break;
			case Keys.ShiftKey:
			case Keys.LShiftKey:
			case Keys.RShiftKey:
			case Keys.Shift:
				_shift_pressed = true;
				break;
			}
			if (!((DateTime.UtcNow - _uses_keybinds_settime).TotalMilliseconds > 750.0) || !_uses_keybinds || _mode_record)
			{
				return;
			}
			Keys keys = keycode & Keys.KeyCode;
			if (_alt_pressed)
			{
				keys |= Keys.Alt;
			}
			if (_ctrl_pressed)
			{
				keys |= Keys.Control;
			}
			if (_shift_pressed)
			{
				keys |= Keys.Shift;
			}
			for (int i = 0; i < Slots; i++)
			{
				if (_useskeybind[i] && _keybind[i] == keys && GetEnabled(1, i))
				{
					_slot_press_time = DateTime.UtcNow;
					break;
				}
			}
		}

