		private void onJsonWritten(string unique_id, clsAudioRecordPlayback.RecordingJsonModel json)
		{
			if (unique_id != _unique_id)
			{
				return;
			}
			int result = -1;
			string fileNameWithoutExtension = Path.GetFileNameWithoutExtension(json.wav_file);
			int num = fileNameWithoutExtension.LastIndexOf('_');
			if (num >= 0 && int.TryParse(fileNameWithoutExtension.Substring(num + 1), out result))
			{
				result--;
				if (result >= 0 && result <= base.Buttons)
				{
					_slot_duration_seconds[result] = (float)json.play_duration_seconds;
				}
			}
		}

		private void onPlayingChanged(bool playing, string id, string filename, bool isWdsp)
		{
			_global_playing = playing;
			bool flag = false;
			if (_mode_record)
			{
				enableAllSlots(!playing);
				setupButtons();
				flag = true;
			}
			if (id != _unique_id)
			{
				if (!flag)
				{
					setupButtons();
				}
				clearRunningRepeat(-1, force: true);
			}
			else if (!playing)
			{
				if (_slot_can_repeat[_slot_playing] && _slot_repeat_enabled[_slot_playing] && !_ignore_next_restart)
				{
					setupRepeatTimer(setup: true, _slot_playing, _slot_repeat_delay[_slot_playing]);
				}
				_slot_playing = -1;
				_ignore_next_restart = false;
			}
			else
			{
				clearRunningRepeat(-1, force: true);
			}
		}

		private void onRecordingChanged(bool recording, string id, string filename)
		{
			_global_recording = recording;
			clearRunningRepeat(-1, force: true);
			enableAllSlots(!recording);
			if (id != _unique_id)
			{
				setupButtons();
				return;
			}
			if ((_slot_recording >= 0) & recording)
			{
				SetEnabled(0, _slot_recording, enabled: true);
			}
			setupButtons();
			if (!recording)
			{
				_slot_recording = -1;
				if (_from_quick_shift_record)
				{
					_from_quick_shift_record = false;
					_mode_record = false;
				}
			}
		}

		private void setupRepeatTimer(bool setup, int slot, int delay)
		{
			if (setup)
			{
				if (_repeat_timer != null)
				{
					setupRepeatTimer(setup: false, slot, delay);
					return;
				}
				_start_repeat_time = DateTime.UtcNow;
				_repeat_slot = slot;
				_repeat_timer = new System.Timers.Timer((float)delay * 1000f);
				_repeat_timer.Elapsed += delegate
				{
					if (_repeat_timer != null)
					{
						_repeat_timer.Stop();
						_repeat_timer.Dispose();
						_repeat_timer = null;
					}
					if (_console != null && !_console.IsDisposed && !_console.Disposing)
					{
						_console.Invoke((MethodInvoker)delegate
						{
							handleClicked(slot, right_click: false, long_hold: false, from_repeat_timer: true);
						});
					}
				};
				_repeat_timer.AutoReset = false;
				_repeat_timer.Start();
			}
			else
			{
				if (_repeat_timer != null)
				{
					_repeat_timer.Stop();
					_repeat_timer.Dispose();
					_repeat_timer = null;
				}
				_repeat_slot = -1;
				_start_repeat_time = DateTime.MinValue;
			}
		}

		private void enableAllSlots(bool enabled)
		{
			for (int i = 0; i < base.Buttons; i++)
			{
				SetEnabled(0, i, enabled);
			}
		}

