		public override void MouseDown(MouseEventArgs e)
		{
			if ((base.FadeOnRx && !_owningmeter.MOX) || (base.FadeOnTx && _owningmeter.MOX))
			{
				return;
			}
			int buttonIndex = base.ButtonIndex;
			if (buttonIndex == -1)
			{
				return;
			}
			if (buttonIndex >= 0)
			{
				_last_draged_to = -1;
				if (Common.AltlKeyDown)
				{
					_dragging_index = buttonIndex;
					return;
				}
				_dragging_index = -1;
				if (!GetEnabled(1, buttonIndex))
				{
					return;
				}
			}
			_slot_press_time = DateTime.UtcNow;
			setupClick(setup: false);
		}

		public override void MouseUp(MouseEventArgs e)
		{
			if ((base.FadeOnRx && !_owningmeter.MOX) || (base.FadeOnTx && _owningmeter.MOX) || _console == null)
			{
				return;
			}
			if (_dragging_index >= 0)
			{
				if (_last_draged_to != -1 && _dragging_index != _last_draged_to)
				{
					lock (_map_lock)
					{
						if (Common.ShiftKeyDown)
						{
							short num = _map[_last_draged_to];
							_map[_last_draged_to] = _map[_dragging_index];
							_map[_dragging_index] = num;
						}
						else
						{
							short num2 = _map[_dragging_index];
							if (_dragging_index < _last_draged_to)
							{
								Array.Copy(_map, _dragging_index + 1, _map, _dragging_index, _last_draged_to - _dragging_index);
								_map[_last_draged_to] = num2;
							}
							else
							{
								Array.Copy(_map, _last_draged_to, _map, _last_draged_to + 1, _dragging_index - _last_draged_to);
								_map[_last_draged_to] = num2;
							}
						}
						_map_changed = true;
					}
					setupButtons();
				}
				_dragging_index = -1;
				_last_draged_to = -1;
				return;
			}
			double totalMilliseconds = (DateTime.UtcNow - _slot_press_time).TotalMilliseconds;
			bool long_hold = totalMilliseconds >= 750.0;
			setupClick(setup: true);
			int index = base.ButtonIndex;
			if (index == -1)
			{
				return;
			}
			if (index == -10)
			{
				clearRunningRepeat(index, force: true);
				_mode_record = !_mode_record;
				return;
			}
			if (index == -11)
			{
				clearRunningRepeat(index, force: true);
				_wdsp = !_wdsp;
				setupButtons();
				return;
			}
			lock (_map_lock)
			{
				index = _map[index];
			}
			if (GetEnabled(1, index))
			{
				_console.Invoke((MethodInvoker)delegate
				{
					handleClicked(index, e.Button == MouseButtons.Right, long_hold);
				});
			}
		}

		private void clearRunningRepeat(int slot, bool force = false)
		{
			if ((_repeat_slot == slot) | force)
			{
				setupRepeatTimer(setup: false, -1, -1);
			}
		}

		private void handleClicked(int slot, bool right_click, bool long_hold, bool from_repeat_timer = false, bool from_keybind = false)
		{
			if (long_hold && !_mode_record)
			{
				if (_slot_can_repeat[slot])
				{
					clearRunningRepeat(slot);
					_slot_repeat_enabled[slot] = !_slot_repeat_enabled[slot];
				}
				return;
			}
			if (slot == _slot_playing)
			{
				clearRunningRepeat(slot);
				_ignore_next_restart = true;
				_console.ARP.StopPlayback(out var _);
				return;
			}
			if (slot == _slot_recording)
			{
				clearRunningRepeat(slot);
				_console.ARP.StopRecord(out var _);
				return;
			}
			if (_mode_record & right_click)
			{
				clearRunningRepeat(slot);
				if (!_slot_locked[slot])
				{
					_console.ARP.DeleteRecording(_slot_filepath[slot], out var _);
					if (!_console.ARP.GetJSONDetailsFromFile(_slot_filepath[slot], out var json_data))
					{
						_slot_filepath[slot] = null;
						_slot_duration_seconds[slot] = 0f;
						_activate_time[slot] = DateTime.MinValue;
					}
					else if (json_data != null)
					{
						_slot_duration_seconds[slot] = (float)json_data.play_duration_seconds;
					}
				}
				return;
			}
			if (!from_keybind && !from_repeat_timer && !_mode_record && _slot_playing == -1 && (_shift_pressed || Common.ShiftKeyDown))
			{
				if (!_slot_locked[slot])
				{
					clearRunningRepeat(-1, force: true);
					_mode_record = true;
					_from_quick_shift_record = true;
					handleClicked(slot, right_click, long_hold);
				}
				return;
			}
			string error4 = null;
			if (_console.ARP.IsPlaying)
			{
				_console.ARP.StopPlayback(out error4);
				error4 = null;
			}
			string full_path = _unique_id + "\\slot_" + (slot + 1) + ".wav";
			if (_mode_record)
			{
				clearRunningRepeat(slot);
				if (!_slot_locked[slot])
				{
					double num = ((_owningmeter.RX == 1) ? _owningmeter.VfoA : _owningmeter.VfoB);
					Band b = ((_owningmeter.RX == 1) ? _owningmeter.BandVfoA : _owningmeter.BandVfoB);
					DSPMode dSPMode = ((_owningmeter.RX == 1) ? _owningmeter.ModeVfoA : _owningmeter.ModeVfoB);
					RecordingDetails details = new RecordingDetails
					{
						Band = BandStackManager.BandToString(b),
						Frequency = num.ToString("F6", CultureInfo.InvariantCulture),
						Mode = dSPMode.ToString(),
						UtcTime = DateTime.UtcNow
					};
					_slot_recording = slot;
					_slot_duration_seconds[slot] = 0f;
					_activate_time[slot] = DateTime.UtcNow;
					if (_wdsp)
					{
						_slot_filepath[slot] = _console.ARP.RecordToFileFromWDSP(_unique_id, full_path, (_owningmeter.RX != 1) ? 1 : 0, out error4, remove_if_file_exists: true, details, _slot_ignore_record_temp_changes[slot]);
					}
					else
					{
						_slot_filepath[slot] = _console.ARP.RecordToFileFromPCAudio(_unique_id, full_path, _console.ARP.InputPCDeviceID, out error4, remove_if_file_exists: true, details);
					}
					if (_slot_filepath[slot] == null || error4 != null)
					{
						_slot_recording = -1;
						_slot_filepath[slot] = null;
						_slot_duration_seconds[slot] = 0f;
						_activate_time[slot] = DateTime.MinValue;
					}
				}
				return;
			}
			bool flag = slot == _repeat_slot;
			clearRunningRepeat(slot, force: true);
			if (!from_repeat_timer & flag)
			{
				return;
			}
			if (string.IsNullOrEmpty(_slot_filepath[slot]))
			{
				string text = Path.Combine(_console.ARP.AudioFolder, UniqueID, "slot_" + (slot + 1) + ".wav");
				if (File.Exists(text))
				{
					_slot_filepath[slot] = text;
				}
			}
			if (!_console.ARP.GetJSONDetailsFromFile(_slot_filepath[slot], out var json_data2))
			{
				_slot_filepath[slot] = null;
				_slot_duration_seconds[slot] = 0f;
				_activate_time[slot] = DateTime.MinValue;
				return;
			}
			if (json_data2 != null)
			{
				_slot_duration_seconds[slot] = (float)json_data2.play_duration_seconds;
			}
			_ignore_next_restart = false;
			bool flag2 = false;
			if (_slot_filepath[slot] != null)
			{
				_slot_playing = slot;
				_activate_time[slot] = DateTime.UtcNow;
				flag2 = ((!_wdsp) ? _console.ARP.PlayFileViaPCAudio(_unique_id, _slot_filepath[slot], _console.ARP.OutputPCDeviceID, out error4) : _console.ARP.PlayFileViaWDSP(_unique_id, _slot_filepath[slot], (_owningmeter.RX != 1) ? 1 : 0, out error4, _slot_gain_adjust[slot], _slot_ignore_play_temp_changes[slot]));
			}
			if (!flag2 || error4 != null)
			{
				_slot_playing = -1;
				_slot_filepath[slot] = null;
				_activate_time[slot] = DateTime.MinValue;
			}
		}
	}

