		public override void Removing()
		{
			if (Interlocked.Exchange(ref _disposed, 1) != 0)
			{
				return;
			}
			_console.ARP.PlayingChanged -= onPlayingChanged;
			_console.ARP.RecordingChanged -= onRecordingChanged;
			lock (_state_lock)
			{
				_file_paths = Array.Empty<string>();
				_hit_regions.Clear();
				_entries = Array.Empty<WaveRecordEntry>();
				_show_scrollbar = false;
				_max_scroll_px = 0f;
				_scroll_offset_px = 0f;
				_scroll_dragging = false;
				_dragging_index = -1;
				_last_dragged_to = -1;
				_mouse_down_hit_type = WaveRecordHitType.NONE;
				_mouse_down_path = null;
			}
		}

		private void onPlayingChanged(bool playing, string id, string filename, bool isWdsp)
		{
			bool flag;
			lock (_state_lock)
			{
				string active_play_filename = _active_play_filename;
				_global_playing = playing;
				_active_play_filename = (playing ? normaliseWaveRecordPath(filename) : null);
				flag = !playing && containsFilePathLocked(active_play_filename);
			}
			if (flag)
			{
				RefreshEntries();
			}
		}

		private void onRecordingChanged(bool recording, string id, string filename)
		{
			bool flag = !string.IsNullOrWhiteSpace(id) && id.StartsWith("waverecord", StringComparison.OrdinalIgnoreCase);
			bool flag2;
			lock (_state_lock)
			{
				string active_record_filename = _active_record_filename;
				_global_recording = recording;
				_active_record_filename = (recording ? normaliseWaveRecordPath(filename) : null);
				flag2 = flag && !recording && containsFilePathLocked(active_record_filename);
			}
			if (flag2)
			{
				RefreshEntries();
			}
		}

		public bool CanAcceptFiles(string[] filePaths)
		{
			return sanitiseStoredPaths(filePaths).Length != 0;
		}

		public void AddFiles(string[] filePaths)
		{
			string[] array = sanitiseStoredPaths(filePaths);
			if (array.Length < 1)
			{
				return;
			}
			bool flag = false;
			lock (_state_lock)
			{
				List<string> list = (_file_paths ?? Array.Empty<string>()).ToList();
				foreach (string newPath in array)
				{
					if (!list.Any((string existing) => waveRecordPathsEqual(existing, newPath)))
					{
						list.Add(newPath);
						flag = true;
					}
				}
				if (flag)
				{
					_file_paths = list.ToArray();
					_order_map = sanitiseOrderMap(_order_map, _file_paths.Length);
				}
			}
			if (flag)
			{
				RefreshEntries();
			}
		}

		public bool IsPlaying(string filePath)
		{
			lock (_state_lock)
			{
				return _global_playing && waveRecordPathsEqual(_active_play_filename, filePath);
			}
		}

		public void SetRenderLayout(SharpDX.RectangleF contentRect, SharpDX.RectangleF scrollTrackRect, SharpDX.RectangleF scrollThumbRect, float rowPitch, float maxScroll, bool showScrollbar, List<WaveRecordHitRegion> hitRegions)
		{
			lock (_state_lock)
			{
				_content_rect = contentRect;
				_scroll_track_rect = scrollTrackRect;
				_scroll_thumb_rect = scrollThumbRect;
				_row_pitch_px = rowPitch;
				_max_scroll_px = Math.Max(0f, maxScroll);
				_show_scrollbar = showScrollbar;
				_hit_regions = hitRegions ?? new List<WaveRecordHitRegion>();
				clampScrollLocked();
			}
		}

		public void UpdateDragFromMouse()
		{
			updateReorderDrag();
			updateScrollDrag();
		}

		public WaveRecordHitRegion HitTest(PointF point)
		{
			lock (_state_lock)
			{
				for (int num = _hit_regions.Count - 1; num >= 0; num--)
				{
					WaveRecordHitRegion waveRecordHitRegion = _hit_regions[num];
					if (waveRecordHitRegion.Rect.Contains(point.X, point.Y))
					{
						return waveRecordHitRegion;
					}
				}
			}
			return null;
		}

		public override void Update(int rx, ref List<Reading> readingsUsed, Dictionary<Reading, object> all_list_item_readings = null)
		{
			updateScrollDrag();
		}

		public override void MouseWheel(int number_of_moves)
		{
			if (!MouseEntered)
			{
				return;
			}
			float row_pitch_px;
			float height;
			bool show_scrollbar;
			lock (_state_lock)
			{
				row_pitch_px = _row_pitch_px;
				height = _content_rect.Height;
				show_scrollbar = _show_scrollbar;
			}
			if (show_scrollbar)
			{
				float num = row_pitch_px * 0.6f;
				if (height > 0f)
				{
					num = Math.Min(num, height * 0.2f);
				}
				num = Math.Max(8f, num);
				float delta = (float)(-number_of_moves) * num;
				adjustScroll(delta);
			}
		}

		public override void MouseDown(MouseEventArgs e)
		{
			if ((base.FadeOnRx && !_owningmeter.MOX) || (base.FadeOnTx && _owningmeter.MOX))
			{
				return;
			}
			PointF point = new PointF(e.X, e.Y);
			WaveRecordHitRegion waveRecordHitRegion = HitTest(point);
			lock (_state_lock)
			{
				_last_dragged_to = -1;
				_mouse_down_hit_type = waveRecordHitRegion?.HitType ?? WaveRecordHitType.NONE;
				_mouse_down_path = waveRecordHitRegion?.FilePath;
				if (e.Button == MouseButtons.Left && Common.AltlKeyDown)
				{
					int num = rowIndexFromPointLocked(point, clampToValid: true);
					if (num != -1)
					{
						_dragging_index = num;
						_last_dragged_to = num;
						_mouse_down_hit_type = WaveRecordHitType.NONE;
						_mouse_down_path = null;
						return;
					}
				}
				_dragging_index = -1;
				if (waveRecordHitRegion != null)
				{
					if (waveRecordHitRegion.HitType == WaveRecordHitType.SCROLL_THUMB)
					{
						_scroll_dragging = true;
						_scroll_drag_start_mouse_y = e.Y;
						_scroll_drag_start_offset_px = _scroll_offset_px;
					}
					else if (waveRecordHitRegion.HitType == WaveRecordHitType.SCROLL_TRACK)
					{
						scrollTrackToLocked(e.Y);
						_scroll_dragging = true;
						_scroll_drag_start_mouse_y = e.Y;
						_scroll_drag_start_offset_px = _scroll_offset_px;
					}
				}
			}
		}

		public override void MouseUp(MouseEventArgs e)
		{
			if ((base.FadeOnRx && !_owningmeter.MOX) || (base.FadeOnTx && _owningmeter.MOX))
			{
				return;
			}
			WaveRecordHitType mouse_down_hit_type;
			string mouse_down_path;
			bool scroll_dragging;
			int dragging_index;
			int last_dragged_to;
			lock (_state_lock)
			{
				mouse_down_hit_type = _mouse_down_hit_type;
				mouse_down_path = _mouse_down_path;
				scroll_dragging = _scroll_dragging;
				dragging_index = _dragging_index;
				last_dragged_to = _last_dragged_to;
				_mouse_down_hit_type = WaveRecordHitType.NONE;
				_mouse_down_path = null;
				_scroll_dragging = false;
				_dragging_index = -1;
				_last_dragged_to = -1;
			}
			if (dragging_index != -1)
			{
				if (last_dragged_to != -1 && dragging_index != last_dragged_to)
				{
					moveEntry(dragging_index, last_dragged_to, Common.ShiftKeyDown);
				}
			}
			else
			{
				if (scroll_dragging || _console == null || _console.IsDisposed || _console.Disposing)
				{
					return;
				}
				WaveRecordHitRegion hit = HitTest(new PointF(e.X, e.Y));
				if (hit != null && hit.HitType == mouse_down_hit_type && waveRecordPathsEqual(hit.FilePath, mouse_down_path))
				{
					_console.BeginInvoke((MethodInvoker)delegate
					{
						handleHit(hit);
					});
				}
			}
		}

		public void RefreshEntries()
		{
			if (Interlocked.CompareExchange(ref _disposed, 0, 0) != 0)
			{
				return;
			}
			string[] array;
			short[] array2;
			lock (_state_lock)
			{
				array = (_file_paths ?? Array.Empty<string>()).ToArray();
				array2 = sanitiseOrderMap(_order_map, array.Length);
				if (!shortArraysEqual(_order_map, array2))
				{
					_order_map = array2;
				}
			}
			List<WaveRecordEntry> list = new List<WaveRecordEntry>(array.Length);
			if (array2 != null)
			{
				foreach (int num in array2)
				{
					if (num >= 0 && num < array.Length)
					{
						string text = array[num];
						if (!string.IsNullOrWhiteSpace(text))
						{
							bool flag = File.Exists(text);
							list.Add(new WaveRecordEntry
							{
								FilePath = text,
								DisplayName = (Path.GetFileName(text) ?? text),
								FileExists = flag,
								JsonData = (flag ? buildJsonDataDisplay(text) : null)
							});
						}
					}
				}
			}
			else
			{
				foreach (string text2 in array)
				{
					if (!string.IsNullOrWhiteSpace(text2))
					{
						bool flag2 = File.Exists(text2);
						list.Add(new WaveRecordEntry
						{
							FilePath = text2,
							DisplayName = (Path.GetFileName(text2) ?? text2),
							FileExists = flag2,
							JsonData = (flag2 ? buildJsonDataDisplay(text2) : null)
						});
					}
				}
			}
			lock (_state_lock)
			{
				_entries = list.ToArray();
				clampScrollLocked();
			}
		}

		private WaveRecordJsonDataDisplay buildJsonDataDisplay(string wavPath)
		{
			try
			{
				if (!_console.ARP.GetJSONDetailsFromFile(wavPath, out var json_data) || json_data == null)
				{
					return null;
				}
				WaveRecordJsonDataDisplay waveRecordJsonDataDisplay = new WaveRecordJsonDataDisplay();
				waveRecordJsonDataDisplay.Frequency = sanitiseJsonDataValue(json_data.frequency, frequency: true);
				waveRecordJsonDataDisplay.Mode = sanitiseJsonDataValue(json_data.mode, frequency: false);
				waveRecordJsonDataDisplay.Band = sanitiseJsonDataValue(json_data.band, frequency: false);
				waveRecordJsonDataDisplay.Duration = formatJsonDataDuration(json_data.play_duration_seconds);
				waveRecordJsonDataDisplay.Audio = formatJsonDataAudio(json_data.bit_depth, json_data.sample_rate, json_data.channels);
				waveRecordJsonDataDisplay.Utc = formatJsonDataUtc(json_data.utc_time);
				return waveRecordJsonDataDisplay.HasData ? waveRecordJsonDataDisplay : null;
			}
			catch
			{
				return null;
			}
		}

		private static string sanitiseJsonDataValue(string value, bool frequency)
		{
			if (string.IsNullOrWhiteSpace(value))
			{
				return null;
			}
			string text = value.Trim();
			if (text.Length < 1)
			{
				return null;
			}
			if (!frequency)
			{
				return text;
			}
			if (text.IndexOf("hz", StringComparison.OrdinalIgnoreCase) >= 0)
			{
				return text;
			}
			if (double.TryParse(text, NumberStyles.Float, CultureInfo.InvariantCulture, out var result))
			{
				return result.ToString("0.000000", CultureInfo.InvariantCulture) + " MHz";
			}
			if (double.TryParse(text, NumberStyles.Float, CultureInfo.CurrentCulture, out result))
			{
				return result.ToString("0.000000", CultureInfo.InvariantCulture) + " MHz";
			}
			return text;
		}

		private static string formatJsonDataDuration(double? durationSeconds)
		{
			if (!durationSeconds.HasValue || durationSeconds.Value <= 0.0)
			{
				return null;
			}
			TimeSpan timeSpan = TimeSpan.FromSeconds(durationSeconds.Value);
			if (timeSpan.TotalHours >= 1.0)
			{
				return timeSpan.ToString("h\\:mm\\:ss");
			}
			return timeSpan.ToString("m\\:ss");
		}

		private static string formatJsonDataAudio(short bitDepth, int sampleRate, short channels)
		{
			List<string> list = new List<string>(3);
			if (bitDepth > 0)
			{
				list.Add(bitDepth.ToString(CultureInfo.InvariantCulture) + "-bit");
			}
			if (sampleRate > 0)
			{
				list.Add(sampleRate.ToString(CultureInfo.InvariantCulture) + " Hz");
			}
			if (channels > 0)
			{
				list.Add(channels.ToString(CultureInfo.InvariantCulture) + "ch");
			}
			if (list.Count >= 1)
			{
				return string.Join(" | ", list);
			}
			return null;
		}

		private static string formatJsonDataUtc(string value)
		{
			string text = sanitiseJsonDataValue(value, frequency: false);
			if (string.IsNullOrWhiteSpace(text))
			{
				return null;
			}
			if (DateTime.TryParse(text, CultureInfo.InvariantCulture, DateTimeStyles.AdjustToUniversal | DateTimeStyles.AssumeUniversal, out var result))
			{
				return DateTime.SpecifyKind(result, DateTimeKind.Utc).ToString("yyyy-MM-dd HH:mm'Z'", CultureInfo.InvariantCulture);
			}
			return text;
		}

		private bool containsFilePathLocked(string filePath)
		{
			if (string.IsNullOrWhiteSpace(filePath) || _file_paths == null || _file_paths.Length < 1)
			{
				return false;
			}
			return _file_paths.Any((string path) => waveRecordPathsEqual(path, filePath));
		}

		private static string[] sanitiseStoredPaths(IEnumerable<string> filePaths)
		{
			if (filePaths == null)
			{
				return Array.Empty<string>();
			}
			List<string> list = new List<string>();
			HashSet<string> hashSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
			foreach (string filePath in filePaths)
			{
				string text = normaliseWaveRecordPath(filePath);
				if (!string.IsNullOrWhiteSpace(text) && string.Equals(Path.GetExtension(text) ?? "", ".wav", StringComparison.OrdinalIgnoreCase) && hashSet.Add(text))
				{
					list.Add(text);
				}
			}
			return list.ToArray();
		}

		private static bool pathArraysEqual(string[] left, string[] right)
		{
			left = left ?? Array.Empty<string>();
			right = right ?? Array.Empty<string>();
			if (left.Length != right.Length)
			{
				return false;
			}
			for (int i = 0; i < left.Length; i++)
			{
				if (!waveRecordPathsEqual(left[i], right[i]))
				{
					return false;
				}
			}
			return true;
		}

		private static bool shortArraysEqual(short[] left, short[] right)
		{
			if (left == right)
			{
				return true;
			}
			left = left ?? Array.Empty<short>();
			right = right ?? Array.Empty<short>();
			if (left.Length != right.Length)
			{
				return false;
			}
			for (int i = 0; i < left.Length; i++)
			{
				if (left[i] != right[i])
				{
					return false;
				}
			}
			return true;
		}

		private static short[] sanitiseOrderMap(IEnumerable<short> rawOrderMap, int itemCount)
		{
			if (itemCount <= 1 || rawOrderMap == null)
			{
				return null;
			}
			List<short> list = new List<short>(itemCount);
			bool[] array = new bool[itemCount];
			foreach (short item in rawOrderMap)
			{
				if (item >= 0 && item < itemCount && !array[item])
				{
					array[item] = true;
					list.Add(item);
				}
			}
			for (int i = 0; i < itemCount; i++)
			{
				if (!array[i])
				{
					list.Add((short)i);
				}
			}
			bool flag = list.Count == itemCount;
			if (flag)
			{
				for (int j = 0; j < list.Count; j++)
				{
					if (list[j] != j)
					{
						flag = false;
						break;
					}
				}
			}
			if (!flag)
			{
				return list.ToArray();
			}
			return null;
		}

		private static short[] removeFromOrderMap(short[] orderMap, int removedIndex, int oldCount)
		{
			if (removedIndex < 0 || removedIndex >= oldCount)
			{
				return sanitiseOrderMap(orderMap, Math.Max(0, oldCount - 1));
			}
			List<short> list = new List<short>(oldCount);
			short[] array = sanitiseOrderMap(orderMap, oldCount);
			if (array == null)
			{
				for (int i = 0; i < oldCount; i++)
				{
					list.Add((short)i);
				}
			}
			else
			{
				list.AddRange(array);
			}
			list.RemoveAll((short index) => index == removedIndex);
			for (int num = 0; num < list.Count; num++)
			{
				if (list[num] > removedIndex)
				{
					list[num]--;
				}
			}
			return sanitiseOrderMap(list, oldCount - 1);
		}

		private void handleHit(WaveRecordHitRegion hit)
		{
			if (hit != null && Interlocked.CompareExchange(ref _disposed, 0, 0) == 0)
			{
				switch (hit.HitType)
				{
				case WaveRecordHitType.PLAY:
					handlePlay(hit.FilePath);
					break;
				case WaveRecordHitType.STOP:
				{
					_console.ARP.StopPlayback(out var _);
					break;
				}
				case WaveRecordHitType.DELETE:
					handleDelete(hit.FilePath);
					break;
				}
			}
		}

		private void handlePlay(string filePath)
		{
			if (string.IsNullOrWhiteSpace(filePath) || !_owningmeter.Power)
			{
				return;
			}
			bool global_recording;
			bool global_playing;
			string active_play_filename;
			lock (_state_lock)
			{
				global_recording = _global_recording;
				global_playing = _global_playing;
				active_play_filename = _active_play_filename;
			}
			if (global_recording)
			{
				return;
			}
			if (!File.Exists(filePath))
			{
				RefreshEntries();
				return;
			}
			string error;
			if (global_playing && waveRecordPathsEqual(active_play_filename, filePath))
			{
				_console.ARP.StopPlayback(out error);
				return;
			}
			if (_console.ARP.IsPlaying)
			{
				_console.ARP.StopPlayback(out error);
			}
			if (!_console.ARP.CanBePlayed(filePath))
			{
				RefreshEntries();
				return;
			}
			int wfw_id = ((_owningmeter.RX != 1) ? 1 : 0);
			if (!_console.ARP.PlayFileViaWDSP("wavelistplayer_" + _owningmeter.RX.ToString(CultureInfo.InvariantCulture), filePath, wfw_id, out var error2) || error2 != null)
			{
				RefreshEntries();
			}
		}

		private void handleDelete(string filePath)
		{
			if (string.IsNullOrWhiteSpace(filePath))
			{
				return;
			}
			string text = Path.GetFileName(filePath);
			if (string.IsNullOrWhiteSpace(text))
			{
				text = filePath;
			}
			if (MessageBox.Show("Remove WaveList Player item \"" + text + "\" from the list?", "WaveList Player", MessageBoxButtons.YesNo, MessageBoxIcon.Question, MessageBoxDefaultButton.Button2, (MessageBoxOptions)262144) != DialogResult.Yes)
			{
				return;
			}
			bool global_playing;
			string active_play_filename;
			lock (_state_lock)
			{
				global_playing = _global_playing;
				active_play_filename = _active_play_filename;
			}
			if (global_playing && waveRecordPathsEqual(active_play_filename, filePath))
			{
				_console.ARP.StopPlayback(out var _);
			}
			bool flag = false;
			lock (_state_lock)
			{
				if (_file_paths != null && _file_paths.Length != 0)
				{
					int num = Array.FindIndex(_file_paths, (string path) => waveRecordPathsEqual(path, filePath));
					if (num != -1)
					{
						string[] array = _file_paths.Where((string path) => !waveRecordPathsEqual(path, filePath)).ToArray();
						flag = array.Length != _file_paths.Length;
						if (flag)
						{
							_file_paths = array;
							_order_map = removeFromOrderMap(_order_map, num, _file_paths.Length + 1);
						}
					}
				}
			}
			if (flag)
			{
				RefreshEntries();
			}
		}

		private void moveEntry(int fromDisplayIndex, int toDisplayIndex, bool swapOnly)
		{
			bool flag = false;
			lock (_state_lock)
			{
				int num = ((_file_paths != null) ? _file_paths.Length : 0);
				if (num < 2 || fromDisplayIndex < 0 || fromDisplayIndex >= num || toDisplayIndex < 0 || toDisplayIndex >= num || fromDisplayIndex == toDisplayIndex)
				{
					return;
				}
				List<short> list = new List<short>();
				short[] array = sanitiseOrderMap(_order_map, num);
				if (array == null)
				{
					for (int i = 0; i < num; i++)
					{
						list.Add((short)i);
					}
				}
				else
				{
					list.AddRange(array);
				}
				if (swapOnly)
				{
					short value = list[toDisplayIndex];
					list[toDisplayIndex] = list[fromDisplayIndex];
					list[fromDisplayIndex] = value;
				}
				else
				{
					short item = list[fromDisplayIndex];
					list.RemoveAt(fromDisplayIndex);
					list.Insert(toDisplayIndex, item);
				}
				short[] array2 = sanitiseOrderMap(list, num);
				flag = !shortArraysEqual(_order_map, array2);
				if (flag)
				{
					_order_map = array2;
				}
			}
			if (flag)
			{
				RefreshEntries();
			}
		}

		private void adjustScroll(float delta)
		{
			lock (_state_lock)
			{
				if (_show_scrollbar && !(_max_scroll_px <= 0f))
				{
					_scroll_offset_px += delta;
					clampScrollLocked();
				}
			}
		}

		private void updateReorderDrag()
		{
			lock (_state_lock)
			{
				if (_dragging_index == -1)
				{
					_last_dragged_to = -1;
				}
				else if (!MouseButtonDown)
				{
					_last_dragged_to = -1;
				}
				else
				{
					_last_dragged_to = rowIndexFromPointLocked(MouseMovePoint, clampToValid: true);
				}
			}
		}

		private void updateScrollDrag()
		{
			lock (_state_lock)
			{
				if (_scroll_dragging && MouseButtonDown && _show_scrollbar && !(_max_scroll_px <= 0f))
				{
					float num = _scroll_track_rect.Bottom - _scroll_track_rect.Top;
					float num2 = _scroll_thumb_rect.Bottom - _scroll_thumb_rect.Top;
					float num3 = num - num2;
					if (!(num3 <= 0f))
					{
						float num4 = MouseMovePoint.Y - _scroll_drag_start_mouse_y;
						_scroll_offset_px = _scroll_drag_start_offset_px + num4 / num3 * _max_scroll_px;
						clampScrollLocked();
					}
				}
			}
		}

		private void scrollTrackToLocked(float mouseY)
		{
			if (!_show_scrollbar || _max_scroll_px <= 0f)
			{
				return;
			}
			float num = _scroll_track_rect.Bottom - _scroll_track_rect.Top;
			float num2 = _scroll_thumb_rect.Bottom - _scroll_thumb_rect.Top;
			float num3 = num - num2;
			if (!(num3 <= 0f))
			{
				float num4 = mouseY - _scroll_track_rect.Top - num2 / 2f;
				if (num4 < 0f)
				{
					num4 = 0f;
				}
				if (num4 > num3)
				{
					num4 = num3;
				}
				_scroll_offset_px = num4 / num3 * _max_scroll_px;
				clampScrollLocked();
			}
		}

		private int rowIndexFromPointLocked(PointF point, bool clampToValid)
		{
			int num = ((_entries != null) ? _entries.Length : 0);
			if (num < 1)
			{
				return -1;
			}
			if (_content_rect.Width <= 0f || _content_rect.Height <= 0f)
			{
				return -1;
			}
			if (!_content_rect.Contains(point.X, point.Y))
			{
				return -1;
			}
			if (_row_pitch_px <= 0f)
			{
				return -1;
			}
			float num2 = point.Y - _content_rect.Top + _scroll_offset_px;
			if (num2 < 0f)
			{
				if (!clampToValid)
				{
					return -1;
				}
				return 0;
			}
			int num3 = (int)(num2 / _row_pitch_px);
			if (num3 < 0)
			{
				if (!clampToValid)
				{
					return -1;
				}
				return 0;
			}
			if (num3 >= num)
			{
				if (!clampToValid)
				{
					return -1;
				}
				return num - 1;
			}
			return num3;
		}

		private void clampScrollLocked()
		{
			if (_max_scroll_px <= 0f)
			{
				_scroll_offset_px = 0f;
				return;
			}
			if (_scroll_offset_px < 0f)
			{
				_scroll_offset_px = 0f;
			}
			if (_scroll_offset_px > _max_scroll_px)
			{
				_scroll_offset_px = _max_scroll_px;
			}
		}
	}

