		public clsBandButtonBox(clsMeter owningmeter)
		{
			_owningmeter = owningmeter;
			base.ItemType = MeterItemType.BAND_BUTTONS;
			Initialise();
		}

		public override void Initialise()
		{
			if (_owningmeter.RX == 1)
			{
				_band = _owningmeter.BandVfoA;
				if (_console != null)
				{
					if (_console.BandGENSelected)
					{
						_button_bands = BandGroups.GEN;
					}
					else if (_console.BandHFSelected)
					{
						_button_bands = BandGroups.HF;
					}
					else if (_console.BandVHFSelected)
					{
						_button_bands = BandGroups.VHF;
					}
					else
					{
						_button_bands = _owningmeter.GetBandGroupFromBand(_band);
					}
				}
				else
				{
					_button_bands = _owningmeter.GetBandGroupFromBand(_band);
				}
			}
			else if (_owningmeter.RX == 2)
			{
				_band = _owningmeter.BandVfoB;
				_button_bands = _owningmeter.GetBandGroupFromBand(_band);
			}
			_click_highlight = false;
			_force_update = false;
			base.Buttons = 15;
			setupButtons();
		}

		public override void BandPanelsChanged(bool gen, bool hf, bool vhf)
		{
			if (gen)
			{
				ButtonBands = BandGroups.GEN;
			}
			else if (hf)
			{
				ButtonBands = BandGroups.HF;
			}
			else if (vhf)
			{
				ButtonBands = BandGroups.VHF;
			}
		}

		public void VHFUpdate(int index, bool enabled, string text)
		{
			if (_button_bands == BandGroups.VHF && index >= 0 && index <= 14)
			{
				SetEnabled(1, index, enabled);
				System.Drawing.Color colour = BandStackManager.BandToColour(Band.VHF0);
				if (enabled)
				{
					SetFontColour(1, index, colour);
				}
				else
				{
					SetFontColour(1, index, System.Drawing.Color.FromArgb(255, (int)((float)(int)colour.R * 0.3f), (int)((float)(int)colour.G * 0.3f), (int)((float)(int)colour.B * 0.3f)));
				}
				SetText(1, index, text);
			}
		}

		public override void BandChanged(Band oldBand, Band newBand)
		{
			Band band = _band;
			_band = newBand;
			BandGroups bandGroupFromBand = _owningmeter.GetBandGroupFromBand(_band);
			BandGroups bandGroupFromBand2 = _owningmeter.GetBandGroupFromBand(band);
			if (bandGroupFromBand != bandGroupFromBand2)
			{
				_force_update = true;
				ButtonBands = _owningmeter.GetBandGroupFromBand(newBand);
				_force_update = false;
				return;
			}
			int num = -1;
			int num2 = -1;
			switch (_button_bands)
			{
			case BandGroups.GEN:
				num = (int)(_band - 28);
				num2 = (int)(band - 28);
				break;
			case BandGroups.HF:
				num = (int)(_band - 1);
				num2 = (int)(band - 1);
				break;
			case BandGroups.VHF:
				num = (int)(_band - 14);
				num2 = (int)(band - 14);
				break;
			}
			if (num != -1 && num2 != -1)
			{
				SetOn(1, num2, on: false);
				if (newBand != Band.WWV)
				{
					SetOn(1, num, on: true);
				}
			}
		}

		private void setupButtons()
		{
			if (!base.RebuildButtons)
			{
				return;
			}
			for (int i = 0; i < base.Buttons; i++)
			{
				SetText(1, i, GetText(0, i));
