				SetOnColour(1, i, GetOnColour(0, i));
				SetOffColour(1, i, GetOffColour(0, i));
				SetIndicatorWidth(1, i, GetIndicatorWidth(0, i));
				SetEnabled(1, i, enabled: true);
				SetVisible(1, i, enabled: true);
				SetOn(1, i, on: false);
				SetFillColour(1, i, GetFillColour(0, i));
				SetHoverColour(1, i, GetHoverColour(0, i));
				SetBorderColour(1, i, GetBorderColour(0, i));
				SetClickColour(1, i, GetClickColour(0, i));
				SetUseOffColour(1, i, GetUseOffColour(0, i));
				SetIndicatorType(1, i, GetIndicatorType(0, i));
			}
			int num = 0;
			int num2 = 0;
			System.Drawing.Color colour = System.Drawing.Color.White;
			switch (_button_bands)
			{
			case BandGroups.GEN:
				num = 28;
				num2 = 41;
				colour = System.Drawing.Color.Yellow;
				SetText(1, 14, "HF");
				SetFontColour(1, 14, System.Drawing.Color.Red);
				SetUseIndicator(1, 14, use: false);
				SetUseOffColour(1, 14, use: false);
				SetOn(1, 14, on: false);
				break;
			case BandGroups.HF:
				num = 1;
				num2 = 11;
				colour = GetFontColour(0, 0);
				SetText(1, 11, "");
				SetHoverColour(1, 11, System.Drawing.Color.Transparent);
				SetUseIndicator(1, 12, use: false);
				SetOn(1, 11, on: false);
				SetUseOffColour(1, 11, use: false);
				SetText(1, 12, "VHF");
				SetFontColour(1, 12, BandStackManager.BandToColour(Band.VHF0));
				SetUseIndicator(1, 12, use: false);
				SetOn(1, 12, on: false);
				SetUseOffColour(1, 12, use: false);
				SetText(1, 13, "WWV");
				SetFontColour(1, 13, System.Drawing.Color.LightGreen);
				SetUseIndicator(1, 13, use: false);
				SetOn(1, 13, on: false);
				SetUseOffColour(1, 13, use: false);
				SetText(1, 14, "SWL");
				SetFontColour(1, 14, BandStackManager.BandToColour(Band.B120M));
				SetUseIndicator(1, 14, use: false);
				SetOn(1, 14, on: false);
				SetUseOffColour(1, 14, use: false);
				break;
			case BandGroups.VHF:
				num = 14;
				num2 = 27;
				colour = BandStackManager.BandToColour(Band.VHF0);
				SetText(1, 14, "HF");
				SetFontColour(1, 14, System.Drawing.Color.Red);
				SetUseIndicator(1, 14, use: false);
				SetOn(1, 14, on: false);
				SetUseOffColour(1, 14, use: false);
				break;
			}
			int num3 = num2 - num + 1;
			for (int j = 0; j < base.Buttons; j++)
			{
				if (j >= num3)
				{
					continue;
				}
				string text = "";
				Band band = (Band)(num + j);
				if (_button_bands == BandGroups.VHF)
				{
					SetEnabled(1, j, _console.GetVHFEnabled(j));
					text = _console.GetVHFText(j).Left(3);
					if (string.IsNullOrEmpty(text))
					{
						text = BandStackManager.BandToString(band);
						text = text.Substring(3);
					}
				}
				else if (band == Band.BLMF)
				{
					text = "L/MW";
				}
				else
				{
					text = BandStackManager.BandToString(band);
					text = text.Left(text.Length - 1);
				}
				SetText(1, j, text);
				if (GetEnabled(1, j))
				{
					SetFontColour(1, j, colour);
				}
				else
				{
					SetFontColour(1, j, System.Drawing.Color.FromArgb(255, (int)((float)(int)colour.R * 0.3f), (int)((float)(int)colour.G * 0.3f), (int)((float)(int)colour.B * 0.3f)));
				}
				SetFontSize(1, j, 18f);
				SetOn(1, j, band == _band);
			}
			int num4 = base.Buttons / Columns;
			if (base.Buttons % Columns > 0)
			{
				num4++;
			}
			_ = Border / 2f;
			_ = 0.96f / (float)Columns;
			_ = Margin;
			_ = Border;
			float height = 0.96f / (float)Columns * HeightRatio * (float)num4;
			base.Size = new SizeF(base.Size.Width, height);
		}

		private void setupClick(bool setup)
		{
			if (setup)
			{
				_click_timer = new System.Timers.Timer(100.0);
				_click_timer.Elapsed += delegate
				{
					_click_highlight = false;
					if (_click_timer != null)
					{
						_click_timer.Stop();
						_click_timer.Dispose();
						_click_timer = null;
					}
				};
				_click_timer.AutoReset = false;
				_click_timer.Start();
			}
			else
			{
				if (_click_timer != null)
				{
					_click_timer.Stop();
					_click_timer.Dispose();
					_click_timer = null;
				}
				_click_highlight = true;
			}
		}

		public override void MouseDown(MouseEventArgs e)
		{
			if ((!base.FadeOnRx || _owningmeter.MOX) && (!base.FadeOnTx || !_owningmeter.MOX))
			{
				int buttonIndex = base.ButtonIndex;
				if (buttonIndex != -1 && GetEnabled(1, buttonIndex))
				{
					setupClick(setup: false);
				}
			}
		}

		public override void MouseUp(MouseEventArgs e)
		{
			if ((base.FadeOnRx && !_owningmeter.MOX) || (base.FadeOnTx && _owningmeter.MOX))
			{
				return;
			}
			setupClick(setup: true);
			if ((_owningmeter.RX == 2 && !_owningmeter.RX2Enabled) || _console == null)
			{
				return;
			}
			int buttonIndex = base.ButtonIndex;
			if (buttonIndex == -1)
			{
				return;
			}
			Band b = Band.FIRST;
			switch (ButtonBands)
			{
			case BandGroups.GEN:
				if (buttonIndex == 14)
				{
					ButtonBands = BandGroups.HF;
					_owningmeter.SetBandPanel(_console, _owningmeter.RX, gen: false, hf: true, vhf: false);
					return;
				}
				b = (Band)(28 + buttonIndex);
				if (buttonIndex > 13)
				{
					return;
				}
				break;
			case BandGroups.HF:
				switch (buttonIndex)
				{
				case 12:
					ButtonBands = BandGroups.VHF;
					_owningmeter.SetBandPanel(_console, _owningmeter.RX, gen: false, hf: false, vhf: true);
					return;
				case 13:
					setBand(Band.WWV);
					return;
				case 14:
					ButtonBands = BandGroups.GEN;
					_owningmeter.SetBandPanel(_console, _owningmeter.RX, gen: true, hf: false, vhf: false);
					return;
				}
				if (buttonIndex > 10)
				{
					return;
				}
				b = (Band)(1 + buttonIndex);
				break;
			case BandGroups.VHF:
				if (buttonIndex == 14)
				{
					ButtonBands = BandGroups.HF;
					_owningmeter.SetBandPanel(_console, _owningmeter.RX, gen: false, hf: true, vhf: false);
					return;
				}
				if (buttonIndex > 13 || !GetEnabled(1, buttonIndex))
				{
					return;
				}
				b = (Band)(14 + buttonIndex);
				break;
			}
			if (e.Button == MouseButtons.Right && GetEnabled(1, buttonIndex))
			{
				if (_console != null)
				{
					_console.BeginInvoke((MethodInvoker)delegate
					{
						_console.PopupBandstack(_owningmeter.RX, b, IsOnTop(_owningmeter.ID));
					});
				}
			}
			else
			{
				setBand(b);
			}
		}

		private void setBand(Band b)
		{
			if (abortForLockedVFO() || b == Band.FIRST)
			{
				return;
			}
			if (_owningmeter.RX == 1)
			{
				_console.BeginInvoke((MethodInvoker)delegate
				{
					_console.BandPreChangeHandlers?.Invoke(1, b);
				});
			}
			else if (_owningmeter.RX == 2)
			{
				_console.BeginInvoke((MethodInvoker)delegate
				{
					_console.SetupRX2Band(b);
				});
			}
		}

		private bool abortForLockedVFO()
		{
			bool result = false;
			if (_owningmeter.RX == 1)
			{
				return _owningmeter.VFOALock;
			}
			if (_owningmeter.RX == 2)
			{
				return _owningmeter.VFOBLock;
			}
			return result;
		}
	}

	internal class clsDiscordButtonBox : clsButtonBox
	{
		private clsMeter _owningmeter;

		private bool _ready;

		private bool _click_highlight;

		private System.Timers.Timer _click_timer;

		public override bool ClickHighlight => _click_highlight;

		public override bool MouseEntered
		{
			get
			{
				return base.MouseEntered;
			}
			set
			{
				if (!value && _click_highlight)
				{
					if (_click_timer != null)
					{
						_click_timer.Stop();
						_click_timer.Dispose();
					}
					_click_highlight = false;
				}
				base.MouseEntered = value;
			}
		}

		public override int Columns
		{
			get
			{
				return base.Columns;
			}
			set
			{
				base.Columns = value;
				setupButtons();
			}
		}

		public override float Border
		{
			get
			{
				return base.Border;
			}
			set
			{
				base.Border = value;
				setupButtons();
			}
		}

		public override float Margin
		{
			get
			{
				return base.Margin;
			}
			set
			{
				base.Margin = value;
				setupButtons();
			}
		}

		public override float Radius
		{
			get
			{
				return base.Radius;
			}
			set
			{
				base.Radius = value;
				setupButtons();
			}
		}

		public override float HeightRatio
		{
			get
