				return base.HeightRatio;
			}
			set
			{
				base.HeightRatio = value;
				setupButtons();
			}
		}

		public clsDiscordButtonBox(clsMeter owningmeter)
		{
			_ready = ThetisBotDiscord.IsReady;
			_owningmeter = owningmeter;
			_click_highlight = false;
			base.ItemType = MeterItemType.DISCORD_BUTTONS;
			base.Buttons = 12;
			setupButtons();
			ThetisBotDiscord.ReadyHandlers = (ThetisBotDiscord.Ready)Delegate.Combine(ThetisBotDiscord.ReadyHandlers, new ThetisBotDiscord.Ready(OnReady));
			ThetisBotDiscord.DisconnectedHandlers = (ThetisBotDiscord.Disconnected)Delegate.Combine(ThetisBotDiscord.DisconnectedHandlers, new ThetisBotDiscord.Disconnected(OnDisconnected));
		}

		private void OnReady()
		{
			for (int i = 0; i < base.Buttons; i++)
			{
				System.Drawing.Color fontColour = GetFontColour(0, i);
				SetEnabled(1, i, enabled: true);
				SetFontColour(1, i, fontColour);
			}
			_ready = true;
		}

		private void OnDisconnected()
		{
			for (int i = 0; i < base.Buttons; i++)
			{
				System.Drawing.Color fontColour = GetFontColour(0, i);
				SetEnabled(1, i, enabled: false);
				SetFontColour(1, i, System.Drawing.Color.FromArgb(255, (int)((float)(int)fontColour.R * 0.3f), (int)((float)(int)fontColour.G * 0.3f), (int)((float)(int)fontColour.B * 0.3f)));
			}
			_ready = false;
		}

		private void setupButtons()
		{
			if (!base.RebuildButtons)
			{
				return;
			}
			for (int i = 0; i < base.Buttons; i++)
			{
				SetText(1, i, GetText(0, i));
				if (_ready)
				{
					SetFontColour(1, i, GetFontColour(0, i));
				}
				else
				{
					System.Drawing.Color fontColour = GetFontColour(0, i);
					SetFontColour(1, i, System.Drawing.Color.FromArgb(255, (int)((float)(int)fontColour.R * 0.3f), (int)((float)(int)fontColour.G * 0.3f), (int)((float)(int)fontColour.B * 0.3f)));
				}
				SetFontFamily(1, i, GetFontFamily(0, i));
				SetFontSize(1, i, GetFontSize(0, i));
				SetFontStyle(1, i, GetFontStyle(0, i));
				SetUseIndicator(1, i, GetUseIndicator(0, i));
				SetOnColour(1, i, GetOnColour(0, i));
				SetOffColour(1, i, GetOffColour(0, i));
				SetIndicatorWidth(1, i, GetIndicatorWidth(0, i));
				SetEnabled(1, i, _ready);
				SetVisible(1, i, enabled: true);
				SetOn(1, i, on: false);
				SetFillColour(1, i, GetFillColour(0, i));
				SetHoverColour(1, i, GetHoverColour(0, i));
				SetBorderColour(1, i, GetBorderColour(0, i));
				SetClickColour(1, i, GetClickColour(0, i));
				SetUseOffColour(1, i, GetUseOffColour(0, i));
				SetIndicatorType(1, i, GetIndicatorType(0, i));
			}
			SetText(1, 0, "Active");
			SetText(1, 1, "Away");
			SetText(1, 2, "Double");
			SetText(1, 3, "CQ");
			SetText(1, 4, "QRV");
			SetText(1, 5, "QRT");
			SetText(1, 6, "QSY");
			SetText(1, 7, "QRX");
			SetText(1, 8, "DX");
			SetText(1, 9, "Version");
			SetText(1, 10, " Net\nStart");
			SetText(1, 11, " Net\nFinish");
			int num = base.Buttons / Columns;
			if (base.Buttons % Columns > 0)
			{
				num++;
			}
			_ = Border / 2f;
			_ = 0.96f / (float)Columns;
			_ = Margin;
			_ = Border;
			float height = 0.96f / (float)Columns * HeightRatio * (float)num;
			base.Size = new SizeF(base.Size.Width, height);
		}

		private string formatNumber(double number)
		{
			string text = number.ToString("F6", CultureInfo.InvariantCulture);
			int num = text.IndexOf('.');
			if (num != -1 && text.Length > num + 3)
			{
				text = text.Insert(num + 4, ".");
			}
			return text;
		}

		private void setupClick(bool setup)
		{
			if (setup)
			{
				_click_timer = new System.Timers.Timer(100.0);
				_click_timer.Elapsed += delegate
				{
					_click_highlight = false;
					if (_click_timer != null)
					{
						_click_timer.Stop();
						_click_timer.Dispose();
						_click_timer = null;
					}
				};
				_click_timer.AutoReset = false;
				_click_timer.Start();
			}
			else
			{
				if (_click_timer != null)
				{
					_click_timer.Stop();
					_click_timer.Dispose();
					_click_timer = null;
				}
				_click_highlight = true;
			}
		}

		public override void MouseDown(MouseEventArgs e)
		{
			if ((!base.FadeOnRx || _owningmeter.MOX) && (!base.FadeOnTx || !_owningmeter.MOX))
			{
				int buttonIndex = base.ButtonIndex;
				if (buttonIndex != -1 && GetEnabled(1, buttonIndex))
				{
					setupClick(setup: false);
				}
			}
		}

		public override void MouseUp(MouseEventArgs e)
		{
			if ((base.FadeOnRx && !_owningmeter.MOX) || (base.FadeOnTx && _owningmeter.MOX))
			{
				return;
			}
			setupClick(setup: true);
			if (_console == null)
			{
				return;
			}
			int buttonIndex = base.ButtonIndex;
			if (buttonIndex != -1 && GetEnabled(1, buttonIndex))
			{
				double number = ((_owningmeter.RX == 2 && _owningmeter.RX2Enabled) ? _owningmeter.VfoB : _owningmeter.VfoA);
				double number2 = ((!_owningmeter.RX2Enabled) ? ((!_owningmeter.TXVFOb) ? _owningmeter.VfoA : _owningmeter.VfoB) : (_owningmeter.TXVFOb ? _owningmeter.VfoB : ((!_owningmeter.Split) ? _owningmeter.VfoA : _owningmeter.VfoSub)));
				switch (buttonIndex)
				{
				case 0:
					sendMsg("Is Active");
					break;
				case 1:
					sendMsg("Is Away");
					break;
				case 2:
					sendMsg("Someone is doubling !");
					break;
				case 3:
					sendMsg("Is calling CQ : " + formatNumber(number2) + " MHz");
					break;
				case 4:
					sendMsg("Is listening : " + formatNumber(number) + " MHz");
					break;
				case 5:
					sendMsg("Has gone QRT");
					break;
				case 6:
					sendMsg("Has QSY to : " + formatNumber(number) + " MHz");
					break;
				case 7:
					sendMsg("Will be right back, QRX");
					break;
				case 8:
				{
					string msg = "Is calling CQDX : " + formatNumber(number2) + " MHz";
					sendMsg(msg);
					break;
				}
				case 9:
					sendMsg("Is running Thetis v" + Common.GetVerNum(include_revision: true, include_build: true));
					break;
				case 10:
					sendMsg("Is starting a net on : " + formatNumber(number2) + " MHz");
					break;
				case 11:
					sendMsg("Is ending a net on : " + formatNumber(number2) + " MHz");
					break;
				}
			}
		}

		private void sendMsg(string msg)
		{
			Task.Run(async delegate
			{
				ulong channel_id = 1297325528336044144uL;
				await ThetisBotDiscord.SendMessage(msg, channel_id);
			});
		}
	}

