			_off_colour = new System.Drawing.Color[2][];
			_on = new bool[2][];
			_fontFamily = new string[2][];
			_fontStyle = new System.Drawing.FontStyle[2][];
			_fontSize = new float[2][];
			_font_colour = new System.Drawing.Color[2][];
			_text = new string[2][];
			_text_changed = new bool[2][];
			_use_icon = new bool[2][];
			_icon_on = new string[2][];
			_icon_off = new string[2][];
			_enabled = new bool[2][];
			_visible = new bool[2][];
			_indicator_type = new IndicatorType[2][];
			for (int i = 0; i < 2; i++)
			{
				_fill_colour[i] = new System.Drawing.Color[512];
				_hover_colour[i] = new System.Drawing.Color[512];
				_border_colour[i] = new System.Drawing.Color[512];
				_click_colour[i] = new System.Drawing.Color[512];
				_use_off_colour[i] = new bool[512];
				_use_indicator[i] = new bool[512];
				_indicator_width[i] = new float[512];
				_on_colour[i] = new System.Drawing.Color[512];
				_off_colour[i] = new System.Drawing.Color[512];
				_on[i] = new bool[512];
				_fontFamily[i] = new string[512];
				_fontStyle[i] = new System.Drawing.FontStyle[512];
				_fontSize[i] = new float[512];
				_font_colour[i] = new System.Drawing.Color[512];
				_text[i] = new string[512];
				_text_changed[i] = new bool[512];
				_use_icon[i] = new bool[512];
				_icon_on[i] = new string[512];
				_icon_off[i] = new string[512];
				_enabled[i] = new bool[512];
				_visible[i] = new bool[512];
				_indicator_type[i] = new IndicatorType[512];
			}
			ResetButtons();
		}

		public void ResetButtons()
		{
			for (int i = 0; i < 2; i++)
			{
				for (int j = 0; j < 512; j++)
				{
					_fill_colour[i][j] = System.Drawing.Color.Black;
					_hover_colour[i][j] = System.Drawing.Color.LightGray;
					_border_colour[i][j] = System.Drawing.Color.White;
					_click_colour[i][j] = System.Drawing.Color.Orange;
					_use_off_colour[i][j] = false;
					_use_indicator[i][j] = false;
					_indicator_width[i][j] = 0.005f;
					_on_colour[i][j] = System.Drawing.Color.CornflowerBlue;
					_off_colour[i][j] = System.Drawing.Color.Black;
					_on[i][j] = false;
					_fontFamily[i][j] = "Trebuchet MS";
					_fontStyle[i][j] = System.Drawing.FontStyle.Regular;
					_fontSize[i][j] = 18f;
					_font_colour[i][j] = System.Drawing.Color.White;
					_text[i][j] = "";
					_text_changed[i][j] = true;
					_use_icon[i][j] = false;
					_icon_on[i][j] = "";
					_icon_off[i][j] = "";
					_enabled[i][j] = true;
					_visible[i][j] = true;
					_indicator_type[i][j] = IndicatorType.RING;
				}
			}
			_total_buttons_visible = _number_of_buttons;
		}

