			{
				_long_press_released = true;
				_mouse_down_time = DateTime.UtcNow;
			}
		}

		public override void MouseUp(MouseEventArgs e)
		{
			if (!MouseEntered || _console == null)
			{
				return;
			}
			switch (_mouse_over_vfoB ? _render_button_vfoB : _render_button_vfoA)
			{
			case buttonState.VFO:
				if (e.Button == MouseButtons.Left)
				{
					_console.BeginInvoke((MethodInvoker)delegate
					{
						adjustVfo(_adjust_step * 1E-06);
					});
				}
				else if (e.Button == MouseButtons.Right)
				{
					_console.BeginInvoke((MethodInvoker)delegate
					{
						adjustVfo((0.0 - _adjust_step) * 1E-06);
					});
				}
				break;
			case buttonState.BAND_SCREEN:
				if (!abortForLockedVFO())
				{
					if (_mouse_over_vfoB)
					{
						VFOBRenderState = renderState.BAND;
					}
					else
					{
						VFOARenderState = renderState.BAND;
					}
				}
				break;
			case buttonState.VFO_SCREEN:
				if (_mouse_over_vfoB)
				{
					VFOBRenderState = renderState.VFO;
				}
				else
				{
					VFOARenderState = renderState.VFO;
				}
				break;
			case buttonState.FILTER_SCREEN:
				if (_mouse_over_vfoB)
				{
					VFOBRenderState = renderState.FILTER;
				}
				else
				{
					VFOARenderState = renderState.FILTER;
				}
				break;
			case buttonState.MODE_SCREEN:
				if (!abortForLockedVFO())
				{
					if (_mouse_over_vfoB)
					{
						VFOBRenderState = renderState.MODE;
					}
					else
					{
						VFOARenderState = renderState.MODE;
					}
				}
				break;
			case buttonState.BAND:
				if (abortForLockedVFO())
				{
					break;
				}
				if (_mouse_over_vfoB)
				{
					if (setBand(vfoB: true))
					{
						VFOBRenderState = renderState.VFO;
					}
					else
					{
						_render_state_vfoB_change_time = DateTime.UtcNow;
					}
				}
				else if (setBand(vfoB: false))
				{
					VFOARenderState = renderState.VFO;
				}
				else
				{
					_render_state_vfoA_change_time = DateTime.UtcNow;
				}
				break;
			case buttonState.MODE:
				if (_mouse_over_vfoB)
				{
					if (setMode(vfoB: true))
					{
						VFOBRenderState = renderState.VFO;
					}
					else
					{
						_render_state_vfoB_change_time = DateTime.UtcNow;
					}
				}
				else if (setMode(vfoB: false))
				{
					VFOARenderState = renderState.VFO;
				}
				else
				{
					_render_state_vfoA_change_time = DateTime.UtcNow;
				}
				break;
			case buttonState.FILTER:
				if (_mouse_over_vfoB)
				{
					if (setFilter(vfoB: true))
					{
						VFOBRenderState = renderState.VFO;
					}
					else
					{
						_render_state_vfoB_change_time = DateTime.UtcNow;
					}
				}
				else if (setFilter(vfoB: false))
				{
					VFOARenderState = renderState.VFO;
				}
				else
				{
					_render_state_vfoA_change_time = DateTime.UtcNow;
				}
				break;
			case buttonState.SPLIT:
				if (!_mouse_over_vfoB)
				{
					toggleSplit(e);
				}
				break;
			case buttonState.TX:
				if (_mouse_over_vfoB)
				{
					setTX(vfoB: true);
				}
				else
				{
					setTX(vfoB: false);
				}
				break;
			case buttonState.LOCK:
				if (_mouse_over_vfoB)
				{
					setLock(vfoB: true);
				}
				else
				{
					setLock(vfoB: false);
				}
				break;
			case buttonState.VFO_SYNC:
				setVfoSync();
				break;
			case buttonState.TUNE_STEP:
				if (!_long_press_released)
				{
					break;
				}
				if (_mouse_over_vfoB)
				{
					if (setTuneStep(vfoB: true))
					{
						VFOBRenderState = renderState.VFO;
					}
					else
					{
						_render_state_vfoB_change_time = DateTime.UtcNow;
					}
				}
				else if (setTuneStep(vfoB: false))
				{
					VFOARenderState = renderState.VFO;
				}
				else
				{
					_render_state_vfoA_change_time = DateTime.UtcNow;
				}
				break;
			}
			_long_press_released = true;
		}

		private bool setTuneStep(bool vfoB)
		{
			if (_console == null)
			{
				return false;
			}
			int num = (vfoB ? _button_grid_index_vfoB : _button_grid_index_vfoA);
			int tune_step_index = -1;
			switch (num)
			{
			case 0:
				tune_step_index = 0;
				break;
			case 1:
				tune_step_index = 2;
				break;
			case 2:
				tune_step_index = 3;
				break;
			case 3:
				tune_step_index = 4;
				break;
			case 4:
				tune_step_index = 5;
				break;
			case 5:
				tune_step_index = 6;
				break;
			case 6:
				tune_step_index = 7;
				break;
			case 7:
				tune_step_index = 8;
				break;
			case 8:
				tune_step_index = 11;
				break;
			case 9:
				tune_step_index = 12;
				break;
			case 10:
				tune_step_index = 14;
				break;
			case 11:
				tune_step_index = 15;
				break;
			case 12:
				tune_step_index = 17;
				break;
			case 13:
				tune_step_index = 18;
				break;
			case 14:
				tune_step_index = 20;
				break;
			case 15:
				tune_step_index = 21;
				break;
			}
			if (tune_step_index != -1)
			{
				_console.BeginInvoke((MethodInvoker)delegate
				{
					_console.TuneStepIndex = tune_step_index;
				});
				return true;
			}
			return false;
		}

		private void setLock(bool vfoB)
		{
			if (_console == null)
			{
				return;
			}
			if (vfoB)
			{
				_console.BeginInvoke((MethodInvoker)delegate
				{
					_console.VFOBLock = !_console.VFOBLock;
				});
			}
			else
			{
				_console.BeginInvoke((MethodInvoker)delegate
				{
					_console.VFOALock = !_console.VFOALock;
				});
			}
		}

