		private void toggleSplit(MouseEventArgs e)
		{
			if (_console == null)
			{
				return;
			}
			_console.BeginInvoke((MethodInvoker)delegate
			{
				if (e.Button == MouseButtons.Left && Keyboard.IsKeyDown(Keys.LShiftKey))
				{
					if (!_console.IsSetupFormNull && !_console.RX2Enabled)
					{
						_console.SetupForm.QuickSplitEnabled = !_console.SetupForm.QuickSplitEnabled;
					}
				}
				else
				{
					_console.VFOSplit = !_console.VFOSplit;
				}
			});
		}

		private bool setFilter(bool vfoB)
		{
			if (vfoB)
			{
				int button_grid_index_vfoB = _button_grid_index_vfoB;
				if (button_grid_index_vfoB < 0)
				{
					return true;
				}
				Filter fltr = (Filter)button_grid_index_vfoB;
				if (_owningmeter.RX2Enabled && (_owningmeter.RX != 1 || (!_owningmeter.MultiRxEnabled && !_owningmeter.Split)))
				{
					if (button_grid_index_vfoB > 8)
					{
						return true;
					}
					if (button_grid_index_vfoB > 6)
					{
						button_grid_index_vfoB += 3;
						fltr = (Filter)button_grid_index_vfoB;
					}
					_console.BeginInvoke((MethodInvoker)delegate
					{
						_console.RX2Filter = fltr;
					});
				}
				else
				{
					_console.BeginInvoke((MethodInvoker)delegate
					{
						_console.RX1Filter = fltr;
					});
				}
			}
			else
			{
				int button_grid_index_vfoA = _button_grid_index_vfoA;
				if (button_grid_index_vfoA < 0)
				{
					return true;
				}
				Filter fltr2 = (Filter)button_grid_index_vfoA;
				_console.BeginInvoke((MethodInvoker)delegate
				{
					_console.RX1Filter = fltr2;
				});
			}
			return true;
		}

		private bool setMode(bool vfoB)
		{
			if (abortForLockedVFO())
			{
				return false;
			}
			if (vfoB)
			{
				int button_grid_index_vfoB = _button_grid_index_vfoB;
				if (button_grid_index_vfoB < 0)
				{
					return true;
				}
				DSPModeForModeDisplay dSPModeForModeDisplay = (DSPModeForModeDisplay)button_grid_index_vfoB;
				Enum.TryParse<DSPMode>(dSPModeForModeDisplay.ToString(), out var dspMode);
				if (_owningmeter.RX2Enabled && (_owningmeter.RX != 1 || (!_owningmeter.MultiRxEnabled && !_owningmeter.Split)))
				{
					_console.BeginInvoke((MethodInvoker)delegate
					{
						_console.RX2DSPMode = dspMode;
					});
				}
				else
				{
					_console.BeginInvoke((MethodInvoker)delegate
					{
						_console.RX1DSPMode = dspMode;
					});
				}
			}
			else
			{
				int button_grid_index_vfoA = _button_grid_index_vfoA;
				if (button_grid_index_vfoA < 0)
				{
					return true;
				}
				DSPModeForModeDisplay dSPModeForModeDisplay2 = (DSPModeForModeDisplay)button_grid_index_vfoA;
				Enum.TryParse<DSPMode>(dSPModeForModeDisplay2.ToString(), out var dspMode2);
				_console.BeginInvoke((MethodInvoker)delegate
				{
					_console.RX1DSPMode = dspMode2;
				});
			}
			return true;
		}

		private bool setBand(bool vfoB)
		{
			if (abortForLockedVFO())
			{
				return false;
			}
			BandGroups bandGroups = ((_owningmeter.RX != 1) ? _owningmeter.GetBandGroupFromBand(vfoB ? _owningmeter.BandVfoB : _owningmeter.BandVfoA) : (_console.BandHFSelected ? BandGroups.HF : (_console.BandVHFSelected ? BandGroups.VHF : ((!_console.BandGENSelected) ? _owningmeter.GetBandGroupFromBand(vfoB ? _owningmeter.BandVfoB : _owningmeter.BandVfoA) : BandGroups.GEN))));
			if (vfoB)
			{
				int button_grid_index_vfoB = _button_grid_index_vfoB;
				if (button_grid_index_vfoB < 0)
				{
					return true;
				}
				Band band;
				switch (bandGroups)
				{
				case BandGroups.GEN:
					if (button_grid_index_vfoB > 12)
					{
						if (button_grid_index_vfoB == 13)
						{
							if (_owningmeter.RX == 1)
							{
								_owningmeter.SetBandPanel(_console, _owningmeter.RX, gen: false, hf: true, vhf: false);
							}
							else
							{
								_console.BeginInvoke((MethodInvoker)delegate
								{
									_console.RX2Band = Band.B20M;
								});
							}
							return false;
						}
						return true;
					}
					band = (Band)(29 + button_grid_index_vfoB);
					break;
				case BandGroups.HF:
					if (button_grid_index_vfoB > 10)
					{
						switch (button_grid_index_vfoB)
						{
						case 11:
							if (_owningmeter.RX == 1)
							{
								_owningmeter.SetBandPanel(_console, _owningmeter.RX, gen: false, hf: false, vhf: true);
							}
							else
							{
								_console.BeginInvoke((MethodInvoker)delegate
								{
									for (Band band3 = Band.VHF0; band3 <= Band.VHF13; band3++)
									{
										if (_console.XVTRForm.GetEnabled((int)(band3 - 14)))
										{
											_console.RX2Band = Band.VHF0;
											break;
										}
									}
								});
							}
							return false;
						case 13:
							if (_owningmeter.RX == 1)
							{
								_owningmeter.SetBandPanel(_console, _owningmeter.RX, gen: true, hf: false, vhf: false);
							}
							else
							{
								_console.BeginInvoke((MethodInvoker)delegate
								{
									_console.RX2Band = Band.B31M;
								});
							}
							return false;
						case 12:
							break;
						default:
							return true;
						}
						band = Band.WWV;
					}
					band = (Band)(1 + button_grid_index_vfoB);
					break;
				case BandGroups.VHF:
					if (button_grid_index_vfoB > 13)
					{
						if (button_grid_index_vfoB == 14)
						{
							if (_owningmeter.RX == 1)
							{
								_owningmeter.SetBandPanel(_console, _owningmeter.RX, gen: false, hf: true, vhf: false);
							}
							else
							{
								_console.BeginInvoke((MethodInvoker)delegate
								{
									_console.RX2Band = Band.B20M;
								});
							}
							return false;
						}
						return true;
					}
					band = (Band)(14 + button_grid_index_vfoB);
					break;
				default:
					return true;
				}
				if (_owningmeter.RX == 1 && (_owningmeter.MultiRxEnabled || _owningmeter.Split))
				{
					_console.BeginInvoke((MethodInvoker)delegate
					{
						_console.BandPreChangeHandlers?.Invoke(1, band);
					});
				}
				else
				{
					_console.BeginInvoke((MethodInvoker)delegate
					{
						_console.SetupRX2Band(band, !_owningmeter.RX2Enabled);
					});
				}
			}
			else
			{
				int button_grid_index_vfoA = _button_grid_index_vfoA;
				if (button_grid_index_vfoA < 0)
				{
					return true;
				}
				Band band2;
				if (_console.BandGENSelected)
				{
					if (button_grid_index_vfoA > 12)
					{
						if (button_grid_index_vfoA == 13)
						{
							if (_owningmeter.RX == 1)
							{
								_owningmeter.SetBandPanel(_console, _owningmeter.RX, gen: false, hf: true, vhf: false);
							}
							return false;
						}
						return true;
					}
					band2 = (Band)(29 + button_grid_index_vfoA);
				}
				else if (_console.BandHFSelected)
				{
					if (button_grid_index_vfoA > 10)
					{
						switch (button_grid_index_vfoA)
						{
						case 11:
							if (_owningmeter.RX == 1)
							{
								_owningmeter.SetBandPanel(_console, _owningmeter.RX, gen: false, hf: false, vhf: true);
							}
							return false;
						case 13:
							if (_owningmeter.RX == 1)
							{
								_owningmeter.SetBandPanel(_console, _owningmeter.RX, gen: true, hf: false, vhf: false);
							}
							return false;
						case 12:
							break;
						default:
							return true;
						}
						band2 = Band.WWV;
					}
					band2 = (Band)(1 + button_grid_index_vfoA);
				}
				else
				{
					if (!_console.BandVHFSelected)
					{
						return true;
					}
					if (button_grid_index_vfoA > 13)
					{
						if (button_grid_index_vfoA == 14)
						{
							if (_owningmeter.RX == 1)
							{
								_owningmeter.SetBandPanel(_console, _owningmeter.RX, gen: false, hf: true, vhf: false);
							}
							return false;
						}
						return true;
					}
					band2 = (Band)(14 + button_grid_index_vfoA);
				}
				_console.BeginInvoke((MethodInvoker)delegate
				{
					_console.BandPreChangeHandlers?.Invoke(1, band2);
				});
			}
			return true;
		}
	}

