		private bool _clipped;

		private bool _darkMode;

		private Guid _image_fetcher_guid;

		private Guid _bitmap_guid;

		private string _url;

		private int _secs_interval;

		private bool _bypass_cache;

		private System.Drawing.Bitmap _bitmap;

		private clsMeter _owningMeter;

		private readonly object _bitmap_lock = new object();

		private clsItemGroup _ig;

		private float _width_scale;

		private float _size;

		private ImageFetcher.State _state;

		private string _four_char;

		private bool _background;

		private int _background_interval;

		private string _background_4char;

		private DateTime _background_start_time;

		private bool _show_background;

		private bool _background_details_updated;

		private bool _show_next;

		private bool _show_this;

		private readonly object _show_this_lock = new object();

		private readonly object _show_next_lock = new object();

		private readonly object _background_start_time_lock = new object();

		private readonly object _background_interval_lock = new object();

		private readonly object _background_4char_lock = new object();

		private bool _process_timer;

		private System.Threading.Timer _timer;

		public override bool UpdateAlways => _background;

		public bool ShowBackground
		{
			get
			{
				return _show_background;
			}
			set
			{
				if (!_background || _show_background == value)
				{
					return;
				}
				_show_background = value;
				if (!_show_background)
				{
					return;
				}
				lock (_background_start_time_lock)
				{
					_background_start_time = DateTime.UtcNow;
				}
				lock (_bitmap_lock)
				{
					if (_bitmap == null || _console == null)
					{
						return;
					}
					System.Drawing.Bitmap bmp = null;
					try
					{
						bmp = _bitmap.Clone() as System.Drawing.Bitmap;
					}
					catch
					{
						bmp = null;
					}
					if (bmp != null && _console.IsHandleCreated)
					{
						_console.BeginInvoke((MethodInvoker)delegate
						{
							_console.PnlDisplayBackgroundImage = bmp;
							bmp.Dispose();
						});
					}
				}
			}
		}

		public bool Background
		{
			get
			{
				return _background;
			}
			set
			{
				if (_background != value)
				{
					_background = value;
					_background_details_updated = true;
				}
			}
		}

		public int BackgroundInterval
		{
			get
			{
				return _background_interval;
			}
			set
			{
				int background_interval;
				lock (_background_interval_lock)
				{
					background_interval = _background_interval;
				}
				if (background_interval != value)
				{
					lock (_background_interval_lock)
					{
						_background_interval = value;
					}
					_background_details_updated = true;
				}
			}
		}

		public string BackgroundFourChar
		{
			get
			{
				lock (_background_4char_lock)
				{
					return _background_4char;
				}
			}
			set
			{
				lock (_background_4char_lock)
				{
					if (_background_4char == value)
					{
						return;
					}
					_background_4char = value;
				}
				_background_details_updated = true;
			}
		}

		public string FourChar => _four_char;

		public System.Drawing.Bitmap Bitmap
		{
			get
			{
				lock (_bitmap_lock)
				{
					return _bitmap;
				}
			}
		}

		public int SecondsInterval
		{
			get
			{
				return _secs_interval;
			}
			set
			{
				_secs_interval = value;
				if (_image_fetcher_guid != Guid.Empty)
				{
					ImgFetch.UpdateInterval(_image_fetcher_guid, _secs_interval);
				}
			}
		}

		public bool BypassCache
		{
			get
			{
				return _bypass_cache;
			}
			set
			{
				_bypass_cache = value;
				if (_image_fetcher_guid != Guid.Empty)
				{
					ImgFetch.UpdateBypassCache(_image_fetcher_guid, _bypass_cache);
				}
			}
		}

		public Guid BitmapGuid
		{
			get
			{
				lock (_bitmap_lock)
				{
					return _bitmap_guid;
				}
			}
		}

		public Guid FetcherGuid
		{
			get
			{
				lock (_bitmap_lock)
				{
					return _image_fetcher_guid;
				}
			}
		}

		public string URL
		{
			get
			{
				return _url;
			}
			set
			{
				if (value == _url)
				{
					return;
				}
				if (value != _url && _image_fetcher_guid != Guid.Empty)
				{
					ImgFetch.ImagesObtained -= OnImage;
					ImgFetch.StateChanged -= OnState;
					ImgFetch.StopFetching(_image_fetcher_guid);
					_image_fetcher_guid = Guid.Empty;
				}
				bool flag = false;
				string text = "";
				if (!Common.IsValidUri(value))
				{
					if (value.ToLower().IndexOf("file://") < 0)
					{
						return;
					}
					try
					{
						Uri uri = new Uri(value);
						if (!File.Exists(uri.LocalPath))
						{
							return;
						}
						flag = true;
						text = uri.LocalPath;
					}
					catch
					{
						return;
					}
				}
				_url = value;
				string url = (flag ? text : _url);
				try
				{
					ImgFetch.StateChanged += OnState;
					ImgFetch.ImagesObtained += OnImage;
					_image_fetcher_guid = ImgFetch.RegisterURL(url, _secs_interval, 1, flag, _bypass_cache);
				}
				catch
				{
					ImgFetch.ImagesObtained -= OnImage;
					ImgFetch.StateChanged -= OnState;
					_image_fetcher_guid = Guid.Empty;
				}
			}
		}

		public ImageFetcher.State WebImageState => _state;

		public float ScaleSize => _size;

		public float WidthScale
		{
			get
			{
				return _width_scale;
			}
			set
			{
				_width_scale = value;
				lock (_bitmap_lock)
				{
					if (_bitmap != null)
					{
						_size = (float)_bitmap.Height / (float)_bitmap.Width * _width_scale;
					}
				}
			}
		}

		public PointF ClipTopLeft
		{
			get
			{
				return _clipTopLeft;
			}
			set
			{
				_clipTopLeft = value;
			}
		}

		public SizeF ClipSize
		{
			get
			{
				return _clipSize;
			}
			set
			{
				_clipSize = value;
			}
		}

		public bool Clipped
		{
			get
			{
				return _clipped;
			}
			set
			{
				_clipped = value;
			}
		}

		public bool DarkMode
		{
			get
			{
				return _darkMode;
			}
			set
			{
				_darkMode = value;
			}
		}

		public clsWebImage(clsMeter owningMeter, clsItemGroup ig)
		{
			_owningMeter = owningMeter;
			if (!Guid.TryParse(ig.ID, out var result))
			{
				result = Guid.NewGuid();
			}
			_four_char = Common.FourChar("webimage", 0, result);
			base.ItemType = MeterItemType.WEB_IMAGE;
			_background_details_updated = false;
			_show_next = false;
			_show_this = false;
			_background = false;
			_background_interval = 5;
			_background_4char = "";
			_background_start_time = DateTime.MinValue;
			_show_background = false;
			_process_timer = false;
			_clipTopLeft = new PointF(0f, 0f);
			_clipSize = new SizeF(1f, 1f);
			_clipped = false;
			_darkMode = false;
			base.StoreSettings = false;
			_image_fetcher_guid = Guid.Empty;
			_bitmap_guid = Guid.Empty;
			_bitmap = null;
			_url = "";
			_secs_interval = 120;
			_bypass_cache = false;
			_ig = ig;
			_width_scale = 1f;
			_size = 0.1f;
			_state = ImageFetcher.State.IDLE;
			_timer = new System.Threading.Timer(timerCallback, null, 0, 1000);
			WebImageRemoved += OnWebImageRemoved;
			ShowWebImageBackground += OnShowWebImageBackground;
			base.UpdateInterval = 100;
		}

		private void OnWebImageRemoved(object sender, string fourchar)
		{
			lock (_background_4char_lock)
			{
				if (_background_4char == fourchar)
				{
					_background_4char = "";
				}
			}
		}

		private void OnShowWebImageBackground(object sender, string fourchar)
		{
			if (_four_char == fourchar)
			{
				lock (_background_start_time_lock)
				{
					_background_start_time = DateTime.UtcNow;
				}
				lock (_show_this_lock)
				{
					_show_this = true;
				}
				_process_timer = true;
			}
			else
			{
				ShowBackground = false;
				_process_timer = false;
			}
		}

		private void timerCallback(object state)
		{
			if (!_process_timer)
			{
				return;
			}
			DateTime background_start_time;
			lock (_background_start_time_lock)
			{
				background_start_time = _background_start_time;
			}
			int background_interval;
			lock (_background_interval_lock)
			{
				background_interval = _background_interval;
			}
			if (!((DateTime.UtcNow - background_start_time).TotalSeconds >= (double)background_interval))
			{
				return;
			}
			_process_timer = false;
			lock (_show_next_lock)
			{
				_show_next = true;
			}
		}

		public override void Update(int rx, ref List<Reading> readingsUsed, Dictionary<Reading, object> all_list_item_readings = null)
		{
			if (_background_details_updated)
			{
				_background_details_updated = false;
				if (_background && !IsWebImageBackgroundShown())
				{
					ShowWebImageBackground?.Invoke(this, _four_char);
				}
			}
			bool show_this;
			lock (_show_this_lock)
			{
				show_this = _show_this;
				_show_this = false;
			}
			if (show_this)
			{
				_show_background = false;
				ShowBackground = true;
			}
			bool show_next;
			lock (_show_next_lock)
			{
				show_next = _show_next;
				_show_next = false;
			}
			if (show_next)
			{
				lock (_background_4char_lock)
				{
					ShowWebImageBackground?.Invoke(this, _background_4char);
				}
			}
		}

		public void ClearBackgroundFourChar()
		{
			lock (_background_4char_lock)
			{
				_background_4char = "";
			}
		}

		public override void Removing()
		{
			WebImageRemoved -= OnWebImageRemoved;
			ShowWebImageBackground -= OnShowWebImageBackground;
			if (_timer != null)
			{
				_timer.Dispose();
				_timer = null;
			}
			if (_show_background && _console != null)
			{
				_console.BeginInvoke((MethodInvoker)delegate
				{
					_console.PnlDisplayBackgroundImage = null;
				});
			}
			if (_image_fetcher_guid != Guid.Empty)
			{
				ImgFetch.ImagesObtained -= OnImage;
				ImgFetch.StateChanged -= OnState;
				ImgFetch.StopFetching(_image_fetcher_guid);
			}
			string text = "";
			lock (_bitmap_lock)
			{
				if (_bitmap != null)
				{
					_bitmap.Dispose();
					text = "webimg_" + _image_fetcher_guid.ToString();
				}
				if (!string.IsNullOrEmpty(text))
				{
					RemoveStreamData(text);
				}
			}
			WebImageRemoved?.Invoke(this, _four_char);
		}

		private void OnState(object sender, ImageFetcher.StateEventArgs e)
		{
			if (e.Guid != _image_fetcher_guid)
			{
				return;
			}
			_state = e.WebImageState;
			if (_console == null || !_console.IsHandleCreated)
			{
				return;
			}
			_console.BeginInvoke((MethodInvoker)delegate
			{
				if (!_console.IsSetupFormNull)
				{
					_console.SetupForm.SetWebImageState(base.ParentID, _state);
				}
			});
		}

		private void OnImage(object sender, Guid guid)
		{
			if (guid != _image_fetcher_guid)
			{
				return;
			}
			lock (_bitmap_lock)
			{
				List<System.Drawing.Image> list = ImgFetch.LatestImages(guid);
				if (list.Count == 1)
				{
					if (_bitmap != null)
					{
						_bitmap.Dispose();
					}
					try
					{
						_bitmap_guid = Guid.NewGuid();
						_bitmap = new System.Drawing.Bitmap(list[0]);
					}
					catch
					{
						_bitmap_guid = Guid.Empty;
						_bitmap = null;
					}
					if (_bitmap != null)
					{
						_size = (float)_bitmap.Height / (float)_bitmap.Width * _width_scale;
					}
				}
			}
			if (_size >= 0f && base.Size.Height != _size)
			{
				base.Size = new SizeF(_width_scale, _size);
				if (_ig != null)
				{
					float num = 0.041f;
					float num2 = 0.05f;
					_ig.Size = new SizeF(_ig.Size.Width, _size + (num - num2 * 0.75f));
					_owningMeter.Rebuild();
				}
			}
		}
	}

