			_show_beam_width = false;
			_beam_width = 30f;
			_beam_width_alpha = 0.6f;
			_darkMode = false;
			_rotator_mode = RotatorMode.BOTH;
			_padding = 0.5f;
			_data_out_mmio_guid = Guid.Empty;
			_big_blob_colour = System.Drawing.Color.Red;
			_small_blob_colour = System.Drawing.Color.White;
			_outer_text_colour = System.Drawing.Color.FromArgb(255, 128, 128, 128);
			_arrow_colour = System.Drawing.Color.White;
			_beam_width_colour = System.Drawing.Color.FromArgb(255, 64, 64, 64);
			_background_colour = System.Drawing.Color.FromArgb(32, 32, 32);
			_control_colour = System.Drawing.Color.LimeGreen;
			_alow_control = false;
			_control_string_AZ = "<PST><AZIMUTH>%AZ%</AZIMUTH></PST>";
			_control_string_ELE = "<PST><ELEVATION>%ELE%</ELEVATION></PST>";
			_control_string_STOP = "<PST><STOP>1</STOP></PST>";
			base.ItemType = MeterItemType.ROTATOR;
			base.ReadingSource = Reading.AZ;
			base.UpdateInterval = 1000;
			base.StoreSettings = false;
			_mouse_over_stop = false;
		}

		public void SendRotatorMessage(bool dragging_rotator_ele, float dragging_rotator_degrees, bool stop)
		{
			if (!(DataOutMMIOGuid == Guid.Empty) && _alow_control && MultiMeterIO.Data.ContainsKey(DataOutMMIOGuid))
			{
				MultiMeterIO.clsMMIO clsMMIO = MultiMeterIO.Data[DataOutMMIOGuid];
				if (clsMMIO != null)
				{
					string text = (stop ? _control_string_STOP : ((!dragging_rotator_ele) ? _control_string_AZ.Replace("%AZ%", ((int)dragging_rotator_degrees).ToString("000")) : _control_string_ELE.Replace("%ELE%", ((int)dragging_rotator_degrees).ToString("00"))));
					text = text.Replace("\\n", "\n");
					text = text.Replace("\\r", "\r");
					text = text.Replace("\\0", "\0");
					clsMMIO.EnqueueOutbound(text);
				}
			}
		}

		public override void Update(int rx, ref List<Reading> readingsUsed, Dictionary<Reading, object> all_list_item_readings = null)
		{
			float num;
			bool flag;
			if (base.MMIOGuid == Guid.Empty)
			{
				num = getReading(rx, base.ReadingSource);
				flag = true;
			}
			else
			{
				num = 0f;
				if (MultiMeterIO.Data.ContainsKey(base.MMIOGuid))
				{
					MultiMeterIO.clsMMIO clsMMIO = MultiMeterIO.Data[base.MMIOGuid];
					if (clsMMIO == null)
					{
						return;
					}
					object variable = clsMMIO.GetVariable(base.MMIOVariable);
					if (variable is int)
					{
						num = (int)variable;
					}
					else if (variable is float)
					{
						num = (float)variable;
					}
					else if (variable is double)
					{
						num = (float)(double)variable;
					}
				}
				flag = false;
			}
			lock (_historyLock)
			{
				if (base.ReadingSource == Reading.ELE)
				{
					if (num < 0f)
					{
						num = 0f;
					}
					if (num > 90f)
					{
						num = 90f;
					}
				}
				float num2 = Value % 360f;
				if (num2 < 0f)
				{
					num2 += 360f;
				}
				float num3 = num % 360f;
				if (num3 < 0f)
				{
					num3 += 360f;
				}
				float num4 = num3 - num2;
				if (num4 > 180f)
				{
					num4 -= 360f;
				}
				else if (num4 < -180f)
				{
					num4 += 360f;
				}
				float num5 = 0.2f * Math.Abs(num4);
				if (Math.Abs(num4) < num5)
				{
					Value = num;
				}
				else
				{
					Value += (float)Math.Sign(num4) * num5;
				}
				Value %= 360f;
				if (Value < 0f)
				{
					Value += 360f;
				}
			}
			if (flag && !readingsUsed.Contains(base.ReadingSource))
			{
				readingsUsed.Add(base.ReadingSource);
			}
		}

		public override bool ZeroOut(ref Dictionary<Reading, float> values, int rx)
		{
			return false;
		}

		public override void MouseUp(MouseEventArgs e)
		{
			if (_alow_control && _mouse_over_stop)
			{
				SendRotatorMessage(dragging_rotator_ele: false, -1f, stop: true);
			}
		}

		public override void MouseDown(MouseEventArgs e)
		{
			if (_alow_control && _mouse_over_stop)
			{
				SendRotatorMessage(dragging_rotator_ele: false, -1f, stop: true);
			}
		}
	}

