		public bool AlwaysShowVFOs
		{
			get
			{
				return _always_show_vfos;
			}
			set
			{
				_always_show_vfos = value;
			}
		}

		public float Degrees
		{
			get
			{
				return _degrees;
			}
			set
			{
				if (Lock || _degrees == value)
				{
					return;
				}
				float num = value - _degrees;
				if (num < -180f)
				{
					num += 360f;
				}
				if (num > 180f)
				{
					num -= 360f;
				}
				_degrees = value;
				if (_ignore_next_vfo_update)
				{
					_ignore_next_vfo_update = false;
					return;
				}
				num = 0f - num;
				_deg_turned += num;
				_degrees_total += Math.Abs(num);
				_old_direction = _direction;
				if (num == 0f)
				{
					_direction = 0;
				}
				else if (num > 0f)
				{
					_direction = 1;
				}
				else
				{
					_direction = -1;
				}
				float num2 = Math.Abs(_deg_turned);
				if (!(num2 >= 1f))
				{
					return;
				}
				if (num2 >= (float)_degrees_per_change)
				{
					_deg_turned -= (int)_deg_turned;
					int direction = _direction;
					if (_console != null)
					{
						double freq = (double)(direction * _console.CurrentTuneStepHz) * 1E-06;
						if (VFOA)
						{
							if (_align_with_tunestep)
							{
								freq = Math.Round((_console.VFOAFreq + freq) / ((double)_console.CurrentTuneStepHz * 1E-06)) * ((double)_console.CurrentTuneStepHz * 1E-06);
							}
							else
							{
								freq = _console.VFOAFreq + freq;
							}
						}
						else if (_align_with_tunestep)
						{
							freq = Math.Round((_console.VFOBFreq + freq) / ((double)_console.CurrentTuneStepHz * 1E-06)) * ((double)_console.CurrentTuneStepHz * 1E-06);
						}
						else
						{
							freq = _console.VFOBFreq + freq;
						}
						_console.BeginInvoke((MethodInvoker)delegate
						{
							if (VFOA)
							{
								_console.VFOAFreq = freq;
							}
							else
							{
								_console.VFOBFreq = freq;
							}
						});
					}
				}
				if (!_accelerate)
				{
					return;
				}
				float num3 = Math.Abs(_smoothed_speed);
				if (num3 >= (float)_up_threshold)
				{
					if (_tune_step_changes < _max_tune_step_changes && (DateTime.UtcNow - _last_accelerated).TotalSeconds >= (double)_tune_step_interval_seconds)
					{
						_console.BeginInvoke((MethodInvoker)delegate
						{
							_console.ChangeTuneStepUp();
						});
						_last_accelerated = DateTime.UtcNow;
						_tune_step_changes++;
					}
					_tune_step_direction = 1;
				}
				else if (num3 <= (float)_down_threshold)
				{
					if (_existing_step_index != -1 && _existing_step_index < _owningmeter.TuneStepIndex)
					{
						if ((DateTime.UtcNow - _last_accelerated).TotalSeconds >= (double)_tune_step_interval_seconds)
						{
							_console.BeginInvoke((MethodInvoker)delegate
							{
								_console.ChangeTuneStepDown();
							});
							_last_accelerated = DateTime.UtcNow;
						}
						_tune_step_changes--;
						if (_tune_step_changes < 0)
						{
							_tune_step_changes = 0;
						}
					}
					_tune_step_direction = -1;
				}
				else
				{
					_tune_step_direction = 0;
				}
			}
		}

		public bool VFOA
		{
			get
			{
				if (_always_show_vfos)
				{
					return _vfoA;
				}
				if (_owningmeter.RX == 1)
				{
					if (_owningmeter.RX2Enabled)
					{
						return true;
					}
					return _vfoA;
				}
				return false;
			}
			set
			{
				if (_always_show_vfos)
				{
					_vfoA = value;
				}
				else if (_owningmeter.RX == 2)
				{
					_vfoA = false;
				}
				else
				{
					_vfoA = value;
				}
			}
		}

		public bool Pressed
		{
			get
			{
				return _pressed;
			}
			set
			{
				if (_pressed != value)
				{
					_pressed = value;
					_smoothed_speed = 0f;
					_deg_turned = 0f;
					_degrees_total = 0f;
					_ignore_next_vfo_update = true;
					_tune_step_changes = 0;
					if (_pressed)
					{
						_existing_step_index = _owningmeter.TuneStepIndex;
					}
					else
					{
						undoTuneStep();
					}
				}
			}
		}

		public float SmoothedSpeed => _smoothed_speed;

		public float DegreesTotal => _degrees_total;

		public bool Accelerate
		{
			get
			{
				return _accelerate;
			}
			set
			{
				_accelerate = value;
			}
		}

		public bool Lock
		{
			get
			{
				if (!VFOA || !_owningmeter.VFOALock)
				{
					if (!VFOA)
					{
						return _owningmeter.VFOBLock;
					}
					return false;
				}
				return true;
			}
		}

		public clsDialDisplay(clsMeter owning_meter)
		{
			_owningmeter = owning_meter;
			_always_show_vfos = false;
			_tune_step_direction = 0;
			_accelerate = false;
			_last_accelerated = DateTime.MinValue;
			_existing_step_index = -1;
			_vfoA = _owningmeter.RX == 1;
			_previous_time = DateTime.MinValue;
			_smoothed_speed = 0f;
			_deg_turned = 0f;
			_pressed = false;
			_degrees = 0f;
			_colour = System.Drawing.Color.Black;
			_vscale = 1f;
			_font_scale = 1f;
			_vfoA_highlighted = false;
			_vfoB_highlighted = false;
			_accel_highlighted = false;
			_lock_highlighted = false;
			_direction = 0;
			_old_direction = 0;
			_ignore_next_vfo_update = false;
			_max_tune_step_changes = 3;
			_tune_step_changes = 0;
			_align_with_tunestep = true;
			_up_threshold = 540;
			_down_threshold = 360;
			_tune_step_interval_seconds = 2;
			_degrees_per_change = 5;
			_text_colour = System.Drawing.Color.White;
			_circle_colour = System.Drawing.Color.Black;
			_pad_colour = System.Drawing.Color.Blue;
			_pad_pressed_colour = System.Drawing.Color.Orange;
			_button_on_colour = System.Drawing.Color.CornflowerBlue;
			_button_off_colour = System.Drawing.Color.Black;
			_button_highlight_colour = System.Drawing.Color.Gray;
			_ring_colour = System.Drawing.Color.Gray;
			_slow_colour = System.Drawing.Color.Blue;
			_hold_colour = System.Drawing.Color.Green;
			_fast_colour = System.Drawing.Color.Red;
			base.ItemType = MeterItemType.DIAL_DISPLAY;
			base.ReadingSource = Reading.NONE;
			base.UpdateInterval = 16;
		}

		private void undoTuneStep()
		{
			if (_existing_step_index != -1)
			{
				int step = _existing_step_index;
				_console.BeginInvoke((MethodInvoker)delegate
				{
					_console.TuneStepIndex = step;
				});
				_existing_step_index = -1;
				_last_accelerated = DateTime.MinValue;
			}
		}

		public override void Update(int rx, ref List<Reading> readingsUsed, Dictionary<Reading, object> all_list_item_readings = null)
		{
			DateTime utcNow = DateTime.UtcNow;
			TimeSpan timeSpan = utcNow - _previous_time;
			if (_pressed && timeSpan.TotalMilliseconds > (double)(base.UpdateInterval * 4))
			{
				float num = _degrees_total / (float)(timeSpan.TotalMilliseconds / 1000.0);
				_smoothed_speed = _smoothed_speed * 0.95f + num * 0.05f;
				_degrees_total = 0f;
				_previous_time = utcNow;
			}
		}

		public override void MouseUp(MouseEventArgs e)
		{
			if (_pressed)
			{
				return;
			}
			if (_vfoA_highlighted)
			{
				VFOA = true;
			}
			if (_vfoB_highlighted)
			{
				VFOA = false;
			}
			if (_accel_highlighted)
			{
				_accelerate = !_accelerate;
			}
			if (!_lock_highlighted)
			{
				return;
			}
			_console.BeginInvoke((MethodInvoker)delegate
			{
				if (VFOA)
				{
					_console.VFOALock = !_console.VFOALock;
				}
				else
				{
					_console.VFOBLock = !_console.VFOBLock;
				}
			});
		}

		public override void MouseWheel(int number_of_moves)
		{
			if (!_pressed)
			{
				int num = Math.Sign(number_of_moves);
				Degrees -= _degrees_per_change * num;
			}
		}
	}

	internal class clsMagicEyeItem : clsMeterItem
	{
		private List<float> _history;

		private int _msHistoryDuration;

		private int _msIgnoreHistoryDuration;

		private bool _showHistory;

		private bool _showValue;

		private readonly object _historyLock = new object();

		private System.Drawing.Color _colour;

		private int _nIgnoringNext;

		private Dictionary<float, PointF> _scaleCalibration;

		public override bool ShowHistory
		{
			get
			{
				return _showHistory;
			}
			set
			{
				_showHistory = value;
			}
		}

		public bool ShowValue
		{
			get
			{
				return _showValue;
			}
			set
			{
				_showValue = value;
			}
		}

		public int IgnoreHistoryDuration
		{
			get
			{
				return _msIgnoreHistoryDuration;
			}
			set
			{
				_msIgnoreHistoryDuration = value;
			}
		}

		public int HistoryDuration
		{
			get
			{
				return _msHistoryDuration;
			}
			set
			{
				_msHistoryDuration = value;
				if (_msHistoryDuration < base.UpdateInterval)
				{
					_msHistoryDuration = base.UpdateInterval;
				}
			}
		}

		public override float MinHistory
		{
			get
			{
				lock (_historyLock)
				{
					if (_history.Count == 0)
					{
						return Value;
					}
					return _history.Min();
				}
			}
		}

		public override float MaxHistory
		{
			get
			{
				lock (_historyLock)
				{
					if (_history.Count == 0)
					{
						return Value;
					}
					return _history.Max();
				}
			}
		}

		public System.Drawing.Color Colour
		{
			get
			{
				return _colour;
			}
			set
			{
				_colour = value;
			}
		}

		public override Dictionary<float, PointF> ScaleCalibration
		{
			get
			{
				return _scaleCalibration;
			}
			set
			{
			}
		}

		public clsMagicEyeItem()
		{
			_history = new List<float>();
			_msHistoryDuration = 500;
			_msIgnoreHistoryDuration = 2000;
			_showHistory = false;
			_showValue = true;
			_colour = System.Drawing.Color.Lime;
			_nIgnoringNext = 0;
			_scaleCalibration = new Dictionary<float, PointF>();
			base.ItemType = MeterItemType.MAGIC_EYE;
			base.ReadingSource = Reading.NONE;
			base.UpdateInterval = 100;
			base.AttackRatio = 0.8f;
			base.DecayRatio = 0.2f;
			base.StoreSettings = false;
		}

		public override void Update(int rx, ref List<Reading> readingsUsed, Dictionary<Reading, object> all_list_item_readings = null)
		{
			float num;
			bool flag;
			if (base.MMIOGuid == Guid.Empty)
			{
				num = getReading(rx, base.ReadingSource);
				flag = true;
			}
			else
			{
				num = 0f;
				if (MultiMeterIO.Data.ContainsKey(base.MMIOGuid))
				{
					object variable = MultiMeterIO.Data[base.MMIOGuid].GetVariable(base.MMIOVariable);
					if (variable is int)
					{
						num = (int)variable;
					}
					else if (variable is float)
					{
						num = (float)variable;
					}
					else if (variable is double)
					{
						num = (float)(double)variable;
					}
				}
				flag = false;
			}
			lock (_historyLock)
			{
				if (num > Value)
				{
					Value = num * base.AttackRatio + Value * (1f - base.AttackRatio);
				}
				else
				{
					Value = num * base.DecayRatio + Value * (1f - base.DecayRatio);
				}
				if (_nIgnoringNext <= 0)
				{
					_history.Add(Value);
					int num2 = _history.Count - _msHistoryDuration / base.UpdateInterval;
					if (num2 > 0)
					{
						_history.RemoveRange(0, num2);
					}
				}
				else
				{
					_nIgnoringNext--;
				}
			}
			if (flag && !readingsUsed.Contains(base.ReadingSource))
			{
				readingsUsed.Add(base.ReadingSource);
			}
		}

		public override void ClearHistory()
		{
			lock (_historyLock)
			{
				_history.Clear();
				_nIgnoringNext = _msIgnoreHistoryDuration / base.UpdateInterval;
			}
		}

		public override void History(out float minHistory, out float maxHistory)
		{
			if (_history.Count == 0)
			{
				minHistory = Value;
				maxHistory = Value;
			}
			else
			{
				minHistory = _history.Min();
				maxHistory = _history.Max();
			}
		}

		public override bool ZeroOut(ref Dictionary<Reading, float> values, int rx)
		{
			if (_scaleCalibration != null || _scaleCalibration.Count > 0)
			{
				float key = _scaleCalibration.OrderBy((KeyValuePair<float, PointF> p) => p.Key).First().Key;
				if (!values.ContainsKey(base.ReadingSource))
				{
					values.Add(base.ReadingSource, key);
				}
				else
				{
					values[base.ReadingSource] = key;
				}
				return true;
			}
			return false;
		}
	}

	internal class clsDataOut : clsMeterItem
	{
		public clsDataOut()
		{
			base.ItemType = MeterItemType.DATA_OUT;
			base.ReadingSource = Reading.NONE;
			base.UpdateInterval = 1000;
		}

		public override void Update(int rx, ref List<Reading> readingsUsed, Dictionary<Reading, object> all_list_item_readings = null)
		{
			if (all_list_item_readings == null || !MultiMeterIO.Data.ContainsKey(base.MMIOGuid))
			{
				return;
			}
			switch (MultiMeterIO.Data[base.MMIOGuid].FormatOut)
			{
			case MultiMeterIO.MMIOFormat.JSON:
			{
				Dictionary<string, string> dictionary = new Dictionary<string, string>();
				dictionary.Add("rx", rx.ToString());
				foreach (KeyValuePair<Reading, object> all_list_item_reading in all_list_item_readings)
				{
					if (all_list_item_reading.Value is float num3)
					{
						dictionary.Add(all_list_item_reading.Key.ToString().ToLower(), num3.ToString("0.0#####"));
					}
					if (all_list_item_reading.Value is double num4)
					{
						dictionary.Add(all_list_item_reading.Key.ToString().ToLower(), num4.ToString("0.0#####"));
					}
					else if (all_list_item_reading.Value is string value)
					{
						dictionary.Add(all_list_item_reading.Key.ToString().ToLower(), value);
					}
				}
				string data = JsonConvert.SerializeObject(dictionary, Formatting.None);
				MultiMeterIO.SendDataMMIO(base.MMIOGuid, data);
				break;
			}
			case MultiMeterIO.MMIOFormat.XML:
			{
				XElement xElement = new XElement("data");
				XElement content = new XElement("rx", rx.ToString());
				xElement.Add(content);
				foreach (KeyValuePair<Reading, object> all_list_item_reading2 in all_list_item_readings)
				{
					if (all_list_item_reading2.Value is float num5)
					{
						content = new XElement(all_list_item_reading2.Key.ToString().ToLower(), num5.ToString("0.0#####"));
					}
					if (all_list_item_reading2.Value is double num6)
					{
						content = new XElement(all_list_item_reading2.Key.ToString().ToLower(), num6.ToString("0.0#####"));
					}
					else if (all_list_item_reading2.Value is string content2)
					{
						content = new XElement(all_list_item_reading2.Key.ToString().ToLower(), content2);
					}
					xElement.Add(content);
				}
				MultiMeterIO.SendDataMMIO(base.MMIOGuid, xElement.ToString(SaveOptions.DisableFormatting));
				break;
			}
			case MultiMeterIO.MMIOFormat.RAW:
			{
				string text = "rx:" + rx + ":";
				foreach (KeyValuePair<Reading, object> all_list_item_reading3 in all_list_item_readings)
				{
					text = text + all_list_item_reading3.Key.ToString().ToLower() + ":";
					if (all_list_item_reading3.Value is float num)
					{
						text = text + num.ToString("0.0#####") + ":";
					}
					if (all_list_item_reading3.Value is double num2)
					{
						text = text + num2.ToString("0.0#####") + ":";
					}
					else if (all_list_item_reading3.Value is string text2)
					{
						text = text + text2.Replace(":", "") + ":";
					}
				}
				MultiMeterIO.SendDataMMIO(base.MMIOGuid, text);
				break;
			}
			}
		}
	}

