		public clsHistoryItem(clsMeter owning_meter, clsItemGroup item_group)
		{
			_owningmeter = owning_meter;
			_ig = item_group;
			_vertical_ratio = 0.5f;
			_back_colour = System.Drawing.Color.Black;
			_axis0_colour = System.Drawing.Color.Red;
			_axis1_colour = System.Drawing.Color.Yellow;
			_lines_colour = System.Drawing.Color.White;
			_time_colour = System.Drawing.Color.Gray;
			_history_data_list_0 = new List<HistoryData>();
			_history_data_list_1 = new List<HistoryData>();
			_reading_0 = Reading.SIGNAL_STRENGTH;
			_reading_1 = Reading.SIGNAL_STRENGTH;
			_keep_for = 60;
			_min_0 = float.MaxValue;
			_max_0 = float.MinValue;
			_min_1 = float.MaxValue;
			_max_1 = float.MinValue;
			_min_0_manual = -150f;
			_max_0_manual = 0f;
			_min_1_manual = -150f;
			_max_1_manual = 0f;
			_removed = 0;
			_auto_scale_0 = true;
			_auto_scale_1 = true;
			_show_scale_1 = false;
			_time_labels_max = 2;
			_active_time_labels = 0;
			_last_time_label_add_time = DateTime.UtcNow;
			_next_add_make_time_label = true;
			_axis_0_MMIOGuid = Guid.Empty;
			_axis_0_MMIOVariable = "--DEFAULT--";
			_axis_1_MMIOGuid = Guid.Empty;
			_axis_1_MMIOVariable = "--DEFAULT--";
			base.ItemType = MeterItemType.HISTORY;
			base.ReadingSource = Reading.SIGNAL_STRENGTH;
			base.UpdateInterval = 100;
		}

		public override bool ZeroOut(ref Dictionary<Reading, float> values, int rx)
		{
			float value = 0f;
			ZeroReading(out value, rx, _reading_0);
			if (!values.ContainsKey(_reading_0))
			{
				values.Add(_reading_0, value);
			}
			else
			{
				values[_reading_0] = value;
			}
			ZeroReading(out value, rx, _reading_1);
			if (!values.ContainsKey(_reading_1))
			{
				values.Add(_reading_1, value);
			}
			else
			{
				values[_reading_1] = value;
			}
			return true;
		}

		private void addReading(int axis, float value)
		{
			DateTime utcNow = DateTime.UtcNow;
			if (axis == 0)
			{
				lock (_history_data_list_lock_0)
				{
					HistoryData historyData;
					if (_history_data_list_0.Count > 0)
					{
						int num = 0;
						historyData = _history_data_list_0[0];
						while ((utcNow - historyData.time).TotalSeconds > (double)_keep_for)
						{
							if (historyData.show_time)
							{
								_active_time_labels--;
								if (_active_time_labels < 0)
								{
									_active_time_labels = 0;
								}
							}
							_history_data_list_0.RemoveAt(0);
							if (_history_data_list_0.Count <= 0)
							{
								break;
							}
							historyData = _history_data_list_0[0];
							num++;
						}
						_removed = num;
						if (num > 0 && _history_data_list_0.Count > 0)
						{
							_min_0 = _history_data_list_0.Min((HistoryData obj) => obj.value);
							_max_0 = _history_data_list_0.Max((HistoryData obj) => obj.value);
						}
					}
					bool flag = false;
					if (_next_add_make_time_label && utcNow.Second % 5 == 0)
					{
						flag = true;
					}
					historyData = new HistoryData
					{
						value = value,
						time = utcNow,
						show_time = flag
					};
					if (flag)
					{
						_active_time_labels++;
						_next_add_make_time_label = false;
						_last_time_label_add_time = DateTime.UtcNow;
					}
					_history_data_list_0.Add(historyData);
					if (value < _min_0)
					{
						_min_0 = value;
					}
					if (value > _max_0)
					{
						_max_0 = value;
					}
					_ = (_history_data_list_0[_history_data_list_0.Count - 1].time - _history_data_list_0[0].time).TotalSeconds;
				}
			}
			if (axis != 1)
			{
				return;
			}
			lock (_history_data_list_lock_1)
			{
				HistoryData historyData2;
				if (_history_data_list_1.Count > 0)
				{
					int num2 = 0;
					historyData2 = _history_data_list_1[0];
					while ((utcNow - historyData2.time).TotalSeconds > (double)_keep_for)
					{
						_history_data_list_1.RemoveAt(0);
						if (_history_data_list_1.Count <= 0)
						{
							break;
						}
						historyData2 = _history_data_list_1[0];
						num2++;
					}
					_removed = num2;
					if (num2 > 0 && _history_data_list_1.Count > 0)
					{
						_min_1 = _history_data_list_1.Min((HistoryData obj) => obj.value);
						_max_1 = _history_data_list_1.Max((HistoryData obj) => obj.value);
					}
				}
				historyData2 = new HistoryData
				{
					value = value,
					time = utcNow
				};
				_history_data_list_1.Add(historyData2);
				if (value < _min_1)
				{
					_min_1 = value;
				}
				if (value > _max_1)
				{
					_max_1 = value;
				}
			}
		}

		public override void Update(int rx, ref List<Reading> readingsUsed, Dictionary<Reading, object> all_list_item_readings = null)
		{
			float value;
			if (_axis_0_MMIOGuid == Guid.Empty)
			{
				value = getReading(rx, _reading_0);
				if (!readingsUsed.Contains(_reading_0))
				{
					readingsUsed.Add(_reading_0);
				}
			}
			else
			{
				value = 0f;
				if (MultiMeterIO.Data.ContainsKey(_axis_0_MMIOGuid))
				{
					MultiMeterIO.clsMMIO clsMMIO = MultiMeterIO.Data[_axis_0_MMIOGuid];
					if (clsMMIO == null)
					{
						return;
					}
					object variable = clsMMIO.GetVariable(_axis_0_MMIOVariable);
					if (variable is int)
					{
						value = (int)variable;
					}
					else if (variable is float)
					{
						value = (float)variable;
					}
					else if (variable is double)
					{
						value = (float)(double)variable;
					}
				}
			}
			addReading(0, value);
			if (!_show_scale_1)
			{
				return;
			}
			float value2;
			if (_axis_1_MMIOGuid == Guid.Empty)
			{
				value2 = getReading(rx, _reading_1);
				if (!readingsUsed.Contains(_reading_1))
				{
					readingsUsed.Add(_reading_1);
				}
			}
			else
			{
				value2 = 0f;
				if (MultiMeterIO.Data.ContainsKey(_axis_1_MMIOGuid))
				{
					MultiMeterIO.clsMMIO clsMMIO2 = MultiMeterIO.Data[_axis_1_MMIOGuid];
					if (clsMMIO2 == null)
					{
						return;
					}
					object variable2 = clsMMIO2.GetVariable(_axis_1_MMIOVariable);
					if (variable2 is int)
					{
						value2 = (int)variable2;
					}
					else if (variable2 is float)
					{
						value2 = (float)variable2;
					}
					else if (variable2 is double)
					{
						value2 = (float)(double)variable2;
					}
				}
			}
			addReading(1, value2);
		}
	}

