		public float Low
		{
			get
			{
				if (_owningmeter.MOX)
				{
					switch (_showVfoA ? _owningmeter.ModeVfoA : _owningmeter.ModeVfoB)
					{
					case DSPMode.DSB:
					case DSPMode.FM:
					case DSPMode.AM:
					case DSPMode.SPEC:
					case DSPMode.SAM:
					case DSPMode.DRM:
						return -_tx_high;
					default:
						return _tx_low;
					}
				}
				return _showVfoA ? _vfoA_low : _vfoB_low;
			}
			set
			{
				if (_console == null)
				{
					return;
				}
				if (_owningmeter.MOX)
				{
					DSPMode mode = (_showVfoA ? _owningmeter.ModeVfoA : _owningmeter.ModeVfoB);
					float val = (Common.CtrlKeyDown ? ((float)(Math.Round(value / 10f) * 10.0)) : value);
					if (!_snap_lines_ignore && _snap_lines && !_auto_zoom)
					{
						val = findNearestVGrid((int)val);
					}
					_console.BeginInvoke((MethodInvoker)delegate
					{
						switch (mode)
						{
						case DSPMode.LSB:
						case DSPMode.DSB:
						case DSPMode.FM:
						case DSPMode.AM:
						case DSPMode.SPEC:
						case DSPMode.DIGL:
						case DSPMode.SAM:
						case DSPMode.DRM:
							if (val > 0f)
							{
								val = 0f;
							}
							_console.TXFilterHigh = (int)Math.Abs(val);
							break;
						default:
							if (val < 0f)
							{
								val = 0f;
							}
							_console.TXFilterLow = (int)Math.Abs(val);
							break;
						}
					});
					return;
				}
				int low = (int)(Common.CtrlKeyDown ? ((float)(Math.Round(value / 10f) * 10.0)) : value);
				if (!_snap_lines_ignore && _snap_lines && !_auto_zoom)
				{
					low = findNearestVGrid(low);
				}
				if ((_showVfoA ? _vfoA_low : _vfoB_low) == low)
				{
					return;
				}
				_console.BeginInvoke((MethodInvoker)delegate
				{
					bool flag = _console.CurrentDSPhasTwoSidebands(_owningmeter.RX) && !Common.ShiftKeyDown;
					if (_owningmeter.RX == 1)
					{
						int rX1FilterHigh = _console.RX1FilterHigh;
						_console.SelectRX1VarFilter(update: true, prevent_update: true);
						if (flag)
						{
							if (low > 0)
							{
								low = 0;
							}
							_console.UpdateRX1Filters(low, Math.Abs(low));
						}
						else
						{
							if (low > rX1FilterHigh - 10)
							{
								low = rX1FilterHigh - 10;
							}
							_console.UpdateRX1Filters(low, rX1FilterHigh);
						}
					}
					else if (_owningmeter.RX == 2)
					{
						int rX2FilterHigh = _console.RX2FilterHigh;
						_console.SelectRX2VarFilter(update: true, prevent_update: true);
						if (flag)
						{
							if (low > 0)
							{
								low = 0;
							}
							_console.UpdateRX2Filters(low, Math.Abs(low));
						}
						else
						{
							if (low > rX2FilterHigh - 10)
							{
								low = rX2FilterHigh - 10;
							}
							_console.UpdateRX2Filters(low, rX2FilterHigh);
						}
					}
				});
			}
		}

		public float High
		{
			get
			{
				if (_owningmeter.MOX)
				{
					if (!_showVfoA)
					{
						_ = _owningmeter.ModeVfoB;
					}
					else
					{
						_ = _owningmeter.ModeVfoA;
					}
					return _tx_high;
				}
				return _showVfoA ? _vfoA_high : _vfoB_high;
			}
			set
			{
				if (_console == null)
				{
					return;
				}
				if (_owningmeter.MOX)
				{
					DSPMode mode = (_showVfoA ? _owningmeter.ModeVfoA : _owningmeter.ModeVfoB);
					float val = (Common.CtrlKeyDown ? ((float)(Math.Round(value / 10f) * 10.0)) : value);
					if (!_snap_lines_ignore && _snap_lines && !_auto_zoom)
					{
						val = findNearestVGrid((int)val);
					}
					_console.BeginInvoke((MethodInvoker)delegate
					{
						DSPMode dSPMode = mode;
						if (dSPMode == DSPMode.LSB || dSPMode == DSPMode.DIGL)
						{
							if (val > 0f)
							{
								val = 0f;
							}
							_console.TXFilterLow = (int)Math.Abs(val);
						}
						else
						{
							if (val < 0f)
							{
								val = 0f;
							}
							_console.TXFilterHigh = (int)Math.Abs(val);
						}
					});
					return;
				}
				int high = (int)(Common.CtrlKeyDown ? ((float)(Math.Round(value / 10f) * 10.0)) : value);
				if (!_snap_lines_ignore && _snap_lines && !_auto_zoom)
				{
					high = findNearestVGrid(high);
				}
				if ((_showVfoA ? _vfoA_high : _vfoB_high) == high)
				{
					return;
				}
				_console.BeginInvoke((MethodInvoker)delegate
				{
					bool flag = _console.CurrentDSPhasTwoSidebands(_owningmeter.RX) && !Common.ShiftKeyDown;
					if (_owningmeter.RX == 1)
					{
						int rX1FilterLow = _console.RX1FilterLow;
						_console.SelectRX1VarFilter(update: true, prevent_update: true);
						if (flag)
						{
							if (high < 0)
							{
								high = 0;
							}
							_console.UpdateRX1Filters(-high, high);
						}
						else
						{
							if (high < rX1FilterLow + 10)
							{
								high = rX1FilterLow + 10;
							}
							_console.UpdateRX1Filters(rX1FilterLow, high);
						}
					}
					else if (_owningmeter.RX == 2)
					{
						int rX2FilterLow = _console.RX2FilterLow;
						_console.SelectRX2VarFilter(update: true, prevent_update: true);
						if (flag)
						{
							if (high < 0)
							{
								high = 0;
							}
							_console.UpdateRX2Filters(-high, high);
						}
						else
						{
							if (high < rX2FilterLow + 10)
							{
								high = rX2FilterLow + 10;
							}
							_console.UpdateRX2Filters(rX2FilterLow, high);
						}
					}
				});
			}
		}

