		public int WaterfallMin
		{
			get
			{
				lock (_spec_data_lock)
				{
					if (_owningmeter.MOX)
					{
						return _tx_waterfall_min;
					}
					int result;
					if (_owningmeter.RX == 1)
					{
						if (Display.SpectrumBasedThresholdsRX1)
						{
							result = _rx_spec_grid_min;
						}
						else if (Display.RX1WaterfallAGC)
						{
							if (Display.WaterfallUseNFForACGRX1)
							{
								if (!Display.FastAttackNoiseFloorRX1 && Display.IsNoiseFloorGoodRX1)
								{
									result = (int)Display.ActiveNoiseFloorRX1;
								}
								else
								{
									float waterfall_min_agc_rx = _waterfall_min_agc_rx * 0.6f + Display.ActiveNoiseFloorRX1 * 0.4f;
									_waterfall_min_agc_rx = waterfall_min_agc_rx;
									result = (int)_waterfall_min_agc_rx;
								}
							}
							else if (_owningmeter.MOX)
							{
								float waterfall_min_agc_tx = _waterfall_min_agc_tx * 0.6f + _spec_raw_min * 0.4f;
								_waterfall_min_agc_tx = waterfall_min_agc_tx;
								result = (int)_waterfall_min_agc_tx;
							}
							else
							{
								float waterfall_min_agc_rx2 = _waterfall_min_agc_rx * 0.6f + _spec_raw_min * 0.4f;
								_waterfall_min_agc_rx = waterfall_min_agc_rx2;
								result = (int)_waterfall_min_agc_rx;
							}
							result -= (int)Display.WaterfallAGCOffsetRX1;
						}
						else
						{
							result = _rx_waterfall_min;
						}
					}
					else if (Display.SpectrumBasedThresholdsRX2)
					{
						result = _rx_spec_grid_min;
					}
					else if (Display.RX2WaterfallAGC)
					{
						if (Display.WaterfallUseNFForACGRX2)
						{
							if (!Display.FastAttackNoiseFloorRX2 && Display.IsNoiseFloorGoodRX2)
							{
								result = (int)Display.ActiveNoiseFloorRX2;
							}
							else
							{
								float waterfall_min_agc_rx3 = _waterfall_min_agc_rx * 0.6f + Display.ActiveNoiseFloorRX2 * 0.4f;
								_waterfall_min_agc_rx = waterfall_min_agc_rx3;
								result = (int)_waterfall_min_agc_rx;
							}
						}
						else if (_owningmeter.MOX)
						{
							float waterfall_min_agc_tx2 = _waterfall_min_agc_tx * 0.6f + _spec_raw_min * 0.4f;
							_waterfall_min_agc_tx = waterfall_min_agc_tx2;
							result = (int)_waterfall_min_agc_tx;
						}
						else
						{
							float waterfall_min_agc_rx4 = _waterfall_min_agc_rx * 0.6f + _spec_raw_min * 0.4f;
							_waterfall_min_agc_rx = waterfall_min_agc_rx4;
							result = (int)_waterfall_min_agc_rx;
						}
						result -= (int)Display.WaterfallAGCOffsetRX2;
					}
					else
					{
						result = _rx_waterfall_min;
					}
					return result;
				}
			}
		}

