		public int findNearestVGrid(int hz)
		{
			float[] vGridFrequencies = VGridFrequencies;
			if (vGridFrequencies.Length == 0)
			{
				return hz;
			}
			float num = vGridFrequencies[0];
			float num2 = Math.Abs((float)hz - num);
			float[] array = vGridFrequencies;
			foreach (float num3 in array)
			{
				if ((SidebandModeSign >= 0 || !(num3 > 0f)) && (SidebandModeSign <= 0 || !(num3 < 0f)))
				{
					float num4 = Math.Abs((float)hz - num3);
					if (num4 < num2)
					{
						num2 = num4;
						num = num3;
					}
				}
			}
			return (int)num;
		}

