		public override void MouseUp(MouseEventArgs e)
		{
			if (_console == null)
			{
				return;
			}
			bool exit = false;
			_console.Invoke((MethodInvoker)delegate
			{
				if ((DateTime.UtcNow - _console.NotchPopupLastDeactivateTime).TotalMilliseconds <= 500.0)
				{
					exit = true;
				}
			});
			if (exit)
			{
				return;
			}
			if (e.Button == MouseButtons.Right && _top_selected)
			{
				int num = (int)(High - Low);
				int num2 = (int)High;
				int num3 = (int)Low;
				switch (_showVfoA ? _owningmeter.ModeVfoA : _owningmeter.ModeVfoB)
				{
				case DSPMode.DSB:
				case DSPMode.FM:
				case DSPMode.AM:
				case DSPMode.SPEC:
				case DSPMode.SAM:
				case DSPMode.DRM:
					num3 = -num / 2;
					num2 = num / 2;
					break;
				case DSPMode.LSB:
					num2 = -_console.DefaultLowCut;
					num3 = num2 - num;
					break;
				case DSPMode.USB:
					num3 = _console.DefaultLowCut;
					num2 = num3 + num;
					break;
				case DSPMode.DIGL:
					num2 = -_console.DIGLClickTuneOffset + num / 2;
					num3 = -_console.DIGLClickTuneOffset - num / 2;
					break;
				case DSPMode.DIGU:
					num3 = _console.DIGUClickTuneOffset - num / 2;
					num2 = _console.DIGUClickTuneOffset + num / 2;
					break;
				case DSPMode.CWL:
					num2 = -_console.CWPitch + num / 2;
					num3 = -_console.CWPitch - num / 2;
					break;
				case DSPMode.CWU:
					num3 = _console.CWPitch - num / 2;
					num2 = _console.CWPitch + num / 2;
					break;
				}
				_snap_lines_ignore = true;
				Low = num3;
				High = num2;
				_snap_lines_ignore = false;
				_top_selected = false;
				return;
			}
			if (e.Button == MouseButtons.Right && _notch_highlighted_index != -1 && !Common.CtrlKeyDown)
			{
				if (_console != null)
				{
					int index = _notch_highlighted_index;
					_console.BeginInvoke((MethodInvoker)delegate
					{
						int x = Cursor.Position.X - 16;
						int y = Cursor.Position.Y - 16;
						_console.ShowNotchPopup(x, y, null, 0, 1000, on_top: true, index);
					});
				}
				_notch_selected = false;
				_notch_highlighted_index = -1;
				_notch_start_freq = -1.0;
				return;
			}
			_low_selected = false;
			_high_selected = false;
			_top_selected = false;
			_notch_selected = false;
			_notch_highlighted_index = -1;
			_notch_start_freq = -1.0;
			lock (_mouse_frequency_locker)
			{
				if (e.Button == MouseButtons.Right && Common.CtrlKeyDown && _mouse_frequency != -1.0 && !_owningmeter.MOX)
				{
					if (_console != null)
					{
						double freq = (_showVfoA ? (_owningmeter.VfoA * 1000000.0) : (_owningmeter.VfoB * 1000000.0));
						freq = Math.Round(freq + _mouse_frequency);
						_console.BeginInvoke((MethodInvoker)delegate
						{
							_console.AddNotch(freq, _owningmeter.RX);
						});
					}
					_mouse_frequency = -1.0;
					return;
				}
			}
			float num4 = (Common.ShiftKeyDown ? 1 : 10);
			if (_adjust_low)
			{
				_snap_lines_ignore = true;
				if (e.Button == MouseButtons.Left)
				{
					Low -= num4;
				}
				if (e.Button == MouseButtons.Right)
				{
					Low += num4;
				}
				_snap_lines_ignore = false;
			}
			if (_adjust_high)
			{
				_snap_lines_ignore = true;
				if (e.Button == MouseButtons.Left)
				{
					High -= num4;
				}
				if (e.Button == MouseButtons.Right)
				{
					High += num4;
				}
				_snap_lines_ignore = false;
			}
			if (_adjust_shift)
			{
				_start_low = Low;
				_start_high = High;
				if (e.Button == MouseButtons.Left)
				{
					Shift(0f - num4);
				}
				if (e.Button == MouseButtons.Right)
				{
					Shift(num4);
				}
			}
			if (_mnf_selected)
			{
				_console.BeginInvoke((MethodInvoker)delegate
				{
					_console.TNFActive = !_console.TNFActive;
				});
			}
			else if (_mnf_plus_selected && !_owningmeter.MOX)
			{
				_console.BeginInvoke((MethodInvoker)delegate
				{
					_console.TNFAdd(_owningmeter.RX);
				});
			}
			else if (_snap_selected && !_auto_zoom)
			{
				_snap_lines = !_snap_lines;
			}
			else if (_autozoom_selected)
			{
				_auto_zoom = !_auto_zoom;
			}
		}

		public override void MouseWheel(int number_of_moves)
		{
			int num = Math.Sign(number_of_moves);
			float num2 = (Common.ShiftKeyDown ? 1 : 10);
			_snap_lines_ignore = true;
			if (_notch_highlighted_index == -1 && !_notch_selected)
			{
				if (_adjust_low)
				{
					float num3 = (Common.CtrlKeyDown ? ((float)(Math.Round(Low / 10f) * 10.0)) : Low);
					Low = num3 + (float)num * num2;
				}
				else if (_adjust_high)
				{
					float num4 = (Common.CtrlKeyDown ? ((float)(Math.Round(High / 10f) * 10.0)) : High);
					High = num4 + (float)num * num2;
				}
				else if (_adjust_shift)
				{
					_start_low = Low;
					_start_high = High;
					Shift((float)num * num2);
				}
			}
			else
			{
				if (_console == null || _notch_highlighted_index == -1)
				{
					return;
				}
				bool flag = false;
				double width = 0.0;
				lock (MiniSpec.NotchLocker)
				{
					MiniSpec.Notch notch = MiniSpec.GetNotch(_notch_highlighted_index);
					if (notch != null)
					{
						width = notch.width_hz;
						flag = true;
					}
				}
				if (flag)
				{
					width += (float)num * num2;
					if (width < 0.0)
					{
						width = 0.0;
					}
					_console.BeginInvoke((MethodInvoker)delegate
					{
						_console.ChangeNotchBW(null, width, _notch_highlighted_index);
					});
				}
			}
			_snap_lines_ignore = false;
		}

		public void AdjustNotch(float delta)
		{
			if (_console == null || !_notch_selected || _notch_highlighted_index == -1)
			{
				return;
			}
			bool flag = false;
			double new_freq = (double)(int)delta + _notch_start_freq;
			new_freq = (Common.CtrlKeyDown ? ((double)(float)(Math.Round(new_freq / 10.0) * 10.0)) : new_freq);
			lock (MiniSpec.NotchLocker)
			{
				MiniSpec.Notch notch = MiniSpec.GetNotch(_notch_highlighted_index);
				if (notch != null)
				{
					double num = (_showVfoA ? _owningmeter.VfoA : _owningmeter.VfoB) * 1000000.0;
					flag = notch.frequency_hz != new_freq && new_freq >= num - (double)_extent_hz && new_freq <= num + (double)_extent_hz;
					if (flag)
					{
						notch.frequency_hz = new_freq;
					}
				}
			}
			if (flag)
			{
				_console.BeginInvoke((MethodInvoker)delegate
				{
					_console.ChangeNotchCentreFrequency(null, new_freq, _owningmeter.RX, _notch_highlighted_index);
				});
			}
		}

		public void Shift(float shift_hz)
		{
			if (_owningmeter.MOX || shift_hz == 0f)
			{
				return;
			}
			float num = (int)shift_hz;
			float num2 = _start_low + num;
			float num3 = _start_high + num;
			if (Common.CtrlKeyDown)
			{
				num2 = (float)(Math.Round(num2 / 10f) * 10.0);
				num3 = (float)(Math.Round(num3 / 10f) * 10.0);
			}
			int low = (int)num2;
			int high = (int)num3;
			_console.BeginInvoke((MethodInvoker)delegate
			{
				_console.ConstrainFilter(ref low, ref high, _owningmeter.RX, filterShift: true);
				if (_owningmeter.RX == 1)
				{
					_console.SelectRX1VarFilter(update: true, prevent_update: true);
					_console.UpdateRX1Filters(low, high);
				}
				else if (_owningmeter.RX == 2)
				{
					_console.SelectRX2VarFilter(update: true, prevent_update: true);
					_console.UpdateRX2Filters(low, high);
				}
			});
		}

		private void buildSpectrumGreyScale(bool do_low, bool do_high)
		{
			if (!_use_greyscale || (!do_low && !do_high))
			{
				return;
			}
			lock (_spec_data_lock)
			{
				float num = (_owningmeter.MOX ? ((float)_tx_extent_hz * 2f) : ((float)_extent_hz * 2f));
				if (_owningmeter.MOX)
				{
					_ = _owningmeter.MinNotchWidthTX;
				}
				else
					_ = _owningmeter.MinNotchWidthRX;
				float num2 = num / (float)_spec_data.Length;
				int num3 = _spec_data.Length / 2;
				int num4 = num3 + (int)(Low / num2);
				int num5 = num3 + (int)(High / num2);
				for (int i = 0; i < _spec_greyscale.Length; i++)
				{
					if (do_low && i < num4)
					{
						_spec_greyscale[i] = 1f;
					}
					else if (do_high && i > num5)
					{
						_spec_greyscale[i] = 1f;
					}
					else if (i >= num4 && i <= num5)
					{
						_spec_greyscale[i] = 0f;
					}
				}
			}
		}

		public unsafe override void Update(int rx, ref List<Reading> readingsUsed, Dictionary<Reading, object> all_list_item_readings = null)
		{
			int id = ((_owningmeter.RX != 1) ? 1 : 0);
			if (MiniSpec.GetMiniRX(id) == null)
			{
				return;
			}
			int dataIndex = MiniSpec.GetMiniRX(id).DataIndex;
			if (dataIndex == _old_data_index)
			{
				return;
			}
			float[] data = MiniSpec.GetMiniRX(id).Data;
			if (data != null)
			{
				lock (_spec_data_lock)
				{
					if (data.Length != _spec_data.Length)
					{
						_spec_data = new float[data.Length];
						_spec_greyscale = new float[data.Length];
						for (int i = 0; i < _spec_data.Length; i++)
						{
							_spec_data[i] = _spec_min;
						}
						buildSpectrumGreyScale(do_low: true, do_high: true);
					}
					fixed (float* ptr = &data[0])
					{
						void* srcptr = ptr;
						fixed (float* ptr2 = &_spec_data[0])
						{
							void* destptr = ptr2;
							Win32.memcpy(destptr, srcptr, _spec_data.Length * 4);
						}
					}
					float[] dataRaw = MiniSpec.GetMiniRX(id).DataRaw;
					fixed (float* ptr = &dataRaw[0])
					{
						void* srcptr2 = ptr;
						fixed (float* ptr2 = &_spec_data_raw[0])
						{
							void* destptr2 = ptr2;
							Win32.memcpy(destptr2, srcptr2, dataRaw.Length * 4);
						}
					}
					_spec_min = _spec_data.Min();
					_spec_max = _spec_data.Max();
					_spec_raw_min = _spec_data_raw.Min();
					_spec_raw_max = _spec_data_raw.Max();
				}
			}
			_old_data_index = dataIndex;
		}

