						else if (Enum.TryParse<Reading>(placeholder.ToUpper(), out result))
						{
							_list_placeholders_readings_2.Add(result);
						}
					}
					string parsed_text_ = _parsed_text_2;
					_parsed_text_2 = parseText(_owningMeter.RX, 2);
					if (_parsed_text_2 != parsed_text_)
					{
						_x_scroll_count_2 = 0;
					}
				}
			}
		}

