		public override void Update(int rx, ref List<Reading> readingsUsed, Dictionary<Reading, object> all_list_item_readings = null)
		{
			lock (_list_placeholders_1_lock)
			{
				foreach (Reading item in _list_placeholders_readings_1)
				{
					ReadingsCustom(_owningMeter.RX).TakeReading(item);
				}
				string parsed_text_ = _parsed_text_1;
				_parsed_text_1 = parseText(_owningMeter.RX, 1);
				if (_parsed_text_1 != parsed_text_)
				{
					_x_scroll_count_1 = 0;
				}
			}
			lock (_list_placeholders_2_lock)
			{
				foreach (Reading item2 in _list_placeholders_readings_2)
				{
					ReadingsCustom(_owningMeter.RX).TakeReading(item2);
				}
				string parsed_text_2 = _parsed_text_2;
				_parsed_text_2 = parseText(_owningMeter.RX, 2);
				if (_parsed_text_2 != parsed_text_2)
				{
					_x_scroll_count_2 = 0;
				}
			}
			if (_rx_led_logic)
			{
				_led_results.TryGetValue(_rx_four_char, out _show_rx);
			}
			if (_rx_led_logic)
			{
				_led_results.TryGetValue(_tx_four_char, out _show_tx);
			}
		}

		private string parseText(int rx, int text_line)
		{
			if (rx < 1 || rx > 2)
			{
				return "";
			}
			string text = "";
			bool flag = false;
			string text2 = "0.0#####";
			object obj;
			List<string> list;
			List<Reading> list2;
			switch (text_line)
			{
			case 1:
				text = _text_1;
				obj = _list_placeholders_1_lock;
				list = _list_placeholders_strings_1;
				list2 = _list_placeholders_readings_1;
				break;
			case 2:
				text = _text_2;
				obj = _list_placeholders_2_lock;
				list = _list_placeholders_strings_2;
				list2 = _list_placeholders_readings_2;
				break;
			default:
				return "";
			}
			lock (obj)
			{
				foreach (string item in list)
				{
					string text3 = "%" + item + "%";
					if (text.IndexOf(text3, StringComparison.OrdinalIgnoreCase) < 0 || text3.IndexOf("%precis=", StringComparison.OrdinalIgnoreCase) < 0)
					{
						continue;
					}
					text = text.ReplaceIgnoreTokenCase(text3, "");
					if (flag)
					{
						continue;
					}
					int num = text3.IndexOf('=') + 1;
					int num2 = text3.Length - 1;
					string text4 = text3.Substring(num, num2 - num);
					if (text4.Length > 0 && int.TryParse(text4, out var result))
					{
						if (result > 20)
						{
							result = 20;
						}
						if (result < 0)
						{
							result = 0;
						}
						text2 = $"f{result}";
						flag = true;
					}
				}
				foreach (string item2 in list)
				{
					string text3 = "%" + item2 + "%";
					if (text.IndexOf(text3, StringComparison.OrdinalIgnoreCase) >= 0)
					{
						string text5 = (flag ? text2 : "0.0#####");
						object reading = ReadingsCustom(rx).GetReading(item2, _owningMeter);
						text = ((!(reading is int)) ? ((!(reading is float)) ? ((!(reading is double)) ? ((!(reading is bool)) ? text.ReplaceIgnoreTokenCase(text3, (string)reading) : text.ReplaceIgnoreTokenCase(text3, ((bool)reading).ToString())) : text.ReplaceIgnoreTokenCase(text3, ((double)reading).ToString(text5))) : text.ReplaceIgnoreTokenCase(text3, ((float)reading).ToString(text5))) : text.ReplaceIgnoreTokenCase(text3, ((int)reading).ToString()));
					}
				}
				foreach (Reading item3 in list2)
				{
					string text3 = "%" + item3.ToString() + "%";
					if (text.IndexOf(text3, StringComparison.OrdinalIgnoreCase) >= 0)
					{
						object reading2 = ReadingsCustom(rx).GetReading(item3.ToString(), _owningMeter);
						text = text.ReplaceIgnoreTokenCase(text3, ((float)reading2).ToString(flag ? text2 : "0.0#####"));
					}
				}
			}
			if (text.IndexOf("%nl%", StringComparison.OrdinalIgnoreCase) >= 0)
			{
				text = text.ReplaceIgnoreTokenCase("%nl%", "\n");
			}
			foreach (KeyValuePair<Guid, MultiMeterIO.clsMMIO> datum in MultiMeterIO.Data)
			{
				MultiMeterIO.clsMMIO value = datum.Value;
				foreach (KeyValuePair<string, object> item4 in value.Variables())
				{
					string text3 = "%" + item4.Key + "%";
					if (text.IndexOf(text3, StringComparison.OrdinalIgnoreCase) >= 0)
					{
						object variable = value.GetVariable(item4.Key, flag ? text2 : "");
						string replacement = value.VariableValueType(variable, flag ? text2 : "");
						text = text.ReplaceIgnoreTokenCase(text3, replacement);
					}
				}
			}
			foreach (KeyValuePair<string, string> cat_variable in _cat_variables)
			{
				string key = cat_variable.Key;
				string value2 = cat_variable.Value;
				text = text.ReplaceIgnoreTokenCase(key, value2);
			}
			return text;
		}

		public override bool ZeroOut(ref Dictionary<Reading, float> values, int rx)
		{
			lock (_list_placeholders_1_lock)
			{
				foreach (Reading item in _list_placeholders_readings_1)
				{
					float value = 0f;
					ZeroReading(out value, rx, item);
					if (!values.ContainsKey(item))
					{
						values.Add(item, value);
					}
					else
					{
						values[item] = value;
					}
				}
			}
			lock (_list_placeholders_2_lock)
			{
				foreach (Reading item2 in _list_placeholders_readings_2)
				{
					float value2 = 0f;
					ZeroReading(out value2, rx, item2);
					if (!values.ContainsKey(item2))
					{
						values.Add(item2, value2);
					}
					else
					{
						values[item2] = value2;
					}
				}
			}
			return true;
		}
	}

