		public override void Removing()
		{
			MeterScriptEngine.UnregisterLed(_led_id);
		}

		private void onTimerElapsedCondition()
		{
			_condition = _pending_condition;
			int rX = _owningMeter.RX;
			lock (_place_holder_lock)
			{
				_place_holders = ReadingsCustom(rX).GetPlaceholders(_condition);
			}
			add_readings(update_custom: true);
			string condition = expand_placeholders(_condition, rX);
			_valid = MeterScriptEngine.SetCondition(_led_id, condition);
		}

		public void UpdateReadings()
		{
			add_readings(update_custom: true);
		}

		private void add_readings(bool update_custom = false)
		{
			lock (_place_holder_lock)
			{
				int rX = _owningMeter.RX;
				foreach (string place_holder in _place_holders)
				{
					string text = place_holder;
					if (ReadingsCustom(rX).IsCustomString(text.ToLower()))
					{
						text = text.ToLower();
					}
					else
					{
						if (!Enum.TryParse<Reading>(text, ignoreCase: true, out var result))
						{
							if (_cat_variables.TryGetValue("%" + text + "%", out var value))
							{
								SetLedVariable(rX, text, value);
							}
							continue;
						}
						ReadingsCustom(rX).TakeReading(result);
						text = result.ToString();
					}
					if (update_custom)
					{
						ReadingsCustom(rX).UpdateReadings("%" + text + "%");
					}
					SetLedVariable(rX, text, ReadingsCustom(rX).GetReading(place_holder, _owningMeter));
				}
			}
		}

		private string expand_placeholders(string expr, int rx)
		{
			if (string.IsNullOrEmpty(expr))
			{
				return string.Empty;
			}
			if (rx < 1 || rx > 2)
			{
				return string.Empty;
			}
			StringBuilder stringBuilder = new StringBuilder(expr.Length * 4);
			int num = 0;
			int length = expr.Length;
			while (num < length)
			{
				int num2 = expr.IndexOf('%', num);
				if (num2 < 0)
				{
					stringBuilder.Append(expr, num, length - num);
					break;
				}
				int num3 = expr.IndexOf('%', num2 + 1);
				if (num3 < 0)
				{
					stringBuilder.Append(expr, num, length - num);
					break;
				}
				stringBuilder.Append(expr, num, num2 - num);
				string text = expr.Substring(num2 + 1, num3 - num2 - 1);
				Reading result;
				if (ReadingsCustom(_owningMeter.RX).IsCustomString(text.ToLower()))
				{
					text = text.ToLower();
				}
				else if (Enum.TryParse<Reading>(text, ignoreCase: true, out result))
				{
					text = result.ToString();
				}
				else
				{
					_cat_variables.TryGetValue("%" + text + "%", out var _);
				}
				stringBuilder.Append("Variables[");
				stringBuilder.Append((rx - 1).ToString());
				stringBuilder.Append("][\"");
				stringBuilder.Append(text);
				stringBuilder.Append("\"]");
				num = num3 + 1;
			}
			return stringBuilder.ToString();
		}

		public void RebuildCondition()
		{
			_pending_condition = _condition;
			if (_timer == null)
			{
				_timer = new System.Threading.Timer(delegate
				{
					onTimerElapsedCondition();
				}, null, _delay_milliseconds, -1);
			}
			else
			{
				_timer.Change(_delay_milliseconds, -1);
			}
		}

		public override void Update(int rx, ref List<Reading> readingsUsed, Dictionary<Reading, object> all_list_item_readings = null)
		{
			if (_valid && !_busy)
			{
				_busy = true;
				add_readings();
				_old_result = _result;
				_result = MeterScriptEngine.ReadResult(_led_id);
				_led_results.AddOrUpdate(_four_char, _result, (string a, bool b) => _result);
				if (_result && _notxtrue && _console.MOX)
				{
					stopMox();
				}
				else if (!_result && _notxfalse && _console.MOX)
				{
					stopMox();
				}
				_busy = false;
			}
		}

		private void stopMox()
		{
			_console.BeginInvoke((MethodInvoker)delegate
			{
				_console.StopAllTx("Led Indicator stopped MOX");
			});
		}

		public override bool ZeroOut(ref Dictionary<Reading, float> values, int rx)
		{
			lock (_place_holder_lock)
			{
				foreach (string place_holder in _place_holders)
				{
					if (!ReadingsCustom(rx).IsCustomString(place_holder.ToLower()) && Enum.TryParse<Reading>(place_holder, ignoreCase: true, out var result))
					{
						float value = 0f;
						ZeroReading(out value, rx, result);
						if (!values.ContainsKey(result))
						{
							values.Add(result, value);
						}
						else
						{
							values[result] = value;
						}
					}
				}
			}
			return true;
		}
	}

