			_fontStyle = System.Drawing.FontStyle.Regular;
			_fontColor = System.Drawing.Color.DarkGray;
			_fontSize = 20f;
			base.ItemType = MeterItemType.H_BAR;
			base.ReadingSource = Reading.NONE;
			base.UpdateInterval = 100;
			base.AttackRatio = 0.8f;
			base.DecayRatio = 0.2f;
			base.StoreSettings = false;
			_postDrawItem = null;
		}

		public override void Update(int rx, ref List<Reading> readingsUsed, Dictionary<Reading, object> all_list_item_readings = null)
		{
			float num;
			bool flag;
			if (base.MMIOGuid == Guid.Empty)
			{
				num = getReading(rx, base.ReadingSource);
				flag = true;
			}
			else
			{
				num = 0f;
				if (MultiMeterIO.Data.ContainsKey(base.MMIOGuid))
				{
					object variable = MultiMeterIO.Data[base.MMIOGuid].GetVariable(base.MMIOVariable);
					if (variable is int)
					{
						num = (int)variable;
					}
					else if (variable is float)
					{
						num = (float)variable;
					}
					else if (variable is double)
					{
						num = (float)(double)variable;
					}
				}
				flag = false;
			}
			lock (_historyLock)
			{
				if (num > Value)
				{
					Value = num * base.AttackRatio + Value * (1f - base.AttackRatio);
				}
				else
				{
					Value = num * base.DecayRatio + Value * (1f - base.DecayRatio);
				}
				if (_nIgnoringNext <= 0)
				{
					_history.Add(Value);
					int num2 = _history.Count - _msHistoryDuration / base.UpdateInterval;
					if (num2 > 0)
					{
						_history.RemoveRange(0, num2);
					}
				}
				else
				{
					_nIgnoringNext--;
				}
			}
			if (flag && !readingsUsed.Contains(base.ReadingSource))
			{
				readingsUsed.Add(base.ReadingSource);
			}
		}

		public override void ClearHistory()
		{
			lock (_historyLock)
			{
				_history.Clear();
				_nIgnoringNext = _msIgnoreHistoryDuration / base.UpdateInterval;
			}
		}

		public override void History(out float minHistory, out float maxHistory)
		{
			if (_history.Count == 0)
			{
				minHistory = Value;
				maxHistory = Value;
			}
			else
			{
				minHistory = _history.Min();
				maxHistory = _history.Max();
			}
		}

		public override void HandleIncrement()
		{
			int units = (int)_units;
			units++;
			if (base.ReadingSource != Reading.ESTIMATED_PBSNR)
			{
				if (units > 2)
				{
					units = 0;
				}
			}
			else if (units > 1)
			{
				units = 0;
			}
			_units = (Units)units;
		}

		public override void HandleDecrement()
		{
			int units = (int)_units;
			units--;
			if (base.ReadingSource != Reading.ESTIMATED_PBSNR)
			{
				if (units < 0)
				{
					units = 2;
				}
			}
			else if (units < 0)
			{
				units = 1;
			}
			_units = (Units)units;
		}

		public override bool ZeroOut(ref Dictionary<Reading, float> values, int rx)
		{
			if (_scaleCalibration != null || _scaleCalibration.Count > 0)
			{
				float value = _scaleCalibration.OrderBy((KeyValuePair<float, PointF> p) => p.Key).First().Key;
				ZeroReading(out value, rx, base.ReadingSource);
				if (!values.ContainsKey(base.ReadingSource))
				{
					values.Add(base.ReadingSource, value);
				}
				else
				{
					values[base.ReadingSource] = value;
				}
				return true;
			}
			return false;
		}
	}

