		public override float Value
		{
			get
			{
				return base.Value;
			}
			set
			{
				base.Value = value;
				updateReadingText(value);
			}
		}

		public clsText()
		{
			_sText = "";
			_fontFamily = "Trebuchet MS";
			_fontStyle = System.Drawing.FontStyle.Regular;
			_color = System.Drawing.Color.White;
			_centred = false;
			_fontSize = 9f;
			_readingText = "";
			base.ItemType = MeterItemType.TEXT;
			base.ReadingSource = Reading.NONE;
			base.UpdateInterval = int.MaxValue;
			base.StoreSettings = false;
		}

		private void updateReadingText(float reading)
		{
			string sText = _sText;
			if (!(sText == "%valueWithType%"))
			{
				if (sText == "%value%")
				{
					_readingText = reading.ToString("0.0");
				}
				else
				{
					_readingText = "";
				}
			}
			else
			{
				_readingText = reading.ToString("0.0") + ReadingUnits(base.ReadingSource);
			}
		}

		public override void Update(int rx, ref List<Reading> readingsUsed, Dictionary<Reading, object> all_list_item_readings = null)
		{
			float reading = getReading(rx, base.ReadingSource);
			updateReadingText(reading);
			if (!readingsUsed.Contains(base.ReadingSource))
			{
				readingsUsed.Add(base.ReadingSource);
			}
		}
	}

