				_mox = value;
				lock (_meterItemsLock)
				{
					foreach (KeyValuePair<string, clsMeterItem> meterItem in _meterItems)
					{
						meterItem.Value.MOX = _mox;
					}
				}
				if (flag)
				{
					if (_mox)
					{
						_qso_start = DateTime.UtcNow;
