		public double VfoA
		{
			get
			{
				return _vfoA;
			}
			set
			{
				_vfoA = value;
				if (_rx == 1)
				{
					_rx1VHForAbove = _vfoA >= _s9Frequency;
				}
				lock (_timerLock_vfoA)
				{
					if ((DateTime.UtcNow - _last_band_text_update_vfoA).TotalMilliseconds > 250.0)
					{
						updateVfoABandText(null);
					}
					else if (_timer_band_text_vfoA == null)
					{
						_timer_band_text_vfoA = new System.Threading.Timer(updateVfoABandText, null, 250, -1);
					}
					else
					{
						_timer_band_text_vfoA.Change(250, -1);
					}
				}
			}
		}

		public double VfoB
		{
			get
			{
				return _vfoB;
			}
			set
			{
				_vfoB = value;
				if (_rx == 2)
				{
					_rx2VHForAbove = _vfoB >= _s9Frequency;
				}
				lock (_timerLock_vfoB)
				{
					if ((DateTime.UtcNow - _last_band_text_update_vfoB).TotalMilliseconds > 250.0)
					{
						updateVfoBBandText(null);
					}
					else if (_timer_band_text_vfoB == null)
					{
						_timer_band_text_vfoB = new System.Threading.Timer(updateVfoBBandText, null, 250, -1);
					}
					else
					{
						_timer_band_text_vfoB.Change(250, -1);
					}
				}
			}
		}

