		public int DisplayGroups => _displayGroups.Count;

		public int DisplayGroup
		{
			get
			{
				return _displayGroup;
			}
			set
			{
				_displayGroup = value;
				if (_displayGroup < 0)
				{
					_displayGroup = 0;
				}
				if (_displayGroup > _displayGroups.Count - 1)
				{
					_displayGroup = _displayGroups.Count - 1;
				}
			}
		}

		public string DisplayGroupText
		{
			get
			{
				if (_displayGroup < 0)
				{
					return "";
				}
				if (_displayGroup > _displayGroups.Count - 1)
				{
					return "";
				}
				return _displayGroups[_displayGroup];
			}
		}

