		public string MeterVariablesReadingString(MeterType meter, int variable_index)
		{
			string result = "";
			switch (meter)
			{
			case MeterType.SIGNAL_STRENGTH:
				result = Reading.SIGNAL_STRENGTH.ToString();
				break;
			case MeterType.AVG_SIGNAL_STRENGTH:
				result = Reading.AVG_SIGNAL_STRENGTH.ToString();
				break;
			case MeterType.SIGNAL_TEXT:
				result = Reading.SIGNAL_STRENGTH.ToString();
				break;
			case MeterType.ADC:
				result = ((variable_index == 0) ? Reading.ADC_PK.ToString() : Reading.ADC_AV.ToString());
				break;
			case MeterType.AGC:
				result = ((variable_index == 0) ? Reading.AGC_PK.ToString() : Reading.AGC_AV.ToString());
				break;
			case MeterType.AGC_GAIN:
				result = Reading.AGC_GAIN.ToString();
				break;
			case MeterType.MIC:
				result = ((variable_index == 0) ? Reading.MIC.ToString() : Reading.MIC_PK.ToString());
				break;
			case MeterType.PWR:
				result = Reading.PWR.ToString();
				break;
			case MeterType.REVERSE_PWR:
				result = Reading.REVERSE_PWR.ToString();
				break;
			case MeterType.ALC:
				result = ((variable_index == 0) ? Reading.ALC.ToString() : Reading.ALC_PK.ToString());
				break;
			case MeterType.EQ:
				result = ((variable_index == 0) ? Reading.EQ.ToString() : Reading.EQ_PK.ToString());
				break;
			case MeterType.LEVELER:
				result = ((variable_index == 0) ? Reading.LEVELER.ToString() : Reading.LEVELER_PK.ToString());
				break;
			case MeterType.COMP:
				result = ((variable_index == 0) ? Reading.COMP.ToString() : Reading.COMP_PK.ToString());
				break;
			case MeterType.ALC_GAIN:
				result = Reading.ALC_G.ToString();
				break;
			case MeterType.ALC_GROUP:
				result = Reading.ALC_GROUP.ToString();
				break;
			case MeterType.LEVELER_GAIN:
				result = Reading.LVL_G.ToString();
				break;
			case MeterType.CFC:
				result = ((variable_index == 0) ? Reading.CFC_AV.ToString() : Reading.CFC_PK.ToString());
				break;
			case MeterType.CFC_GAIN:
				result = Reading.CFC_G.ToString();
				break;
			case MeterType.MAGIC_EYE:
				result = Reading.SIGNAL_STRENGTH.ToString();
				break;
			case MeterType.ESTIMATED_PBSNR:
				result = Reading.ESTIMATED_PBSNR.ToString();
				break;
			case MeterType.CROSS:
				result = ((variable_index == 0) ? Reading.PWR.ToString() : Reading.REVERSE_PWR.ToString());
				break;
			case MeterType.SWR:
				result = Reading.SWR.ToString();
				break;
			case MeterType.VFO_DISPLAY:
				result = Reading.NONE.ToString();
				break;
			case MeterType.CLOCK:
				result = Reading.NONE.ToString();
				break;
			case MeterType.SPACER:
				result = Reading.NONE.ToString();
				break;
			case MeterType.TEXT_OVERLAY:
				result = Reading.NONE.ToString();
				break;
			case MeterType.LED:
				result = Reading.NONE.ToString();
				break;
			case MeterType.WEB_IMAGE:
				result = Reading.NONE.ToString();
				break;
			case MeterType.BAND_BUTTONS:
				result = Reading.NONE.ToString();
				break;
			case MeterType.MODE_BUTTONS:
				result = Reading.NONE.ToString();
				break;
			case MeterType.FILTER_BUTTONS:
				result = Reading.NONE.ToString();
				break;
			case MeterType.ANTENNA_BUTTONS:
				result = Reading.NONE.ToString();
				break;
			case MeterType.DATA_OUT:
				result = Reading.NONE.ToString();
				break;
			case MeterType.ROTATOR:
				result = ((variable_index == 0) ? Reading.AZ.ToString() : Reading.ELE.ToString());
				break;
			case MeterType.HISTORY:
				result = ((variable_index == 0) ? "Left Axis" : "Right Axis");
				break;
			case MeterType.TUNESTEP_BUTTONS:
				result = Reading.NONE.ToString();
				break;
			case MeterType.DISCORD_BUTTONS:
				result = Reading.NONE.ToString();
				break;
			case MeterType.FILTER_DISPLAY:
				result = Reading.NONE.ToString();
				break;
			case MeterType.DIAL_DISPLAY:
				result = Reading.NONE.ToString();
				break;
			case MeterType.CUSTOM_METER_BAR:
				result = ((variable_index == 0) ? "Primary" : "Secondary");
				break;
			case MeterType.SIGNAL_MAX_BIN:
				result = Reading.SIGNAL_MAX_BIN.ToString();
				break;
			case MeterType.OTHER_BUTTONS:
				result = Reading.NONE.ToString();
