		public void AddMeter(MeterType meter, clsItemGroup restoreIg = null)
		{
			float fBottom = 0f;
			int nMSupdate = 50;
			switch (meter)
			{
			case MeterType.SIGNAL_STRENGTH:
				AddSMeterBarSignal(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.AVG_SIGNAL_STRENGTH:
				AddSMeterBarSignalAvg(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.SIGNAL_TEXT:
				AddSMeterBarText(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.ADC:
				AddADCBar(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.AGC:
				AddAGCBar(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.AGC_GAIN:
				AddAGCGainBar(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.MIC:
				AddMicBar(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.PWR:
				AddPWRBar(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.REVERSE_PWR:
				AddREVPWRBar(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.ALC:
				AddALCBar(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.EQ:
				AddEQBar(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.LEVELER:
				AddLevelerBar(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.COMP:
				AddCompBar(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.ALC_GAIN:
				AddALCGainBar(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.ALC_GROUP:
				AddALCGroupBar(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.LEVELER_GAIN:
				AddLevelerGainBar(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.CFC:
				AddCFCBar(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.CFC_GAIN:
				AddCFCGainBar(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.MAGIC_EYE:
				AddMagicEye(nMSupdate, 0f, out fBottom, 0.2f, restoreIg);
				break;
			case MeterType.ESTIMATED_PBSNR:
				AddPBSNRBar(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.ANANMM:
				AddAnanMM(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.CROSS:
				AddCrossNeedle(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.SWR:
				AddSWRBar(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.VFO_DISPLAY:
				AddVFODisplay(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.CLOCK:
				AddClock(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.SPACER:
				AddSpacer(nMSupdate, 0f, out fBottom, 0.1f, restoreIg);
				break;
			case MeterType.TEXT_OVERLAY:
				AddTextOverlay(nMSupdate, 0f, out fBottom, 0.1f, restoreIg);
				break;
			case MeterType.LED:
				AddLed(nMSupdate, 0f, out fBottom, 0.1f, restoreIg);
				break;
			case MeterType.WEB_IMAGE:
				AddWebImage(nMSupdate, 0f, out fBottom, 0.1f, restoreIg);
				break;
			case MeterType.DATA_OUT:
				AddDataOut(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.ROTATOR:
				AddRotator(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.BAND_BUTTONS:
				AddBandButtons(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.MODE_BUTTONS:
				AddModeButtons(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.FILTER_BUTTONS:
				AddFilterButtons(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.ANTENNA_BUTTONS:
				AddAntennaButtons(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.HISTORY:
				AddHistory(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.TUNESTEP_BUTTONS:
				AddTunestepButtons(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.DISCORD_BUTTONS:
				AddDiscordButtons(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.FILTER_DISPLAY:
				AddFilterDisplay(nMSupdate, 0f, out fBottom, 0.2f, restoreIg);
				break;
			case MeterType.DIAL_DISPLAY:
				AddDial(nMSupdate, 0f, out fBottom, 1f, restoreIg);
				break;
			case MeterType.CUSTOM_METER_BAR:
				AddCustomBar(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.SIGNAL_MAX_BIN:
				AddSMeterBarMaxBin(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.OTHER_BUTTONS:
				AddOtherButtons(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.WAVE_RECORD:
				AddWaveRecord(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.VOICE_RECORD_PLAY_BUTTONS:
				AddVoiceRecordPlay(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			case MeterType.ACG_MAX_MAG:
				AddADCMaxMag(nMSupdate, 0f, out fBottom, restoreIg);
				break;
			}
			if (restoreIg == null)
			{
				initConsoleData(this);
			}
			switch (meter)
			{
			case MeterType.EQ:
				OnEQChanged(TXEQEnabled, TXEQEnabled);
				break;
			case MeterType.LEVELER:
			case MeterType.LEVELER_GAIN:
				OnLevelerChanged(LevelerEnabled, LevelerEnabled);
				break;
			case MeterType.CFC:
			case MeterType.CFC_GAIN:
				OnCFCChanged(CFCEnabled, CFCEnabled);
				break;
			case MeterType.COMP:
				OnCompandChanged(CompandEnabled, CompandEnabled);
				break;
			case MeterType.ALC:
			case MeterType.ALC_GAIN:
			case MeterType.ALC_GROUP:
				break;
			}
		}

