		private clsFadeCover getFadeCover(string sId, bool ignore_empty_check = false)
		{
			System.Drawing.RectangleF bounds = getBounds(sId);
			if (!ignore_empty_check && bounds.IsEmpty)
			{
				return null;
			}
			return new clsFadeCover
			{
				TopLeft = new PointF(bounds.X, bounds.Y),
				Size = new SizeF(bounds.Width, bounds.Height),
				ParentID = sId
			};
		}

		private string addSMeterBar(int nMSupdate, Reading reading, float fTop, out float fBottom, clsItemGroup restoreIg = null)
		{
			clsItemGroup clsItemGroup2 = new clsItemGroup();
			if (restoreIg != null)
			{
				clsItemGroup2.ID = restoreIg.ID;
			}
			clsItemGroup2.ParentID = ID;
			clsBarItem clsBarItem2 = new clsBarItem();
			clsBarItem2.ParentID = clsItemGroup2.ID;
			clsBarItem2.Primary = true;
			clsBarItem2.TopLeft = new PointF(_fPadX, fTop + _fPadY);
			clsBarItem2.Size = new SizeF(1f - _fPadX * 2f, _fHeight);
			clsBarItem2.ReadingSource = reading;
			clsBarItem2.MMIOVariableIndex = 0;
			clsBarItem2.AttackRatio = 0.8f;
			clsBarItem2.DecayRatio = 0.2f;
			clsBarItem2.UpdateInterval = nMSupdate;
			clsBarItem2.HistoryDuration = 4000;
			clsBarItem2.ShowHistory = true;
			clsBarItem2.ShowValue = true;
			clsBarItem2.Colour = System.Drawing.Color.CadetBlue;
			clsBarItem2.ShowMarker = true;
			clsBarItem2.PeakHoldMarkerColour = System.Drawing.Color.Red;
			clsBarItem2.HistoryColour = System.Drawing.Color.FromArgb(128, System.Drawing.Color.Red);
			clsBarItem2.Style = clsBarItem.BarStyle.Line;
			clsBarItem2.ScaleCalibration.Add(-133f, new PointF(0f, 0f));
			clsBarItem2.ScaleCalibration.Add(-73f, new PointF(0.5f, 0f));
			clsBarItem2.ScaleCalibration.Add(-13f, new PointF(0.99f, 0f));
			clsBarItem2.FontColour = System.Drawing.Color.Yellow;
			clsBarItem2.Value = clsBarItem2.ScaleCalibration.OrderBy((KeyValuePair<float, PointF> p) => p.Key).First().Key;
			if (IsAboveS9Frequency(_rx))
			{
				clsBarItem2.Value -= 20f;
			}
			clsBarItem2.ZOrder = 2;
			clsBarItem2.HighPoint = clsBarItem2.ScaleCalibration.OrderBy((KeyValuePair<float, PointF> p) => p.Key).ElementAt(1).Value;
			addMeterItem(clsBarItem2);
			clsScaleItem clsScaleItem2 = new clsScaleItem();
			clsScaleItem2.ParentID = clsItemGroup2.ID;
			clsScaleItem2.TopLeft = clsBarItem2.TopLeft;
			clsScaleItem2.Size = clsBarItem2.Size;
			clsScaleItem2.ReadingSource = clsBarItem2.ReadingSource;
			clsScaleItem2.ZOrder = 3;
			clsScaleItem2.ShowType = true;
			addMeterItem(clsScaleItem2);
			clsSolidColour clsSolidColour2 = new clsSolidColour();
			clsSolidColour2.ParentID = clsItemGroup2.ID;
			clsSolidColour2.TopLeft = new PointF(clsBarItem2.TopLeft.X, clsBarItem2.TopLeft.Y - _fHeight * 0.75f);
			clsSolidColour2.Size = new SizeF(clsBarItem2.Size.Width, _fHeight + _fHeight * 0.75f);
			clsSolidColour2.Colour = System.Drawing.Color.FromArgb(32, 32, 32);
			clsSolidColour2.ZOrder = 1;
			addMeterItem(clsSolidColour2);
			clsClickBox clsClickBox2 = new clsClickBox();
			clsClickBox2.ParentID = clsItemGroup2.ID;
			clsClickBox2.TopLeft = clsSolidColour2.TopLeft;
			clsClickBox2.Size = clsSolidColour2.Size;
			clsClickBox2.ChangesGroup = false;
			clsClickBox2.PerformsIncDec = true;
			clsClickBox2.RelatedMeterItem = clsBarItem2;
			addMeterItem(clsClickBox2);
			fBottom = clsBarItem2.TopLeft.Y + clsBarItem2.Size.Height;
			clsItemGroup2.TopLeft = clsBarItem2.TopLeft;
			clsItemGroup2.Size = new SizeF(clsBarItem2.Size.Width, fBottom);
			switch (reading)
			{
			case Reading.SIGNAL_STRENGTH:
				clsItemGroup2.MeterType = MeterType.SIGNAL_STRENGTH;
				break;
			case Reading.AVG_SIGNAL_STRENGTH:
				clsItemGroup2.MeterType = MeterType.AVG_SIGNAL_STRENGTH;
				break;
			case Reading.SIGNAL_MAX_BIN:
				clsItemGroup2.MeterType = MeterType.SIGNAL_MAX_BIN;
				break;
			}
			clsItemGroup2.Order = restoreIg?.Order ?? numberOfMeterGroups();
			clsFadeCover fadeCover = getFadeCover(clsItemGroup2.ID);
			if (fadeCover != null)
			{
				addMeterItem(fadeCover);
			}
			addMeterItem(clsItemGroup2);
			return clsBarItem2.ID;
		}

