		public BandGroups GetBandGroupFromBand(Band b)
		{
			switch (b)
			{
			case Band.B160M:
			case Band.B80M:
			case Band.B60M:
			case Band.B40M:
			case Band.B30M:
			case Band.B20M:
			case Band.B17M:
			case Band.B15M:
			case Band.B12M:
			case Band.B10M:
			case Band.B6M:
			case Band.B2M:
				return BandGroups.HF;
			case Band.WWV:
				return BandGroups.HF;
			case Band.BLMF:
			case Band.B120M:
			case Band.B90M:
			case Band.B61M:
			case Band.B49M:
			case Band.B41M:
			case Band.B31M:
			case Band.B25M:
			case Band.B22M:
			case Band.B19M:
			case Band.B16M:
			case Band.B14M:
			case Band.B13M:
			case Band.B11M:
				return BandGroups.GEN;
			case Band.VHF0:
			case Band.VHF1:
			case Band.VHF2:
			case Band.VHF3:
			case Band.VHF4:
			case Band.VHF5:
			case Band.VHF6:
			case Band.VHF7:
			case Band.VHF8:
			case Band.VHF9:
			case Band.VHF10:
			case Band.VHF11:
			case Band.VHF12:
			case Band.VHF13:
				return BandGroups.VHF;
			default:
				return BandGroups.GEN;
			}
		}

		public void SetBandPanel(Console c, int rx, bool gen, bool hf, bool vhf)
		{
			if (c == null || rx > 1)
			{
				return;
			}
			if (gen)
			{
				hf = false;
				vhf = false;
			}
			else if (hf)
			{
				gen = false;
				vhf = false;
			}
			else if (vhf)
			{
				gen = false;
				hf = false;
			}
			_console.BeginInvoke((MethodInvoker)delegate
			{
				if (gen && !c.BandGENSelected)
				{
					c.BandGENSelected = true;
				}
				else if (hf && !c.BandHFSelected)
				{
					c.BandHFSelected = true;
				}
				else if (vhf && !c.BandVHFSelected)
				{
					c.BandVHFSelected = true;
				}
			});
		}

		public (string, string) GetWebImageIDsFrom4Char(string fourchar)
		{
			string item = null;
			string item2 = null;
			lock (_meterItemsLock)
			{
				foreach (KeyValuePair<string, clsMeterItem> meterItem in _meterItems)
				{
					if (meterItem.Value is clsWebImage clsWebImage2 && !string.IsNullOrEmpty(clsWebImage2.FourChar) && clsWebImage2.FourChar == fourchar)
					{
						item = ID;
						item2 = clsWebImage2.ParentID;
					}
				}
			}
			return (item, item2);
		}

		public bool IsWebImageBackgroundShown()
		{
			bool flag = false;
			lock (_meterItemsLock)
			{
				foreach (KeyValuePair<string, clsMeterItem> meterItem in _meterItems)
				{
					if (meterItem.Value is clsWebImage clsWebImage2)
					{
						flag |= clsWebImage2.ShowBackground;
						if (flag)
						{
							break;
						}
					}
				}
			}
			return flag;
		}

