		public void ZeroOut(bool bRxReadings, bool bTxReadings)
		{
			lock (_meterItemsLock)
			{
				foreach (KeyValuePair<string, clsMeterItem> meterItem in _meterItems)
				{
					clsMeterItem value = meterItem.Value;
					value.ClearHistory();
					Dictionary<Reading, float> values = new Dictionary<Reading, float>();
					if (!value.ZeroOut(ref values, _rx))
					{
						continue;
					}
					foreach (KeyValuePair<Reading, float> item in values)
					{
						if (bRxReadings | bTxReadings)
						{
							setReadingForced(RX, item.Key, item.Value);
						}
					}
				}
			}
		}

		public void RebuildLedReadings()
		{
			lock (_meterItemsLock)
			{
