		public bool TryParse(string str)
		{
			bool flag = false;
			int result = 0;
			int result2 = 0;
			float result3 = 0f;
			float result4 = 0f;
			float result5 = 0f;
			float result6 = 0f;
			float result7 = 0f;
			if (str != "")
			{
				string[] array = str.Split('|');
				if (array.Length == 9)
				{
					flag = array[0] != "";
					if (flag)
					{
						ID = array[0];
					}
					if (flag)
					{
						_name = array[1];
					}
					if (flag)
					{
						int.TryParse(array[2], out result);
					}
					if (flag)
					{
						RX = result;
					}
					if (flag)
					{
						flag = float.TryParse(array[3], out result3);
					}
					if (flag)
					{
						flag = float.TryParse(array[4], out result4);
					}
					if (flag)
					{
						_XRatio = result3;
						_YRatio = result4;
					}
					if (flag)
					{
						int.TryParse(array[5], out result2);
					}
					if (flag)
					{
						_displayGroup = result2;
					}
					if (flag)
					{
						flag = float.TryParse(array[6], out result5);
					}
					if (flag)
					{
						flag = float.TryParse(array[7], out result6);
					}
					if (flag)
					{
						flag = float.TryParse(array[8], out result7);
					}
					if (flag)
					{
						_fPadX = 0.004f;
						_fPadY = 0.041f;
						_fHeight = result7;
					}
				}
			}
			return flag;
		}

		private int numberOfMeterGroups()
		{
			lock (_meterItemsLock)
			{
				Dictionary<string, clsMeterItem> meterItems = _meterItems;
				if (meterItems == null)
				{
					return 0;
				}
				int num = 0;
				foreach (KeyValuePair<string, clsMeterItem> item in meterItems)
				{
					if (item.Value.ItemType == clsMeterItem.MeterItemType.ITEM_GROUP)
					{
						num++;
					}
				}
				return num;
			}
		}

		private void removeMeterItem(string sId, bool bRebuild = false)
		{
			lock (_meterItemsLock)
			{
				Dictionary<string, clsMeterItem> dictionary = itemsFromID(sId);
				if (dictionary == null || dictionary.Count == 0)
				{
					return;
				}
				List<string> list = new List<string>();
				foreach (KeyValuePair<string, clsMeterItem> item in dictionary)
				{
					list.Add(item.Value.ID);
				}
				dictionary.Clear();
				MeterScriptEngine.BeginBatch();
				foreach (string item2 in list)
				{
					_meterItems[item2].Removing();
					_meterItems.Remove(item2);
				}
				MeterScriptEngine.EndBatch();
				list.Clear();
				if (bRebuild)
				{
					Rebuild();
				}
			}
		}

		public void RemoveMeterType(MeterType mt, int order, bool bRebuild = false)
		{
			lock (_meterItemsLock)
			{
				if (_meterItems == null)
				{
					return;
				}
				if (mt == MeterType.ANANMM)
				{
					RemoveDisplayGroup("ALL");
					RemoveDisplayGroup("PWR/SWR");
					RemoveDisplayGroup("Comp");
					RemoveDisplayGroup("ALC");
					RemoveDisplayGroup("Volts/Amps");
				}
				foreach (KeyValuePair<string, clsMeterItem> item in _meterItems.Where((KeyValuePair<string, clsMeterItem> o) => o.Value.ItemType == clsMeterItem.MeterItemType.ITEM_GROUP).ToDictionary((KeyValuePair<string, clsMeterItem> x) => x.Key, (KeyValuePair<string, clsMeterItem> x) => x.Value))
				{
					int num = -1;
					if (item.Value is clsItemGroup clsItemGroup2 && clsItemGroup2.MeterType == mt && clsItemGroup2.Order == order)
					{
						num = clsItemGroup2.Order;
						removeMeterItem(clsItemGroup2.ID);
						order = -9999;
					}
					if (num < 0)
					{
						continue;
					}
					foreach (KeyValuePair<string, clsMeterItem> item2 in _meterItems.Where((KeyValuePair<string, clsMeterItem> o) => o.Value.ItemType == clsMeterItem.MeterItemType.ITEM_GROUP).ToDictionary((KeyValuePair<string, clsMeterItem> x) => x.Key, (KeyValuePair<string, clsMeterItem> x) => x.Value))
					{
						if (item2.Value is clsItemGroup clsItemGroup3 && clsItemGroup3.Order > num)
						{
							clsItemGroup3.Order--;
						}
					}
				}
				if (bRebuild)
				{
					Rebuild();
				}
			}
		}

		public clsMeterItem GetMeterItem(MeterType mt, int order, clsMeterItem.MeterItemType mit)
		{
			clsMeterItem result = null;
			lock (_meterItemsLock)
			{
				if (_meterItems == null)
				{
					return null;
				}
				foreach (KeyValuePair<string, clsMeterItem> item in _meterItems.Where((KeyValuePair<string, clsMeterItem> o) => o.Value.ItemType == clsMeterItem.MeterItemType.ITEM_GROUP).ToDictionary((KeyValuePair<string, clsMeterItem> x) => x.Key, (KeyValuePair<string, clsMeterItem> x) => x.Value))
				{
					if (!(item.Value is clsItemGroup clsItemGroup2) || clsItemGroup2.MeterType != mt || clsItemGroup2.Order != order)
					{
						continue;
					}
					Dictionary<string, clsMeterItem> dictionary = itemsFromID(clsItemGroup2.ID, bIncludeTheParent: false, bOnlyChildren: true);
					if (dictionary == null)
					{
						return null;
					}
					foreach (clsMeterItem value in dictionary.Values)
					{
						if (value.ItemType == mit)
						{
							result = value;
							break;
						}
					}
					break;
				}
			}
			return result;
		}

