		public void Find4Chars(ref Dictionary<string, string> fourchars, clsIGSettings igs)
		{
			lock (_meterItemsLock)
			{
				if (_meterItems == null)
				{
					return;
				}
				foreach (KeyValuePair<string, clsMeterItem> item in _meterItems.Where((KeyValuePair<string, clsMeterItem> o) => o.Value.ItemType == clsMeterItem.MeterItemType.ITEM_GROUP).ToDictionary((KeyValuePair<string, clsMeterItem> x) => x.Key, (KeyValuePair<string, clsMeterItem> x) => x.Value))
				{
					clsItemGroup clsItemGroup2 = item.Value as clsItemGroup;
					if (clsItemGroup2 != null && clsItemGroup2.MeterType == MeterType.LED)
					{
						foreach (KeyValuePair<string, clsMeterItem> item2 in from o in itemsFromID(clsItemGroup2.ID, bIncludeTheParent: false)
							where o.Value.ItemType == clsMeterItem.MeterItemType.LED
							select o)
						{
							if (item2.Value is clsLed clsLed2)
							{
								fourchars[clsLed2.ID] = clsLed2.FourChar;
							}
						}
					}
					else if (clsItemGroup2 != null && clsItemGroup2.MeterType == MeterType.TEXT_OVERLAY)
					{
						foreach (KeyValuePair<string, clsMeterItem> item3 in from o in itemsFromID(clsItemGroup2.ID, bIncludeTheParent: false)
							where o.Value.ItemType == clsMeterItem.MeterItemType.TEXT_OVERLAY
							select o)
						{
							if (item3.Value is clsTextOverlay)
							{
								string setting = igs.GetSetting("textoverlay_rx_4char", validate: false, "", "", "");
								fourchars[setting] = "-";
								setting = igs.GetSetting("textoverlay_tx_4char", validate: false, "", "", "");
								fourchars[setting] = "-";
							}
						}
					}
					else if (clsItemGroup2 != null && clsItemGroup2.MeterType == MeterType.WEB_IMAGE)
					{
						foreach (KeyValuePair<string, clsMeterItem> item4 in from o in itemsFromID(clsItemGroup2.ID, bIncludeTheParent: false)
							where o.Value.ItemType == clsMeterItem.MeterItemType.WEB_IMAGE
							select o)
						{
							if (item4.Value is clsWebImage clsWebImage2)
							{
								string setting2 = igs.GetSetting("webimage_background_4char", validate: false, "", "", "");
								fourchars[setting2] = "-";
								fourchars[clsWebImage2.FourChar] = clsWebImage2.ID;
							}
						}
					}
					else
					{
						if (clsItemGroup2 == null || clsItemGroup2.MeterType != MeterType.VOICE_RECORD_PLAY_BUTTONS)
						{
							continue;
						}
						foreach (KeyValuePair<string, clsMeterItem> item5 in from o in itemsFromID(clsItemGroup2.ID, bIncludeTheParent: false)
							where o.Value.ItemType == clsMeterItem.MeterItemType.VOICE_RECORD_PLAY_BUTTONS
							select o)
						{
							if (item5.Value is clsVoiceRecordPlay clsVoiceRecordPlay2)
							{
								fourchars[clsVoiceRecordPlay2.ID] = clsVoiceRecordPlay2.FourChar;
							}
						}
					}
				}
			}
		}

		public void ApplySettingsForMeterGroup(MeterType mt, clsIGSettings igs, List<string> webimages = null, int order = -1, bool from_setup_form = false, bool ignore_led_condition = false)
		{
			lock (_meterItemsLock)
			{
				if (_meterItems == null)
				{
					return;
				}
				bool flag = false;
				foreach (KeyValuePair<string, clsMeterItem> item in _meterItems.Where((KeyValuePair<string, clsMeterItem> o) => o.Value.ItemType == clsMeterItem.MeterItemType.ITEM_GROUP).ToDictionary((KeyValuePair<string, clsMeterItem> x) => x.Key, (KeyValuePair<string, clsMeterItem> x) => x.Value))
				{
					if (!(item.Value is clsItemGroup clsItemGroup2) || clsItemGroup2.MeterType != mt || (order != -1 && clsItemGroup2.Order != order))
					{
						continue;
					}
					switch (mt)
					{
					case MeterType.HISTORY:
					{
						flag = true;
						float num4 = 0f;
						Dictionary<string, clsMeterItem> source7 = itemsFromID(clsItemGroup2.ID, bIncludeTheParent: false);
						foreach (KeyValuePair<string, clsMeterItem> item2 in source7.Where((KeyValuePair<string, clsMeterItem> o) => o.Value.ItemType == clsMeterItem.MeterItemType.HISTORY))
						{
							if (item2.Value is clsHistoryItem clsHistoryItem2)
							{
								clsHistoryItem2.VerticalRatio = igs.GetSetting("history_vertical_ratio", validate: true, 0.13f, 1f, 0.5f);
								clsHistoryItem2.BackColour = igs.GetSetting("history_background_colour", validate: false, System.Drawing.Color.Empty, System.Drawing.Color.Empty, System.Drawing.Color.Black);
								clsHistoryItem2.UpdateInterval = (int)igs.GetSetting("history_update", validate: true, 50f, 10000f, 0.5f);
								clsHistoryItem2.KeepFor = (int)igs.GetSetting("history_keep_for", validate: true, 1f, 86400f, 20f);
								clsHistoryItem2.Reading0 = igs.GetSetting("history_reading_0", validate: false, Reading.NONE, Reading.NONE, Reading.SIGNAL_STRENGTH);
								clsHistoryItem2.Reading1 = igs.GetSetting("history_reading_1", validate: false, Reading.NONE, Reading.NONE, Reading.SIGNAL_STRENGTH);
								clsHistoryItem2.AutoScale0 = igs.GetSetting("history_auto_scale_0", validate: false, min: false, max: false, defaultValue: true);
								clsHistoryItem2.Min0Manual = igs.GetSetting("history_min_0", validate: true, -40000f, 40000f, -150f);
								clsHistoryItem2.Max0Manual = igs.GetSetting("history_max_0", validate: true, -40000f, 40000f, 0f);
								clsHistoryItem2.ShowScale1 = igs.GetSetting("history_show_scale_1", validate: false, min: false, max: false, defaultValue: true);
								clsHistoryItem2.AutoScale1 = igs.GetSetting("history_auto_scale_1", validate: false, min: false, max: false, defaultValue: true);
								clsHistoryItem2.Min1Manual = igs.GetSetting("history_min_1", validate: true, -40000f, 40000f, -150f);
								clsHistoryItem2.Max1Manual = igs.GetSetting("history_max_1", validate: true, -40000f, 40000f, 0f);
								clsHistoryItem2.Axis0MMIOGuid = igs.GetMMIOGuid(0);
								clsHistoryItem2.Axis0MMIOVariable = igs.GetMMIOVariable(0);
								clsHistoryItem2.Axis1MMIOGuid = igs.GetMMIOGuid(1);
								clsHistoryItem2.Axis1MMIOVariable = igs.GetMMIOVariable(1);
								clsHistoryItem2.Axis0Colour = igs.GetSetting("history_colour_0", validate: false, System.Drawing.Color.Empty, System.Drawing.Color.Empty, System.Drawing.Color.Red);
								clsHistoryItem2.Axis1Colour = igs.GetSetting("history_colour_1", validate: false, System.Drawing.Color.Empty, System.Drawing.Color.Empty, System.Drawing.Color.Yellow);
								clsHistoryItem2.LinesColour = igs.GetSetting("history_colour_lines", validate: false, System.Drawing.Color.Empty, System.Drawing.Color.Empty, System.Drawing.Color.White);
								clsHistoryItem2.TimeColour = igs.GetSetting("history_colour_time", validate: false, System.Drawing.Color.Empty, System.Drawing.Color.Empty, System.Drawing.Color.Gray);
								clsHistoryItem2.FadeOnRx = igs.FadeOnRx;
								clsHistoryItem2.FadeOnTx = igs.FadeOnTx;
								clsHistoryItem2.TopLeft = new PointF(clsItemGroup2.TopLeft.X, _fPadY - _fHeight * 0.75f);
								clsHistoryItem2.Size = new SizeF(clsItemGroup2.Size.Width, clsHistoryItem2.VerticalRatio);
								num4 += clsHistoryItem2.Size.Height;
							}
						}
						clsItemGroup2.Size = new SizeF(clsItemGroup2.Size.Width, num4 + (_fPadY - _fHeight * 0.75f));
						if (getBounds(clsItemGroup2.ID).IsEmpty)
						{
							break;
						}
						foreach (KeyValuePair<string, clsMeterItem> item3 in source7.Where((KeyValuePair<string, clsMeterItem> o) => o.Value.ItemType == clsMeterItem.MeterItemType.FADE_COVER))
						{
							if (item3.Value is clsFadeCover clsFadeCover7)
