								clsWaveRecord2.BackColour = igs.GetSetting("waverecord_back_colour", validate: false, System.Drawing.Color.Empty, System.Drawing.Color.Empty, clsWaveRecord2.BackColour);
								clsWaveRecord2.RowColour = igs.GetSetting("waverecord_row_colour", validate: false, System.Drawing.Color.Empty, System.Drawing.Color.Empty, clsWaveRecord2.RowColour);
								clsWaveRecord2.RowBorderColour = igs.GetSetting("waverecord_row_border_colour", validate: false, System.Drawing.Color.Empty, System.Drawing.Color.Empty, igs.GetSetting("waverecord_border_colour", validate: false, System.Drawing.Color.Empty, System.Drawing.Color.Empty, clsWaveRecord2.RowBorderColour));
								clsWaveRecord2.TextColour = igs.GetSetting("waverecord_text_colour", validate: false, System.Drawing.Color.Empty, System.Drawing.Color.Empty, clsWaveRecord2.TextColour);
								clsWaveRecord2.ButtonFillColour = igs.GetSetting("waverecord_button_fill_colour", validate: false, System.Drawing.Color.Empty, System.Drawing.Color.Empty, clsWaveRecord2.ButtonFillColour);
								clsWaveRecord2.ButtonBorderColour = igs.GetSetting("waverecord_button_border_colour", validate: false, System.Drawing.Color.Empty, System.Drawing.Color.Empty, clsWaveRecord2.ButtonBorderColour);
								clsWaveRecord2.ButtonHoverColour = igs.GetSetting("waverecord_button_hover_colour", validate: false, System.Drawing.Color.Empty, System.Drawing.Color.Empty, clsWaveRecord2.ButtonHoverColour);
								clsWaveRecord2.PlayIconColour = igs.GetSetting("waverecord_play_colour", validate: false, System.Drawing.Color.Empty, System.Drawing.Color.Empty, clsWaveRecord2.PlayIconColour);
								clsWaveRecord2.StopIconColour = igs.GetSetting("waverecord_stop_colour", validate: false, System.Drawing.Color.Empty, System.Drawing.Color.Empty, clsWaveRecord2.StopIconColour);
								clsWaveRecord2.DeleteIconColour = igs.GetSetting("waverecord_delete_colour", validate: false, System.Drawing.Color.Empty, System.Drawing.Color.Empty, clsWaveRecord2.DeleteIconColour);
								clsWaveRecord2.ScrollbarTrackColour = igs.GetSetting("waverecord_scrolltrack_colour", validate: false, System.Drawing.Color.Empty, System.Drawing.Color.Empty, clsWaveRecord2.ScrollbarTrackColour);
								clsWaveRecord2.ScrollbarThumbColour = igs.GetSetting("waverecord_scrollthumb_colour", validate: false, System.Drawing.Color.Empty, System.Drawing.Color.Empty, clsWaveRecord2.ScrollbarThumbColour);
								clsWaveRecord2.ScrollbarThumbHoverColour = igs.GetSetting("waverecord_scrollthumb_hover_colour", validate: false, System.Drawing.Color.Empty, System.Drawing.Color.Empty, clsWaveRecord2.ScrollbarThumbHoverColour);
