							{
								clsBarItem2.UpdateInterval = igs.UpdateInterval;
								clsBarItem2.AttackRatio = igs.AttackRatio;
								clsBarItem2.DecayRatio = igs.DecayRatio;
								clsBarItem2.FadeOnRx = igs.FadeOnRx;
								clsBarItem2.FadeOnTx = igs.FadeOnTx;
								clsBarItem2.MarkerColour = igs.SubMarkerColour;
								clsBarItem2.ShowMarker = igs.ShowSubMarker;
							}
							if (clsBarItem2.ReadingSource == Reading.PWR || clsBarItem2.ReadingSource == Reading.REVERSE_PWR)
							{
								clsBarItem2.MaxPower = igs.MaxPower;
							}
						}
						foreach (KeyValuePair<string, clsMeterItem> item44 in source.Where((KeyValuePair<string, clsMeterItem> o) => o.Value.ItemType == clsMeterItem.MeterItemType.SOLID_COLOUR))
						{
							if (item44.Value is clsSolidColour clsSolidColour2)
							{
