								clsSolidColour2.FadeOnTx = igs.FadeOnTx;
								clsSolidColour2.Colour = igs.Colour;
							}
						}
						foreach (KeyValuePair<string, clsMeterItem> item45 in source.Where((KeyValuePair<string, clsMeterItem> o) => o.Value.ItemType == clsMeterItem.MeterItemType.H_SCALE))
						{
