							{
								clsScaleItem2.FadeOnRx = igs.FadeOnRx;
								clsScaleItem2.FadeOnTx = igs.FadeOnTx;
								clsScaleItem2.LowColour = igs.LowColor;
								clsScaleItem2.HighColour = igs.HighColor;
								clsScaleItem2.ShowType = igs.ShowType;
								clsScaleItem2.FontColourType = igs.TitleColor;
								clsScaleItem2.FontColourLow = igs.LowColor;
								clsScaleItem2.FontColourHigh = igs.HighColor;
								if (clsScaleItem2.ReadingSource == Reading.PWR || clsScaleItem2.ReadingSource == Reading.REVERSE_PWR)
								{
									clsScaleItem2.MaxPower = igs.MaxPower;
								}
								if (mt == MeterType.CUSTOM_METER_BAR)
								{
									clsScaleItem2.CustomMin = igs.GetSetting("meter_custom_min", validate: true, -5000f, 5000f, 0f);
									clsScaleItem2.CustomMax = igs.GetSetting("meter_custom_max", validate: true, -5000f, 5000f, 10f);
									clsScaleItem2.CustomHigh = igs.GetSetting("meter_custom_high", validate: true, -5000f, 5000f, 7.5f);
									clsScaleItem2.CustomUnits = igs.GetSetting("meter_custom_units", validate: false, "", "", "?");
									clsScaleItem2.CustomTitle = igs.GetSetting("meter_custom_title", validate: false, "", "", "Title");
								}
							}
						}
						foreach (KeyValuePair<string, clsMeterItem> item46 in source.Where((KeyValuePair<string, clsMeterItem> o) => o.Value.ItemType == clsMeterItem.MeterItemType.FADE_COVER))
						{
