							{
								clsFadeCover2.FadeOnRx = igs.FadeOnRx;
								clsFadeCover2.FadeOnTx = igs.FadeOnTx;
							}
						}
						break;
					}
					}
					if (flag)
					{
						Rebuild();
					}
					else
					{
						UpdateIntervals();
					}
					break;
				}
			}
		}

