		public List<int> GetOrderForMeterType(MeterType mt)
		{
			lock (_meterItemsLock)
			{
				Dictionary<string, clsMeterItem> meterItems = _meterItems;
				if (meterItems == null)
				{
					return new List<int>();
				}
				List<int> list = new List<int>(meterItems.Count);
				foreach (clsMeterItem value in meterItems.Values)
				{
					if (value is clsItemGroup clsItemGroup2 && clsItemGroup2.MeterType == mt)
					{
						list.Add(clsItemGroup2.Order);
					}
				}
				return list;
			}
		}

		public void SetOrderForMeterType(MeterType mt, int nOrder, bool bRebuild, bool bUp, int order = -1)
		{
			lock (_meterItemsLock)
			{
				if (_meterItems == null)
				{
					return;
				}
				Dictionary<string, clsMeterItem> meterItems = _meterItems;
				if (nOrder < 0)
				{
					nOrder = 0;
				}
				int num = 0;
				foreach (KeyValuePair<string, clsMeterItem> item in meterItems)
				{
					if (item.Value.ItemType == clsMeterItem.MeterItemType.ITEM_GROUP)
					{
						num++;
					}
				}
				int num2 = ((num > 0) ? (num - 1) : 0);
				if (nOrder > num2)
				{
					nOrder = num2;
				}
				bool flag = false;
				foreach (KeyValuePair<string, clsMeterItem> item2 in meterItems)
				{
					if (!(item2.Value is clsItemGroup clsItemGroup2))
					{
						continue;
					}
					if (!flag && clsItemGroup2.MeterType == mt && (order == -1 || clsItemGroup2.Order == order))
					{
						clsItemGroup2.Order = nOrder;
						flag = true;
					}
					else if (clsItemGroup2.Order == nOrder)
					{
						if (bUp)
						{
							clsItemGroup2.Order++;
						}
						else
						{
							clsItemGroup2.Order--;
						}
					}
				}
			}
			if (bRebuild)
			{
				Rebuild();
			}
		}

