					{
						result = true;
						break;
					}
				}
			}
			return result;
		}

		internal clsMeterItem itemFromID(string sId)
		{
			lock (_meterItemsLock)
			{
				if (_meterItems == null)
				{
					return null;
				}
				if (!_meterItems.ContainsKey(sId))
				{
					return null;
				}
				return _meterItems[sId];
			}
		}

		internal System.Drawing.RectangleF getBounds(string sId)
		{
			lock (_meterItemsLock)
			{
				if (_meterItems == null)
				{
					return System.Drawing.RectangleF.Empty;
				}
				Dictionary<string, clsMeterItem> dictionary = itemsFromID(sId, bIncludeTheParent: false, bOnlyChildren: true);
				if (dictionary == null)
				{
					return System.Drawing.RectangleF.Empty;
				}
				float num = float.MaxValue;
				float num2 = float.MaxValue;
				float num3 = float.MinValue;
				float num4 = float.MinValue;
				foreach (KeyValuePair<string, clsMeterItem> item in dictionary)
				{
					clsMeterItem value = item.Value;
					if (value.TopLeft.X < num)
					{
						num = value.TopLeft.X;
					}
					if (value.TopLeft.Y < num2)
					{
						num2 = value.TopLeft.Y;
					}
					if (value.TopLeft.X + value.Size.Width > num3)
					{
						num3 = value.TopLeft.X + value.Size.Width;
					}
					if (value.TopLeft.Y + value.Size.Height > num4)
					{
						num4 = value.TopLeft.Y + value.Size.Height;
					}
				}
				return new System.Drawing.RectangleF(num, num2, num3 - num, num4 - num2);
			}
		}

