		internal Dictionary<string, clsMeterItem> itemsFromID(string sId, bool bIncludeTheParent = true, bool bOnlyChildren = false)
		{
			lock (_meterItemsLock)
			{
				if (_meterItems == null)
				{
					return null;
				}
				if (!bOnlyChildren && !_meterItems.ContainsKey(sId))
				{
					return null;
				}
				Dictionary<string, clsMeterItem> dictionary = new Dictionary<string, clsMeterItem>();
				foreach (KeyValuePair<string, clsMeterItem> item in _meterItems.Where((KeyValuePair<string, clsMeterItem> o) => o.Value.ParentID == sId || ((!bOnlyChildren & bIncludeTheParent) && o.Value.ID == sId)))
				{
					dictionary.Add(item.Key, item.Value);
				}
				return dictionary;
			}
		}

