		public void UpdateItems()
		{
			bool isInBatch = MeterScriptEngine.IsInBatch;
			lock (_meterItemsLock)
			{
				foreach (KeyValuePair<string, clsMeterItem> item in _meterItems.Where((KeyValuePair<string, clsMeterItem> o) => o.Value.ItemType == clsMeterItem.MeterItemType.TEXT_OVERLAY || o.Value.ItemType == clsMeterItem.MeterItemType.LED))
				{
					switch (item.Value.ItemType)
					{
					case clsMeterItem.MeterItemType.TEXT_OVERLAY:
						if (item.Value is clsTextOverlay clsTextOverlay2)
						{
							clsTextOverlay2.Text1 = clsTextOverlay2.Text1;
							clsTextOverlay2.Text2 = clsTextOverlay2.Text2;
						}
						break;
					case clsMeterItem.MeterItemType.LED:
						if (!isInBatch && item.Value is clsLed clsLed2)
						{
							clsLed2.Condition = clsLed2.Condition;
						}
						break;
					}
				}
				foreach (KeyValuePair<string, clsMeterItem> item2 in _meterItems.Where((KeyValuePair<string, clsMeterItem> o) => o.Value.ItemType == clsMeterItem.MeterItemType.BAND_BUTTONS || o.Value.ItemType == clsMeterItem.MeterItemType.FILTER_BUTTONS || o.Value.ItemType == clsMeterItem.MeterItemType.MODE_BUTTONS || o.Value.ItemType == clsMeterItem.MeterItemType.OTHER_BUTTONS || o.Value.ItemType == clsMeterItem.MeterItemType.FILTER_DISPLAY || o.Value.ItemType == clsMeterItem.MeterItemType.WAVE_RECORD || o.Value.ItemType == clsMeterItem.MeterItemType.VOICE_RECORD_PLAY_BUTTONS))
				{
					item2.Value.Initialise();
				}
			}
		}

		internal Dictionary<string, clsItemGroup> getMeterGroups()
		{
			lock (_meterItemsLock)
			{
				Dictionary<string, clsItemGroup> dictionary = new Dictionary<string, clsItemGroup>(_meterItems.Count);
				foreach (KeyValuePair<string, clsMeterItem> meterItem in _meterItems)
				{
					if (meterItem.Value.ItemType == clsMeterItem.MeterItemType.ITEM_GROUP)
					{
						clsItemGroup clsItemGroup2 = (clsItemGroup)meterItem.Value;
						dictionary.Add(clsItemGroup2.ID, clsItemGroup2);
					}
				}
				return dictionary;
			}
		}

		public void UpdateIntervals()
		{
			_quickestRXUpdate = QuickestUpdateInterval(mox: false, console_only_refresh: false);
			_quickestTXUpdate = QuickestUpdateInterval(mox: true, console_only_refresh: false);
		}

		public void Rebuild()
		{
			UpdateIntervals();
			setupSortedZOrder();
			lock (_meterItemsLock)
			{
				Dictionary<string, clsItemGroup> meterGroups = getMeterGroups();
				float num = 0f;
				foreach (KeyValuePair<string, clsItemGroup> item in meterGroups.OrderBy((KeyValuePair<string, clsItemGroup> o) => o.Value.Order))
				{
					clsItemGroup value = item.Value;
					if (value == null)
					{
						continue;
					}
					value.TopLeft = new PointF(value.TopLeft.X, num);
					foreach (KeyValuePair<string, clsMeterItem> item2 in itemsFromID(value.ID, bIncludeTheParent: false))
					{
						clsMeterItem value2 = item2.Value;
						value2.DisplayTopLeft = new PointF(value2.TopLeft.X, value2.TopLeft.Y + num);
					}
					num += value.Size.Height;
				}
			}
		}

		private void setupSortedZOrder()
		{
			lock (_meterItemsLock)
			{
				Dictionary<string, clsMeterItem> meterItems = _meterItems;
				List<clsMeterItem> list = new List<clsMeterItem>(meterItems.Count);
				foreach (KeyValuePair<string, clsMeterItem> item in meterItems)
				{
					list.Add(item.Value);
				}
				list.Sort((clsMeterItem a, clsMeterItem b) => a.ZOrder.CompareTo(b.ZOrder));
				_sortedMeterItemsForZOrder = list;
			}
		}

		internal void MouseUp(MouseEventArgs e, clsMeter m, clsClickBox cb)
		{
			if (cb.GotoGroup > 0)
			{
				m.DisplayGroup = cb.GotoGroup;
				return;
			}
			if (cb.ChangesGroup)
			{
				if (e.Button == MouseButtons.Left)
				{
					incrementDisplayGroup();
				}
				else if (e.Button == MouseButtons.Right)
				{
					decrementDisplayGroup();
				}
			}
			if (!cb.PerformsIncDec)
			{
				return;
			}
			if (e.Button == MouseButtons.Left)
			{
				lock (_meterItemsLock)
				{
					incrementMeterItem(cb);
					return;
				}
			}
			if (e.Button != MouseButtons.Right)
			{
				return;
			}
			lock (_meterItemsLock)
			{
				decrementMeterItem(cb);
			}
		}

		private void updateVfoABandText(object _)
		{
			lock (_timerLock_vfoA)
			{
				System.Threading.Timer timer = null;
				try
				{
					UpdateBandText(is_vfoA: true);
					_last_band_text_update_vfoA = DateTime.UtcNow;
					timer = _timer_band_text_vfoA;
					_timer_band_text_vfoA = null;
				}
				catch
				{
				}
				finally
				{
					timer?.Dispose();
				}
			}
		}

		private void updateVfoBBandText(object _)
		{
			lock (_timerLock_vfoB)
			{
				System.Threading.Timer timer = null;
				try
				{
					UpdateBandText(is_vfoA: false);
					_last_band_text_update_vfoB = DateTime.UtcNow;
					timer = _timer_band_text_vfoB;
					_timer_band_text_vfoB = null;
				}
				catch
				{
				}
				finally
				{
					timer?.Dispose();
				}
			}
		}

		public void UpdateBandText(bool is_vfoA)
		{
			if (_rx == 1)
			{
				if (is_vfoA)
				{
					DB.BandText(_vfoA, out _vfoA_band_text);
				}
				else
				{
					DB.BandText(_vfoB, out _vfoB_band_text);
				}
			}
			else if (!is_vfoA)
			{
				DB.BandText(_vfoB, out _vfoB_band_text);
			}
		}

		public void ContainerEnabled(string id, bool enabled)
		{
			lock (_meterItemsLock)
			{
				foreach (KeyValuePair<string, clsMeterItem> meterItem in _meterItems)
				{
					meterItem.Value.ContainerEnabled(id, enabled);
				}
			}
		}

		public void ContainerHiddenByMacro(string id, bool hidden)
		{
			lock (_meterItemsLock)
			{
				foreach (KeyValuePair<string, clsMeterItem> meterItem in _meterItems)
				{
					meterItem.Value.ContainerHiddenByMacro(id, hidden);
				}
			}
		}

		public int QuickestUpdateInterval(bool mox, bool console_only_refresh)
		{
			lock (_meterItemsLock)
			{
				int num = int.MaxValue;
				foreach (KeyValuePair<string, clsMeterItem> meterItem in _meterItems)
				{
					clsMeterItem value = meterItem.Value;
					if ((!mox || !value.OnlyWhenTX) && (mox || !value.OnlyWhenRX) && (value.OnlyWhenTX || value.OnlyWhenRX))
					{
						continue;
					}
					if (console_only_refresh)
					{
						bool flag = false;
						int readingSource = (int)value.ReadingSource;
						flag = (_mox ? (readingSource >= 8 && readingSource <= 35) : ((readingSource >= 0 && readingSource <= 7) || readingSource == 72));
						if (!flag)
						{
							flag = readingSource == 38 || readingSource == 39;
						}
						if (!flag)
						{
							clsMeterItem.MeterItemType itemType = value.ItemType;
							flag = itemType == clsMeterItem.MeterItemType.TEXT_OVERLAY || itemType == clsMeterItem.MeterItemType.LED || itemType == clsMeterItem.MeterItemType.HISTORY;
						}
						if (!flag)
						{
							continue;
						}
					}
					else
					{
						clsMeterItem.MeterItemType itemType2 = value.ItemType;
						if (itemType2 == clsMeterItem.MeterItemType.BASE || itemType2 == clsMeterItem.MeterItemType.CLICKBOX || itemType2 == clsMeterItem.MeterItemType.DATA_OUT || itemType2 == clsMeterItem.MeterItemType.FADE_COVER || itemType2 == clsMeterItem.MeterItemType.H_SCALE || itemType2 == clsMeterItem.MeterItemType.V_SCALE || itemType2 == clsMeterItem.MeterItemType.IMAGE || itemType2 == clsMeterItem.MeterItemType.ITEM_GROUP || itemType2 == clsMeterItem.MeterItemType.NEEDLE_SCALE_PWR || itemType2 == clsMeterItem.MeterItemType.SOLID_COLOUR || itemType2 == clsMeterItem.MeterItemType.TEXT)
						{
							continue;
						}
					}
					if (value.UpdateInterval < num)
					{
						num = value.UpdateInterval;
					}
				}
				return num;
			}
		}

		private void addUpdateReading(ref Dictionary<Reading, object> all_readings, Reading reading, object value)
		{
			if (all_readings.ContainsKey(reading))
			{
				all_readings[reading] = value;
			}
			else
			{
				all_readings.Add(reading, value);
			}
		}

		public void Update(ref List<Reading> readingsUsed)
		{
			lock (_meterItemsLock)
			{
				Dictionary<Reading, object> all_readings = new Dictionary<Reading, object>();
				List<clsMeterItem> list = new List<clsMeterItem>();
				foreach (KeyValuePair<string, clsMeterItem> meterItem in _meterItems)
				{
					clsMeterItem value = meterItem.Value;
					if (value.RequiresUpdate)
					{
						if (value.ItemType != clsMeterItem.MeterItemType.DATA_OUT)
						{
							value.Update(_rx, ref readingsUsed);
						}
						else if (value is clsDataOut clsDataOut2 && clsDataOut2.MMIOGuid != Guid.Empty)
						{
							list.Add(value);
						}
					}
				}
				if (list.Count <= 0)
				{
					return;
				}
				foreach (KeyValuePair<string, clsMeterItem> meterItem2 in _meterItems)
				{
					clsMeterItem value2 = meterItem2.Value;
					if (value2.ReadingSource != Reading.NONE && (value2.ItemType == clsMeterItem.MeterItemType.H_BAR || value2.ItemType == clsMeterItem.MeterItemType.NEEDLE || value2.ItemType == clsMeterItem.MeterItemType.MAGIC_EYE))
					{
						addUpdateReading(ref all_readings, value2.ReadingSource, value2.Value);
						continue;
					}
					if (value2.ReadingSource == Reading.NONE && value2.ItemType == clsMeterItem.MeterItemType.CLOCK)
					{
						DateTime now = DateTime.Now;
						DateTime utcNow = DateTime.UtcNow;
						if (value2 is clsClock clsClock2)
						{
							string text = "";
							string text2;
							if (clsClock2.Show24HourCLock)
							{
								text2 = utcNow.ToString("HH:mm:ss");
							}
							else
							{
								text2 = utcNow.ToString("h:mm:ss");
								text = ((utcNow.Hour >= 12) ? "pm" : "am");
							}
							string text3 = "";
							string text4;
							if (clsClock2.Show24HourCLock)
							{
								text4 = now.ToString("HH:mm:ss");
							}
							else
							{
								text4 = now.ToString("h:mm:ss");
								text3 = ((now.Hour >= 12) ? "pm" : "am");
							}
							string value3 = utcNow.ToString("ddd d MMM yyyy");
							string value4 = now.ToString("ddd d MMM yyyy");
							addUpdateReading(ref all_readings, Reading.TIME_UTC, text2 + text);
							addUpdateReading(ref all_readings, Reading.DATE_UTC, value3);
							addUpdateReading(ref all_readings, Reading.TIME_LOC, text4 + text3);
							addUpdateReading(ref all_readings, Reading.DATE_LOC, value4);
						}
						continue;
					}
					if (value2.ReadingSource != Reading.NONE || value2.ItemType != clsMeterItem.MeterItemType.VFO_DISPLAY)
					{
						continue;
					}
					addUpdateReading(ref all_readings, Reading.VFOA_FREQ, VfoA.ToString("f6"));
					addUpdateReading(ref all_readings, Reading.VFOB_FREQ, VfoB.ToString("f6"));
					int num;
					if (RX == 1 && VfoSub >= 0.0 && RX2Enabled)
					{
						if (!MultiRxEnabled)
						{
							num = (Split ? 1 : 0);
							if (num == 0)
							{
								goto IL_02f1;
							}
						}
						else
						{
							num = 1;
						}
						addUpdateReading(ref all_readings, Reading.VFOSUBA_FREQ, VfoSub.ToString("f6"));
					}
					else
					{
						num = 0;
					}
					goto IL_02f1;
					IL_02f1:
					addUpdateReading(ref all_readings, Reading.TX_FREQ, TXVFOb ? VfoB.ToString("f6") : VfoA.ToString("f6"));
					addUpdateReading(ref all_readings, Reading.VFOA_BAND, clearB(BandVfoA.ToString().ToLower()));
					addUpdateReading(ref all_readings, Reading.VFOB_BAND, clearB(BandVfoB.ToString().ToLower()));
					if (num != 0)
					{
						addUpdateReading(ref all_readings, Reading.VFOSUBA_BAND, clearB(BandVfoASub.ToString().ToLower()));
					}
					addUpdateReading(ref all_readings, Reading.VFOA_FILTER_NAME, FilterVfoAName.ToLower());
					addUpdateReading(ref all_readings, Reading.VFOB_FILTER_NAME, FilterVfoBName.ToLower());
					addUpdateReading(ref all_readings, Reading.TX_BAND, clearB(TXVFOb ? BandVfoB.ToString().ToLower() : BandVfoA.ToString().ToLower()));
					addUpdateReading(ref all_readings, Reading.VFOA_MODE, ModeVfoA.ToString().ToLower());
					addUpdateReading(ref all_readings, Reading.VFOB_MODE, ModeVfoB.ToString().ToLower());
					addUpdateReading(ref all_readings, Reading.SPLIT, Split.ToString().ToLower());
					addUpdateReading(ref all_readings, Reading.RX2_ENABLED, RX2Enabled.ToString().ToLower());
					addUpdateReading(ref all_readings, Reading.VFOB_TX, TXVFOb.ToString().ToLower());
					if (RX == 1)
					{
						addUpdateReading(ref all_readings, Reading.SUB_RX, MultiRxEnabled.ToString().ToLower());
					}
				}
				if (_rx != 1 && (_rx != 2 || !_rx2Enabled))
				{
					return;
				}
				foreach (clsMeterItem item in list)
				{
					item.Update(_rx, ref readingsUsed, all_readings);
				}
			}
		}

		private string clearB(string b)
		{
			if (b.Left(1) == "b" || b.Left(1) == "B")
			{
				return b.Substring(1);
			}
			return b;
		}

		public int DelayForUpdate()
		{
			lock (_meterItemsLock)
			{
				int num = int.MaxValue;
				foreach (KeyValuePair<string, clsMeterItem> meterItem in _meterItems)
				{
					int delayUntilNextUpdate = meterItem.Value.DelayUntilNextUpdate;
					if (delayUntilNextUpdate < num)
					{
						num = delayUntilNextUpdate;
					}
				}
				if (num == int.MaxValue)
				{
					num = 250;
				}
				return num;
			}
		}

		private void incrementDisplayGroup()
		{
			_displayGroup++;
			if (_displayGroup > _displayGroups.Count - 1)
			{
				_displayGroup = 0;
			}
		}

		private void decrementDisplayGroup()
		{
			_displayGroup--;
			if (_displayGroup < 0)
			{
				_displayGroup = _displayGroups.Count - 1;
			}
		}

		private void incrementMeterItem(clsClickBox cb)
		{
			if (cb != null && cb.RelatedMeterItem != null)
			{
				cb.RelatedMeterItem.HandleIncrement();
			}
		}

		private void decrementMeterItem(clsClickBox cb)
		{
			if (cb != null && cb.RelatedMeterItem != null)
			{
				cb.RelatedMeterItem.HandleDecrement();
			}
		}

		public void AddDisplayGroup(string sName)
		{
			if (!_displayGroups.Contains(sName))
			{
				_displayGroups.Add(sName);
				_displayGroup = 0;
			}
		}

		public void RemoveDisplayGroup(string sName)
		{
			if (_displayGroups.Contains(sName))
			{
				_displayGroups.Remove(sName);
				_displayGroup = 0;
			}
		}

		public override string ToString()
		{
			return _sId + "|" + _name + "|" + _rx + "|" + _XRatio.ToString("f4") + "|" + _YRatio.ToString("f4") + "|" + _displayGroup + "|" + _fPadX.ToString("f4") + "|" + _fPadY.ToString("f4") + "|" + _fHeight.ToString("f4");
		}
	}

	private class clsReading
	{
		public Reading Type;

		public float Reading;

		public bool Updated;
	}

	private class clsReadings
	{
		private Dictionary<Reading, clsReading> _latestReading;

		public clsReadings()
		{
			_latestReading = new Dictionary<Reading, clsReading>();
			for (int i = 0; i < 74; i++)
			{
				clsReading value = new clsReading
				{
					Type = (Reading)i,
					Reading = -200f,
					Updated = false
				};
				_latestReading.Add((Reading)i, value);
			}
		}

		public float GetReading(Reading rt, bool useReading = false)
		{
			if (rt == Reading.NONE)
			{
				return -200f;
			}
			if (useReading)
			{
				UseReading(rt);
			}
			return _latestReading[rt].Reading;
		}

		public void SetReading(Reading rt, float value)
		{
			if (rt != Reading.NONE)
			{
				_latestReading[rt].Reading = value;
				_latestReading[rt].Updated = true;
			}
		}

		public bool RequiresUpdate(Reading rt)
		{
			if (rt == Reading.NONE)
			{
				return false;
			}
			return !_latestReading[rt].Updated;
		}

		public void UseReading(Reading rt)
		{
			if (rt != Reading.NONE)
			{
				_latestReading[rt].Updated = false;
			}
		}
	}

