				Priority = ThreadPriority.Lowest,
				IsBackground = false
			};
			_dxRenderThread.Start();
		}

		internal void RemoveAnySkinImages()
		{
			lock (_DXlock)
			{
				foreach (string item in (from pair in _images
					where pair.Value.Tag is bool
					select pair.Key).ToList())
				{
					RemoveDXImage(item);
				}
			}
		}

		private void convertImageToDX(string sID)
		{
			if (string.IsNullOrEmpty(sID) || _images.ContainsKey(sID))
			{
				return;
			}
			System.Drawing.Bitmap bitmap = GetBitmap(sID);
			if (bitmap != null)
			{
				SharpDX.Direct2D1.Bitmap bitmap2 = bitmapFromSystemBitmap(_renderTarget, bitmap, sID);
				if (bitmap2 != null)
				{
					bitmap2.Tag = bitmap.Tag;
					_images.Add(sID, bitmap2);
				}
			}
		}

		private int getMaxSamples()
		{
			for (int num = 32; num > 0; num /= 2)
			{
				if (_device.CheckMultisampleQualityLevels(Format.B8G8R8A8_UNorm, num) > 0)
				{
					return num;
				}
			}
			return 1;
		}

		private void dxInit(DriverType driverType = DriverType.Hardware, Display.AdaptorInfo adaptorInfo = null)
		{
			if (_bDXSetup)
			{
				return;
			}
			try
			{
				DeviceCreationFlags deviceCreationFlags = DeviceCreationFlags.None;
				int major = Environment.OSVersion.Version.Major;
				int minor = Environment.OSVersion.Version.Minor;
				SharpDX.Direct3D.FeatureLevel[] featureLevels;
				if (major >= 10)
				{
					featureLevels = new SharpDX.Direct3D.FeatureLevel[9]
					{
						SharpDX.Direct3D.FeatureLevel.Level_12_1,
						SharpDX.Direct3D.FeatureLevel.Level_12_0,
						SharpDX.Direct3D.FeatureLevel.Level_11_1,
						SharpDX.Direct3D.FeatureLevel.Level_11_0,
						SharpDX.Direct3D.FeatureLevel.Level_10_1,
						SharpDX.Direct3D.FeatureLevel.Level_10_0,
						SharpDX.Direct3D.FeatureLevel.Level_9_3,
						SharpDX.Direct3D.FeatureLevel.Level_9_2,
						SharpDX.Direct3D.FeatureLevel.Level_9_1
					};
					_NoVSYNCpresentFlag = PresentFlags.DoNotWait;
				}
				else if (major == 6 && minor >= 2)
				{
					featureLevels = new SharpDX.Direct3D.FeatureLevel[7]
					{
						SharpDX.Direct3D.FeatureLevel.Level_11_1,
						SharpDX.Direct3D.FeatureLevel.Level_11_0,
						SharpDX.Direct3D.FeatureLevel.Level_10_1,
						SharpDX.Direct3D.FeatureLevel.Level_10_0,
						SharpDX.Direct3D.FeatureLevel.Level_9_3,
						SharpDX.Direct3D.FeatureLevel.Level_9_2,
						SharpDX.Direct3D.FeatureLevel.Level_9_1
					};
					_NoVSYNCpresentFlag = PresentFlags.DoNotWait;
