					_renderTarget = new RenderTarget(properties: new RenderTargetProperties(new SharpDX.Direct2D1.PixelFormat(_swapChain.Description.ModeDescription.Format, SharpDX.Direct2D1.AlphaMode.Premultiplied)), factory: _factory, dxgiSurface: _surface);
