		private void OnMouseEnter(object sender, EventArgs e)
		{
			if (!(sender is Panel panel))
			{
				return;
			}
			string key = panel.Tag.ToString();
			if (!_meters.ContainsKey(key))
			{
				return;
			}
			clsMeter clsMeter2 = _meters[key];
			lock (clsMeter2._meterItemsLock)
			{
				if (clsMeter2.SortedMeterItemsForZOrder == null)
				{
					return;
				}
				foreach (clsMeterItem item in clsMeter2.SortedMeterItemsForZOrder)
				{
					item.MouseEntered = true;
				}
			}
		}

