		private void OnDragEnter(object sender, DragEventArgs e)
		{
			if (Common.IsAdministrator())
			{
				e.Effect = DragDropEffects.None;
				return;
			}
			string[] filePaths = (e.Data.GetDataPresent(DataFormats.FileDrop) ? (e.Data.GetData(DataFormats.FileDrop) as string[]) : null);
			clsWaveRecord clsWaveRecord2 = tryGetWaveRecordDropTarget(sender, new System.Drawing.Point(e.X, e.Y));
			e.Effect = ((clsWaveRecord2 != null && clsWaveRecord2.CanAcceptFiles(filePaths)) ? DragDropEffects.Copy : DragDropEffects.None);
		}

