		private void OnDragDrop(object sender, DragEventArgs e)
		{
			if (!Common.IsAdministrator())
			{
				string[] filePaths = (e.Data.GetDataPresent(DataFormats.FileDrop) ? (e.Data.GetData(DataFormats.FileDrop) as string[]) : null);
				clsWaveRecord clsWaveRecord2 = tryGetWaveRecordDropTarget(sender, new System.Drawing.Point(e.X, e.Y));
				if (clsWaveRecord2 != null && clsWaveRecord2.CanAcceptFiles(filePaths))
				{
					clsWaveRecord2.AddFiles(filePaths);
				}
			}
		}

		private clsWaveRecord tryGetWaveRecordDropTarget(object sender, System.Drawing.Point screenPoint)
		{
			lock (_metersLock)
			{
				if (!(sender is Panel { Tag: not null } panel))
				{
					return null;
				}
				string text = panel.Tag.ToString();
				if (string.IsNullOrWhiteSpace(text) || !_meters.ContainsKey(text))
				{
					return null;
				}
				clsMeter clsMeter2 = _meters[text];
				System.Drawing.Point point = panel.PointToClient(screenPoint);
				lock (clsMeter2._meterItemsLock)
				{
					if (clsMeter2.SortedMeterItemsForZOrder == null)
					{
						return null;
					}
					float num = (float)targetWidth - 1f;
					float xRatio = clsMeter2.XRatio;
					float yRatio = clsMeter2.YRatio;
					SharpDX.RectangleF rectangleF = new SharpDX.RectangleF(0f, 0f, num * xRatio, num * yRatio);
					for (int num2 = clsMeter2.SortedMeterItemsForZOrder.Count - 1; num2 >= 0; num2--)
					{
						clsMeterItem clsMeterItem2 = clsMeter2.SortedMeterItemsForZOrder[num2];
						if (clsMeterItem2.ItemType == clsMeterItem.MeterItemType.WAVE_RECORD)
						{
							float x = clsMeterItem2.DisplayTopLeft.X / clsMeter2.XRatio * rectangleF.Width;
							float y = clsMeterItem2.DisplayTopLeft.Y / clsMeter2.YRatio * rectangleF.Height;
							float width = rectangleF.Width * (clsMeterItem2.Size.Width / clsMeter2.XRatio);
							float height = rectangleF.Height * (clsMeterItem2.Size.Height / clsMeter2.YRatio);
							if (new SharpDX.RectangleF(x, y, width, height).Contains(new SharpDX.Point(point.X, point.Y)))
							{
								return clsMeterItem2 as clsWaveRecord;
							}
						}
					}
				}
			}
			return null;
		}

		private int drawMeters(out int height)
		{
			int num = int.MaxValue;
			clsMeter meter = _meter;
			height = 24;
			lock (meter._meterItemsLock)
			{
				_quickest_update_interval = meter.QuickestUpdateInterval(meter.MOX, console_only_refresh: false);
				if (meter.RX == _rx && meter.SortedMeterItemsForZOrder != null && meter.SortedMeterItemsForZOrder.Count > 0)
				{
					float num2 = (float)targetWidth - 1f;
					int num3 = (meter.MOX ? meter.QuickestTXUpdate : meter.QuickestRXUpdate);
					if (num3 < num)
					{
						num = num3;
					}
					List<clsMeterItem> list = new List<clsMeterItem>();
					_waterfall_row_added = false;
					float xRatio = meter.XRatio;
					float yRatio = meter.YRatio;
					SharpDX.RectangleF rect = new SharpDX.RectangleF(0f, 0f, num2 * xRatio, num2 * yRatio);
					foreach (clsMeterItem item in meter.SortedMeterItemsForZOrder)
					{
						if (((!meter.MOX || !item.OnlyWhenTX) && (meter.MOX || !item.OnlyWhenRX) && (item.OnlyWhenTX || item.OnlyWhenRX)) || (meter.DisplayGroup != 0 && item.DisplayGroup != 0 && item.DisplayGroup != meter.DisplayGroup))
						{
							continue;
						}
						switch (item.ItemType)
						{
						case clsMeterItem.MeterItemType.ITEM_GROUP:
						{
							float num4 = item.DisplayTopLeft.Y / meter.YRatio * rect.Height;
							float num5 = rect.Height * (item.Size.Height / meter.YRatio);
							float num6 = rect.Width * (item.Size.Width / meter.XRatio);
							float num7 = (meter.PadY - meter.Height * 0.75f) * num6;
							int num8 = (int)Math.Ceiling(num4 + num5 + num7) + 1;
							if (num8 > height)
							{
								height = num8;
							}
							break;
						}
						case clsMeterItem.MeterItemType.H_BAR:
						{
							clsMeterItem clsMeterItem2 = renderHBar(rect, item, meter);
							if (clsMeterItem2 != null)
							{
								renderHBarMarkersOnly(rect, clsMeterItem2, meter);
							}
							break;
						}
						case clsMeterItem.MeterItemType.SOLID_COLOUR:
							renderSolidColour(rect, item, meter);
							break;
						case clsMeterItem.MeterItemType.NEEDLE:
							renderNeedle(rect, item, meter);
							break;
						case clsMeterItem.MeterItemType.IMAGE:
							renderImage(rect, item, meter);
							break;
						case clsMeterItem.MeterItemType.TEXT:
							renderText(rect, item, meter);
							break;
						case clsMeterItem.MeterItemType.H_SCALE:
						case clsMeterItem.MeterItemType.V_SCALE:
							renderScale(rect, item, meter);
							break;
						case clsMeterItem.MeterItemType.NEEDLE_SCALE_PWR:
							renderNeedleScale(rect, item, meter);
							break;
						case clsMeterItem.MeterItemType.MAGIC_EYE:
							renderEye(rect, item, meter);
							break;
						case clsMeterItem.MeterItemType.SPACER:
							renderSpacer(rect, item, meter);
							break;
						case clsMeterItem.MeterItemType.WEB_IMAGE:
							renderWebImage(rect, item, meter);
							break;
						case clsMeterItem.MeterItemType.TEXT_OVERLAY:
							renderTextOverlay(rect, item, meter, render_text: false);
							list.Add(item);
							break;
						case clsMeterItem.MeterItemType.LED:
							renderLed(rect, item, meter, draw_led: false);
							list.Add(item);
							break;
						case clsMeterItem.MeterItemType.ROTATOR:
							renderRotator(rect, item, meter);
							break;
						case clsMeterItem.MeterItemType.VFO_DISPLAY:
							renderVfoDisplay(rect, item, meter);
							break;
						case clsMeterItem.MeterItemType.CLOCK:
							renderClock(rect, item, meter);
							break;
						case clsMeterItem.MeterItemType.SIGNAL_TEXT_DISPLAY:
							renderSignalTextDisplay(rect, item, meter);
							break;
						case clsMeterItem.MeterItemType.BAND_BUTTONS:
						case clsMeterItem.MeterItemType.MODE_BUTTONS:
						case clsMeterItem.MeterItemType.FILTER_BUTTONS:
						case clsMeterItem.MeterItemType.ANTENNA_BUTTONS:
						case clsMeterItem.MeterItemType.TUNESTEP_BUTTONS:
						case clsMeterItem.MeterItemType.DISCORD_BUTTONS:
						case clsMeterItem.MeterItemType.OTHER_BUTTONS:
						case clsMeterItem.MeterItemType.VOICE_RECORD_PLAY_BUTTONS:
							renderButtonBox(rect, item, meter);
							break;
						case clsMeterItem.MeterItemType.WAVE_RECORD:
							renderWaveRecord(rect, item, meter);
							break;
						case clsMeterItem.MeterItemType.FADE_COVER:
							renderFadeCover(rect, item, meter);
							break;
						case clsMeterItem.MeterItemType.HISTORY:
							renderHistory(rect, item, meter);
							break;
						case clsMeterItem.MeterItemType.FILTER_DISPLAY:
							renderFilterDisplay(rect, item, meter);
							break;
						case clsMeterItem.MeterItemType.DIAL_DISPLAY:
							renderDialDisplay(rect, item, meter);
							break;
						}
					}
					foreach (clsMeterItem item2 in list)
					{
						switch (item2.ItemType)
						{
						case clsMeterItem.MeterItemType.TEXT_OVERLAY:
							if (renderTextOverlay(rect, item2, meter, render_text: true) && num > 32)
							{
								num = 32;
							}
							break;
						case clsMeterItem.MeterItemType.LED:
							renderLed(rect, item2, meter, draw_led: true);
							break;
						}
					}
				}
			}
			return num;
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private SizeF measureString(string sText, string sFontFamily, System.Drawing.FontStyle style, float emSize, bool ignore_caching = false)
		{
			if (!_bDXSetup || string.IsNullOrEmpty(sText))
			{
				return SizeF.Empty;
			}
			float num = (float)Math.Round(emSize, 2);
			if (num == 0f)
			{
				return SizeF.Empty;
			}
			(string, float, System.Drawing.FontStyle, string) tuple = (sFontFamily, num, style, sText);
			if (!ignore_caching && _stringMeasure.TryGetValue(tuple, out var value))
			{
				return value;
			}
			FontWeight fontWeight = (((style & System.Drawing.FontStyle.Bold) != System.Drawing.FontStyle.Regular) ? FontWeight.Bold : FontWeight.Normal);
			SharpDX.DirectWrite.FontStyle fontStyle = (((style & System.Drawing.FontStyle.Italic) != System.Drawing.FontStyle.Regular) ? SharpDX.DirectWrite.FontStyle.Italic : SharpDX.DirectWrite.FontStyle.Normal);
			(string, float, FontWeight, SharpDX.DirectWrite.FontStyle) tuple2 = (sFontFamily, num, fontWeight, fontStyle);
			if (!_format_cache.TryGetValue(tuple2, out var value2))
			{
				value2 = new TextFormat(_fontFactory, sFontFamily, fontWeight, fontStyle, num);
				value2.WordWrapping = WordWrapping.NoWrap;
				_format_cache.Add(tuple2, value2);
				_format_cache_keys.Enqueue(tuple2);
				if (_format_cache.Count > 2000)
				{
					(string, float, FontWeight, SharpDX.DirectWrite.FontStyle) key = _format_cache_keys.Dequeue();
					if (_format_cache.TryGetValue(key, out var value3))
					{
						Utilities.Dispose(ref value3);
						_format_cache.Remove(key);
					}
				}
			}
			TextLayout comObject = new TextLayout(_fontFactory, sText, value2, float.MaxValue, float.MaxValue);
			float width = comObject.Metrics.Width;
			float height = comObject.Metrics.Height;
			Utilities.Dispose(ref comObject);
			value = new SizeF(width * _pixels_per_point_width, height * _pixels_per_point_height);
			if (!ignore_caching)
			{
				if (_stringMeasure.ContainsKey(tuple))
				{
					_stringMeasure[tuple] = value;
				}
				else
				{
					_stringMeasure.Add(tuple, value);
					_stringMeasureKeys.Enqueue(tuple);
					if (_stringMeasure.Count > 2000)
					{
						(string, float, System.Drawing.FontStyle, string) key2 = _stringMeasureKeys.Dequeue();
						_stringMeasure.Remove(key2);
					}
				}
			}
			return value;
		}

		private int fade(clsMeterItem mi, clsMeter m)
