		private static float[] ResampleWaterfallRow(SharedWaterfallState.PerRxSnapshot snap, int outWidth, int specLow, int specHigh)
		{
			float[] waterfallRow = snap.WaterfallRow;
			int num = Math.Min(snap.WaterfallRowWidth, waterfallRow.Length);
			float[] array = new float[outWidth];
			float rXDisplayOffsetDb = snap.RXDisplayOffsetDb;
			float num2 = snap.RXDisplayHighHz - snap.RXDisplayLowHz;
			if (num < 2 || num2 <= 0f || specHigh <= specLow)
			{
				for (int i = 0; i < outWidth; i++)
				{
					array[i] = -200f;
				}
				return array;
			}
			for (int j = 0; j < outWidth; j++)
			{
				float num3 = ((float)specLow + (float)((specHigh - specLow) * j) / (float)(outWidth - 1) - snap.RXDisplayLowHz) * (float)(num - 1) / num2;
				if (num3 < 0f || num3 > (float)(num - 1))
				{
					array[j] = -200f;
					continue;
				}
				int num4 = (int)num3;
				int num5 = num4 + 1;
				if (num5 >= num)
				{
					num5 = num - 1;
				}
				float num6 = num3 - (float)num4;
				array[j] = waterfallRow[num4] + (waterfallRow[num5] - waterfallRow[num4]) * num6 + rXDisplayOffsetDb;
			}
			return array;
		}

		private static void BuildPaletteRows(WaterfallPalette pal, float[] data, int width, float low, float high, byte[] row_rx, byte alpha_rx, byte[] row_tx, byte alpha_tx)
		{
			float num = high - low;
			if (num < 0.001f)
			{
