		private float hzToPixels(double hz, float pixel_span, int hz_span)
		{
			if (hz <= 0.0 || pixel_span <= 0f || hz_span <= 0)
			{
				return 0f;
			}
			return (float)((double)(pixel_span / (float)hz_span) * hz);
		}

		private double pixelsToHz(float pixels, float pixel_span, int hz_span)
		{
			if (pixel_span <= 0f || hz_span <= 0)
			{
				return 0.0;
			}
			return pixels / pixel_span * (float)hz_span;
		}

		public bool isMouseNearLine(RawVector2 point1, RawVector2 point2, PointF mousePosition, float proximityThreshold = 3f)
		{
			return pointToSegmentDistance(point1, point2, mousePosition) <= proximityThreshold;
		}

		private float pointToSegmentDistance(RawVector2 lineStart, RawVector2 lineEnd, PointF point)
		{
			float num = (lineEnd.X - lineStart.X) * (lineEnd.X - lineStart.X) + (lineEnd.Y - lineStart.Y) * (lineEnd.Y - lineStart.Y);
			if (num == 0f)
			{
				return distanceBetweenPoints(lineStart, point);
			}
			float val = ((point.X - lineStart.X) * (lineEnd.X - lineStart.X) + (point.Y - lineStart.Y) * (lineEnd.Y - lineStart.Y)) / num;
			val = Math.Max(0f, Math.Min(1f, val));
			RawVector2 p = new RawVector2(lineStart.X + val * (lineEnd.X - lineStart.X), lineStart.Y + val * (lineEnd.Y - lineStart.Y));
			return distanceBetweenPoints(p, point);
		}

		private float distanceBetweenPoints(RawVector2 p1, PointF p2)
		{
			return (float)Math.Sqrt((p1.X - p2.X) * (p1.X - p2.X) + (p1.Y - p2.Y) * (p1.Y - p2.Y));
		}

