		private string convertDegreesToCardinal(float degrees)
		{
			string[] array = new string[17]
			{
				"N", "NNE", "NE", "ENE", "E", "ESE", "SE", "SSE", "S", "SSW",
				"SW", "WSW", "W", "WNW", "NW", "NNW", "N"
			};
			float[] array2 = new float[17]
			{
				0f, 11.25f, 33.75f, 56.25f, 78.75f, 101.25f, 123.75f, 146.25f, 168.75f, 191.25f,
				213.75f, 236.25f, 258.75f, 281.25f, 303.75f, 326.25f, 348.75f
			};
			degrees %= 360f;
			for (int i = 0; i < array2.Length - 1; i++)
			{
				if (degrees >= array2[i] && degrees < array2[i + 1])
				{
					return array[i];
				}
			}
			return array[0];
		}

