		private void getParts(double vfoFreq, out string MHz, out string kHz, out string hz)
		{
			string text = vfoFreq.ToString("0.000000");
			int num = text.IndexOf(".");
			MHz = text.Substring(0, num);
			kHz = text.Substring(num + 1, 3);
