		private void shrinkRectangle(SharpDX.RectangleF original, float ratio, ref SharpDX.RectangleF shrunk, float absolute = 0f)
		{
			float num = original.Width * ratio;
			float num2 = original.Height * ratio;
			num -= absolute;
			num2 -= absolute;
			if (num < 0f)
			{
				num = 0f;
			}
			if (num2 < 0f)
			{
				num2 = 0f;
			}
			float num3 = (original.Width - num) / 2f;
			float num4 = (original.Height - num2) / 2f;
			shrunk.X = original.X + num3;
			shrunk.Y = original.Y + num4;
			shrunk.Width = num;
			shrunk.Height = num2;
		}

