		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private System.Drawing.Color dimColour(System.Drawing.Color colour, bool dim, float amount = 0.35f)
		{
			if (amount < 0f)
			{
				amount = 0f;
			}
			if (amount > 1f)
			{
				amount = 1f;
			}
			byte red = (byte)(dim ? ((float)(int)colour.R * amount) : ((float)(int)colour.R));
			byte green = (byte)(dim ? ((float)(int)colour.G * amount) : ((float)(int)colour.G));
			byte blue = (byte)(dim ? ((float)(int)colour.B * amount) : ((float)(int)colour.B));
			return System.Drawing.Color.FromArgb(red, green, blue);
		}

