		private void drawWaveRecordIcon(string icon, SharpDX.RectangleF buttonRect, System.Drawing.Color iconColour, int fade)
		{
			convertImageToDX(icon);
			if (!_images.ContainsKey(icon))
			{
				return;
			}
			SharpDX.Direct2D1.Bitmap bitmap = _images[icon];
			float num = Math.Min(buttonRect.Width, buttonRect.Height) * 0.58f;
			SharpDX.RectangleF rectangleF = new SharpDX.RectangleF(buttonRect.Left + (buttonRect.Width - num) / 2f, buttonRect.Top + (buttonRect.Height - num) / 2f, num, num);
			Matrix3x2 matrix3x = _renderTarget.Transform;
			AntialiasMode antialiasMode = _renderTarget.AntialiasMode;
			try
			{
				_renderTarget.AntialiasMode = AntialiasMode.Aliased;
				_renderTarget.Transform = Matrix3x2.Identity;
				_renderTarget.FillOpacityMask(bitmap, getDXBrushForColour(iconColour, fade), OpacityMaskContent.Graphics, rectangleF, new RawRectangleF(0f, 0f, bitmap.Size.Width, bitmap.Size.Height));
			}
			finally
			{
				_renderTarget.AntialiasMode = antialiasMode;
				_renderTarget.Transform = matrix3x;
			}
		}

		private SharpDX.RectangleF clipRect(SharpDX.RectangleF value, SharpDX.RectangleF clip)
		{
			float num = Math.Max(value.Left, clip.Left);
			float num2 = Math.Max(value.Top, clip.Top);
			float num3 = Math.Min(value.Right, clip.Right);
			float num4 = Math.Min(value.Bottom, clip.Bottom);
			if (num3 <= num || num4 <= num2)
			{
				return default(SharpDX.RectangleF);
			}
			return new SharpDX.RectangleF(num, num2, num3 - num, num4 - num2);
		}

		private bool rectEmpty(SharpDX.RectangleF value)
		{
			if (!(value.Width <= 0f))
			{
				return value.Height <= 0f;
			}
			return true;
		}

		private bool samePath(string left, string right)
		{
			if (string.IsNullOrWhiteSpace(left) || string.IsNullOrWhiteSpace(right))
			{
				return false;
			}
			return string.Equals(left, right, StringComparison.OrdinalIgnoreCase);
		}

