		private double degToRad(float deg)
		{
			return (double)deg * Math.PI / 180.0;
		}

		private double radToDeg(float rad)
		{
			return (double)rad * (180.0 / Math.PI);
		}

		private void getPerc(clsMeterItem mi, float rawValue, out float percX, out float percY, out PointF min, out PointF max)
		{
			percX = 0f;
			percY = 0f;
			min = new PointF(0f, 0f);
			max = new PointF(0f, 0f);
			float num = (float)Math.Round(rawValue, 2);
			if (mi.ReadingSource == Reading.SIGNAL_STRENGTH || mi.ReadingSource == Reading.AVG_SIGNAL_STRENGTH)
			{
				num += dbmOffsetForAboveS9Frequency(_rx);
			}
			else if (mi.NormaliseTo100W)
			{
				num *= 100f / mi.MaxPower;
			}
			else if (mi.IsCustom)
			{
				float num2 = Math.Max(mi.CustomMin, Math.Min(mi.CustomMax, num));
				float num3 = mi.CustomMax - mi.CustomMin;
				num = ((num3 != 0f) ? ((num2 - mi.CustomMin) / num3 * 100f) : 0f);
			}
			clsMeterItem.clsPercCache perc = mi.GetPerc(num);
			if (perc != null)
			{
				percX = perc._percX;
				percY = perc._percY;
				min = perc._min;
				max = perc._max;
			}
			else if (mi._scales_calibKeys.Length != 0)
			{
				float[] scales_calibKeys = mi._scales_calibKeys;
				PointF[] scales_calibValues = mi._scales_calibValues;
				int num4 = Array.BinarySearch(scales_calibKeys, num);
				bool num5 = num4 >= 0;
				int num6 = (num5 ? num4 : (~num4 - 1));
				int num7 = (num5 ? num4 : (~num4));
				if (num6 < 0)
				{
					num6 = 0;
				}
				if (num7 < 0)
				{
					num7 = 0;
				}
				if (num6 >= scales_calibKeys.Length)
				{
					num6 = scales_calibKeys.Length - 1;
				}
				if (num7 >= scales_calibKeys.Length)
				{
					num7 = scales_calibKeys.Length - 1;
				}
				PointF pointF = scales_calibValues[num6];
				PointF pointF2 = scales_calibValues[num7];
				float num8 = scales_calibKeys[num6];
				float num9 = scales_calibKeys[num7];
				bool num10 = num6 == num7;
				float num11 = mi._scales_maxX - mi._scales_minX;
				float num12 = mi._scales_maxY - mi._scales_minY;
				float num13 = (num10 ? pointF.X : (pointF.X + (pointF2.X - pointF.X) * ((num - num8) / (num9 - num8))));
				float num14 = (num10 ? pointF.Y : (pointF.Y + (pointF2.Y - pointF.Y) * ((num - num8) / (num9 - num8))));
				percX = ((num11 > 0f) ? ((num13 - mi._scales_minX) / num11) : 0f);
				percY = ((num12 > 0f) ? ((num14 - mi._scales_minY) / num12) : 0f);
				min = new PointF(mi._scales_minX, mi._scales_minY);
				max = new PointF(mi._scales_maxX, mi._scales_maxY);
				clsMeterItem.clsPercCache pc = new clsMeterItem.clsPercCache
				{
					_value = num,
					_percX = percX,
					_percY = percY,
					_min = min,
					_max = max
				};
				mi.AddPerc(pc);
			}
		}

		private SharpDX.Direct2D1.Bitmap bitmapFromSystemBitmap(RenderTarget rt, System.Drawing.Bitmap bitmap, string sId)
		{
			try
			{
				ImagingFactory comObject = null;
				BitmapDecoder comObject2 = null;
				BitmapFrameDecode comObject3 = null;
				FormatConverter comObject4 = null;
				SharpDX.Direct2D1.Bitmap result;
				if (ContainsStreamData(sId))
				{
					MemoryStream streamData = GetStreamData(sId);
					streamData.Position = 0L;
					try
					{
						comObject = new ImagingFactory();
						comObject2 = new BitmapDecoder(comObject, streamData, DecodeOptions.CacheOnDemand);
						comObject3 = comObject2.GetFrame(0);
						comObject4 = new FormatConverter(comObject);
						comObject4.Initialize(comObject3, SharpDX.WIC.PixelFormat.Format32bppPBGRA);
						result = SharpDX.Direct2D1.Bitmap.FromWicBitmap(rt, comObject4);
					}
					finally
					{
						Utilities.Dispose(ref comObject4);
						Utilities.Dispose(ref comObject3);
						Utilities.Dispose(ref comObject2);
						Utilities.Dispose(ref comObject);
					}
				}
				else
				{
					MemoryStream memoryStream = new MemoryStream();
					bitmap.Save(memoryStream, ImageFormat.Png);
					memoryStream.Position = 0L;
					try
					{
						comObject = new ImagingFactory();
						comObject2 = new BitmapDecoder(comObject, memoryStream, DecodeOptions.CacheOnDemand);
						comObject3 = comObject2.GetFrame(0);
						comObject4 = new FormatConverter(comObject);
						comObject4.Initialize(comObject3, SharpDX.WIC.PixelFormat.Format32bppPBGRA);
						result = SharpDX.Direct2D1.Bitmap.FromWicBitmap(rt, comObject4);
					}
					finally
					{
						Utilities.Dispose(ref comObject4);
						Utilities.Dispose(ref comObject3);
						Utilities.Dispose(ref comObject2);
						Utilities.Dispose(ref comObject);
					}
					AddStreamData(sId, memoryStream);
				}
				return result;
			}
			catch (Exception)
			{
				return null;
			}
		}
	}

