	private static MeterScriptEngine.Snapshot provide_variables()
	{
		MeterScriptEngine.Snapshot snapshot = new MeterScriptEngine.Snapshot();
		snapshot.Common = new Dictionary<string, object>();
		snapshot.Banks = new Dictionary<string, object>[2];
		foreach (KeyValuePair<Guid, MultiMeterIO.clsMMIO> datum in MultiMeterIO.Data)
		{
			MultiMeterIO.clsMMIO value = datum.Value;
			foreach (KeyValuePair<string, object> item in value.Variables())
			{
				snapshot.Common[item.Key] = value.GetVariable(item.Key);
			}
		}
		for (int i = 1; i <= 2; i++)
		{
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			foreach (KeyValuePair<string, object> item2 in _led_readings[i - 1])
			{
				dictionary[item2.Key] = item2.Value;
			}
			snapshot.Banks[i - 1] = dictionary;
		}
		return snapshot;
	}

