	private static void OnCatQmessage(int queue_index, Guid guid, ScriptCommand sc)
	{
		if (!guard_holds(sc) || queue_index != 0)
		{
			return;
		}
		string result = _console.ThreadSafeCatParse(sc.text);
		switch (sc.type)
		{
		case ScriptCommandType.CatMessageVar:
		{
			string key = normalise_var(sc.variable_name);
			_cat_variables.AddOrUpdate(key, result, (string a, string b) => result);
			rebuildAllLedReadings();
			break;
		}
		case ScriptCommandType.CatState:
			CatStateHandlers?.Invoke(queue_index, guid, sc, result);
			break;
		case ScriptCommandType.CatMessage:
		case ScriptCommandType.Wait:
			break;
		}
	}

	private static bool guard_holds(ScriptCommand c)
	{
		if (c.guard_true != null)
		{
			int i = 0;
			for (int count = c.guard_true.Count; i < count; i++)
			{
				if (!eval_now(c.ID, c.macro, c.button_index, c.guard_true[i]))
				{
					return false;
				}
			}
		}
		if (c.guard_false != null)
		{
			int j = 0;
			for (int count2 = c.guard_false.Count; j < count2; j++)
			{
				if (eval_now(c.ID, c.macro, c.button_index, c.guard_false[j]))
				{
					return false;
				}
			}
		}
		return true;
	}

	private static bool eval_now(string id, int macro, int button_index, string name)
	{
		if (macro < 0 || macro > 30)
		{
			return false;
		}
		clsOtherButtons otherButtonsFromID = GetOtherButtonsFromID(id);
		if (otherButtonsFromID == null)
		{
			return false;
		}
		if (string.Equals(name, "ON", StringComparison.OrdinalIgnoreCase))
		{
			return otherButtonsFromID.GetOn(1, button_index);
		}
		if (string.Equals(name, "OFF", StringComparison.OrdinalIgnoreCase))
		{
			return !otherButtonsFromID.GetOn(1, button_index);
		}
		if (name.StartsWith("%") && name.EndsWith("%"))
		{
			int num = name.LastIndexOf("%");
			string text = name.Substring(1, num - 1);
			foreach (KeyValuePair<Guid, MultiMeterIO.clsMMIO> datum in MultiMeterIO.Data)
			{
				foreach (KeyValuePair<string, object> item in datum.Value.Variables())
				{
					if (!text.Equals(item.Key, StringComparison.OrdinalIgnoreCase))
					{
						continue;
					}
					try
					{
						if (item.Value.GetType() == typeof(bool))
						{
							return (bool)item.Value;
						}
					}
					catch
					{
					}
				}
			}
		}
		if (name.StartsWith("$") && name.EndsWith("$"))
		{
			int num2 = name.LastIndexOf("$");
			string key = name.Substring(1, num2 - 1);
			if (_led_results.TryGetValue(key, out var value))
			{
				return value;
			}
		}
		return false;
	}

	private static string normalise_var(string name)
	{
		string text = name ?? string.Empty;
		if (!text.StartsWith("%", StringComparison.Ordinal))
		{
			text = "%" + text;
		}
		if (!text.EndsWith("%", StringComparison.Ordinal))
		{
			text += "%";
		}
		return text;
	}

