	public static void FilterItemFrequencies(FilterItemSnapFrequencies setting_group, string settings)
	{
		if (string.IsNullOrEmpty(settings))
		{
			return;
		}
		settings = settings.Trim().Replace(" ", "");
		if (string.IsNullOrEmpty(settings))
		{
			return;
		}
		string[] array = settings.Split(',');
		if (array.Length == 0)
		{
			return;
		}
		List<float> list = new List<float>();
		string[] array2 = array;
		foreach (string text in array2)
		{
			if (string.IsNullOrEmpty(text) || !float.TryParse(text, out var result))
			{
				continue;
			}
			result = Math.Abs(result);
			switch (setting_group)
			{
			case FilterItemSnapFrequencies.OTHER:
				if (!list.Contains(0f - result))
				{
					list.Add(0f - result);
				}
				if (!list.Contains(result))
				{
					list.Add(result);
				}
				break;
			case FilterItemSnapFrequencies.SIDEBANDS:
			case FilterItemSnapFrequencies.CW:
				if (!list.Contains(0f))
				{
					list.Add(0f);
				}
				if (!list.Contains(0f - result))
				{
					list.Add(0f - result);
				}
				if (!list.Contains(result))
				{
					list.Add(result);
				}
				break;
			}
		}
		lock (_snap_freqs_locker)
		{
			list.Sort();
			switch (setting_group)
			{
			case FilterItemSnapFrequencies.OTHER:
				_snap_freqs_other = list.ToArray();
				break;
			case FilterItemSnapFrequencies.CW:
				_snap_freqs_cw = list.ToArray();
				break;
			case FilterItemSnapFrequencies.SIDEBANDS:
				_snap_freqs_sidebands = list.ToArray();
				break;
			}
		}
	}

	public static float[] GetFilterItemFrequencies(FilterItemSnapFrequencies setting_group)
	{
		lock (_snap_freqs_locker)
		{
			return setting_group switch
			{
				FilterItemSnapFrequencies.OTHER => (float[])_snap_freqs_other.Clone(), 
				FilterItemSnapFrequencies.CW => (float[])_snap_freqs_cw.Clone(), 
				FilterItemSnapFrequencies.SIDEBANDS => (float[])_snap_freqs_sidebands.Clone(), 
				_ => null, 
			};
		}
	}

