	public static void ZeroReading(out float value, int rx, Reading reading)
	{
		value = 0f;
		switch (reading)
		{
		case Reading.SIGNAL_STRENGTH:
		case Reading.AVG_SIGNAL_STRENGTH:
		case Reading.SIGNAL_MAX_BIN:
			if (IsAboveS9Frequency(rx))
			{
				value = -153f;
			}
			else
			{
				value = -133f;
			}
			break;
		case Reading.ADC_PK:
		case Reading.ADC_AV:
			value = -120f;
			break;
		case Reading.AGC_PK:
		case Reading.AGC_AV:
			value = -125f;
			break;
		case Reading.AGC_GAIN:
			value = -50f;
			break;
		case Reading.MIC:
		case Reading.MIC_PK:
			value = -120f;
			break;
		case Reading.LEVELER:
		case Reading.LEVELER_PK:
			value = -30f;
			break;
		case Reading.EQ:
		case Reading.EQ_PK:
			value = -30f;
			break;
		case Reading.LVL_G:
			value = 0f;
			break;
		case Reading.ALC:
		case Reading.ALC_PK:
			value = -120f;
			break;
		case Reading.ALC_G:
			value = 0f;
			break;
		case Reading.ALC_GROUP:
			value = -30f;
			break;
		case Reading.CFC_PK:
		case Reading.CFC_AV:
			value = -30f;
			break;
		case Reading.CFC_G:
			value = 0f;
			break;
		case Reading.COMP:
		case Reading.COMP_PK:
			value = -30f;
			break;
		case Reading.PWR:
		case Reading.REVERSE_PWR:
			value = 0f;
			break;
		case Reading.SWR:
			value = 1f;
			break;
		case Reading.ESTIMATED_PBSNR:
			value = 0f;
			break;
		case Reading.VOLTS:
			value = 0f;
			break;
		case Reading.AMPS:
			value = 0f;
			break;
		case Reading.ADC_MAX_MAG:
			value = 0f;
			break;
		}
		setReadingForced(rx, reading, value);
	}

	public static int GetMeterTXRXType(MeterType meter)
	{
		return meter switch
