	private static void UpdateMeters()
	{
		List<Reading> readingsUsed = new List<Reading>();
		_meterThreadRunning = true;
		while (_meterThreadRunning)
		{
			if (_finishedSetup)
			{
				int num = int.MaxValue;
				lock (_metersLock)
				{
					foreach (KeyValuePair<string, clsMeter> meter in _meters)
					{
						clsMeter value = meter.Value;
						if (!value.Enabled && !value.UpdateAlways())
						{
							continue;
						}
						readingsUsed.Clear();
						value.Update(ref readingsUsed);
						int num2 = value.DelayForUpdate();
						if (num2 < num)
						{
							num = num2;
						}
						foreach (Reading item in readingsUsed)
						{
							_readings[value.RX].UseReading(item);
						}
					}
				}
				if (num == int.MaxValue)
				{
					num = 250;
				}
				Thread.Sleep(num);
			}
			else
			{
				Thread.Sleep(250);
			}
		}
	}

	private static string normaliseWaveRecordPath(string path)
	{
		if (string.IsNullOrWhiteSpace(path))
		{
			return null;
		}
		try
		{
			return Path.GetFullPath(path.Trim());
		}
		catch
		{
			return path.Trim();
		}
	}

	private static bool waveRecordPathsEqual(string left, string right)
	{
		if (string.IsNullOrWhiteSpace(left) || string.IsNullOrWhiteSpace(right))
		{
			return false;
		}
		return string.Equals(normaliseWaveRecordPath(left), normaliseWaveRecordPath(right), StringComparison.OrdinalIgnoreCase);
	}

	private static void loadImages(bool init = false)
	{
		string text = _openHPSDR_appdatapath;
		string current_skin_path = _current_skin_path;
		string[] array = new string[10] { "ananMM", "ananMM-bg", "ananMM-bg-tx", "cross-needle", "cross-needle-bg", "eye-bezel", "rotator_az-bg", "rotator_ele-bg", "rotator_both-bg", "rotator_map-bg" };
		string[] array2 = new string[6] { "", "-small", "-large", "-dark", "-dark-small", "-dark-large" };
		string[] array3 = new string[4] { ".png", ".jpg", ".jpeg", ".bmp" };
		if (!text.EndsWith("\\"))
		{
			text += "\\";
		}
		if (!Directory.Exists(text))
		{
			return;
		}
		for (int i = 0; i < array.Length; i++)
		{
			string text2 = current_skin_path + "\\Meters\\" + array[i];
			string text3 = text + "\\Meters\\" + array[i];
			for (int j = 0; j < array2.Length; j++)
			{
				for (int k = 0; k < array3.Length; k++)
				{
					string text4 = array2[j] + array3[k];
					if (File.Exists(text2 + text4))
					{
						if (!init)
						{
							string sKey = array[i] + array2[j];
							removeImageCacheData(sKey);
							foreach (KeyValuePair<string, DXRenderer> dXrenderer in _DXrenderers)
							{
								dXrenderer.Value.RemoveDXImage(sKey);
							}
						}
						loadImage(text2 + text4, isSkinImage: true);
						break;
					}
					if (File.Exists(text3 + text4))
					{
						loadImage(text3 + text4, isSkinImage: false);
						break;
					}
				}
			}
		}
	}

	private static void loadImage(string sFilePath, bool isSkinImage)
	{
		string fileNameWithoutExtension = Path.GetFileNameWithoutExtension(sFilePath);
		if (ContainsBitmap(fileNameWithoutExtension) || !File.Exists(sFilePath))
		{
			return;
		}
		System.Drawing.Image image = null;
		try
		{
			image = System.Drawing.Image.FromFile(sFilePath);
			System.Drawing.Bitmap bitmap = new System.Drawing.Bitmap(image);
			bitmap.Tag = isSkinImage;
			addBitmap(fileNameWithoutExtension, bitmap);
		}
		catch
		{
		}
		finally
		{
			image?.Dispose();
		}
	}

