	private static void clearAllCachedImageData(bool bOnlySkins = false)
	{
		if (_image_cache == null)
		{
			return;
		}
		lock (_imageLock)
		{
			foreach (string item in _image_cache.Keys.ToList())
			{
				removeImageCacheData(item, bOnlySkins);
			}
			if (!bOnlySkins)
			{
				_image_cache.Clear();
				_image_streamdata_cache.Clear();
			}
		}
	}

	private static bool removeImageCacheData(string sKey, bool bOnlySkins = false)
	{
		lock (_imageLock)
		{
			if (_image_cache == null)
			{
				return false;
			}
			if (!_image_cache.ContainsKey(sKey))
			{
				return false;
			}
			if (bOnlySkins && !(bool)_image_cache[sKey].Tag)
			{
				return false;
			}
			_image_cache[sKey].Dispose();
			_image_cache.Remove(sKey);
			if (_image_streamdata_cache != null && _image_streamdata_cache.ContainsKey(sKey))
			{
				_image_streamdata_cache[sKey].Dispose();
				_image_streamdata_cache.Remove(sKey);
			}
		}
		return true;
	}

	private static bool addBitmap(string sKey, System.Drawing.Bitmap image)
	{
		bool result = true;
		lock (_imageLock)
		{
			if (_image_cache == null)
			{
				result = false;
			}
			if (_image_cache.ContainsKey(sKey))
			{
				result = false;
			}
			_image_cache.Add(sKey, image);
			return result;
		}
	}

