			}
			ucMeter ucMeter2 = _lstUCMeters[sId];
			if (_lstMeterDisplayForms.ContainsKey(ucMeter2.ID))
			{
				frmMeterDisplay frmMeterDisplay2 = _lstMeterDisplayForms[ucMeter2.ID];
				if (minimises != ucMeter2.ContainerMinimises)
				{
					ucMeter2.ContainerMinimises = minimises;
					frmMeterDisplay2.ContainerMinimises = minimises;
				}
			}
		}
	}

	public static void RefreshContainerVisible(string id)
	{
		bool visible = !ContainerIsHidden(id);
		containerVisible(id, visible);
	}

	private static void containerVisible(string id, bool visible)
	{
		int num = 20;
		while (num > 0 && !_concurrent_container_visibility.AddOrUpdate(id, visible, (string key, bool val) => visible))
		{
			num--;
		}
		ContainerVisibleHandlers?.Invoke(id, visible);
	}

	public static void ContainerHidesWhenRXNotUsed(string sId, bool hides)
	{
		lock (_metersLock)
		{
			if (_meters == null || !_meters.ContainsKey(sId) || _lstUCMeters == null || !_lstUCMeters.ContainsKey(sId) || _lstMeterDisplayForms == null || !_lstMeterDisplayForms.ContainsKey(sId))
			{
				return;
			}
			clsMeter clsMeter2 = _meters[sId];
			ucMeter ucMeter2 = _lstUCMeters[sId];
			frmMeterDisplay obj = _lstMeterDisplayForms[ucMeter2.ID];
			ucMeter2.ContainerHidesWhenRXNotUsed = hides;
			obj.ContainerHidesWhenRXNotUsed = hides;
			if (clsMeter2.RX == 2 && !clsMeter2.RX2Enabled && ucMeter2.ContainerHidesWhenRXNotUsed)
			{
				if (ucMeter2.Floating)
				{
					_lstMeterDisplayForms[ucMeter2.ID].Hide();
				}
				else
				{
					ucMeter2.Hide();
					ucMeter2.Repaint();
				}
				containerVisible(ucMeter2.ID, visible: false);
			}
			else if (ucMeter2.MeterEnabled && (!ucMeter2.Visible & !ucMeter2.HiddenByMacro))
			{
				if (ucMeter2.Floating)
				{
					setMeterFloating(ucMeter2, _lstMeterDisplayForms[ucMeter2.ID]);
				}
				else
				{
					returnMeterFromFloating(ucMeter2, _lstMeterDisplayForms[ucMeter2.ID]);
				}
				containerVisible(ucMeter2.ID, visible: true);
			}
		}
	}

