	public static void HiddenByMacro(string sId, bool hide, string sId_copy_size = null)
	{
		lock (_metersLock)
		{
			if (_meters == null || !_meters.ContainsKey(sId) || _lstUCMeters == null || !_lstUCMeters.ContainsKey(sId) || !_lstMeterDisplayForms.ContainsKey(sId))
			{
				return;
			}
			_meters[sId].HiddenByMacro = hide;
			ucMeter ucMeter2 = _lstUCMeters[sId];
			ucMeter2.HiddenByMacro = hide;
			frmMeterDisplay frmMeterDisplay2 = _lstMeterDisplayForms[sId];
			frmMeterDisplay2.HiddenByMacro = hide;
			if (!hide && !string.IsNullOrEmpty(sId_copy_size) && (1u & ((_meters != null && _meters.ContainsKey(sId_copy_size)) ? 1u : 0u) & ((_lstUCMeters != null && _lstUCMeters.ContainsKey(sId_copy_size)) ? 1u : 0u) & (_lstMeterDisplayForms.ContainsKey(sId_copy_size) ? 1u : 0u)) != 0)
			{
				frmMeterDisplay frmMeterDisplay3 = _lstMeterDisplayForms[sId_copy_size];
				_ = _meters[sId_copy_size];
				ucMeter ucMeter3 = _lstUCMeters[sId_copy_size];
				if (ucMeter2.Floating)
				{
					frmMeterDisplay2.Location = new System.Drawing.Point(frmMeterDisplay3.Location.X, frmMeterDisplay3.Location.Y);
					frmMeterDisplay2.Size = new Size(frmMeterDisplay3.Size.Width, frmMeterDisplay3.Size.Height);
				}
				else
				{
					ucMeter2.Location = new System.Drawing.Point(ucMeter3.Location.X, ucMeter3.Location.Y);
					ucMeter2.Size = new Size(ucMeter3.Size.Width, ucMeter3.Size.Height);
					ucMeter2.DockedLocation = new System.Drawing.Point(ucMeter3.Location.X, ucMeter3.Location.Y);
					ucMeter2.DockedSize = new Size(ucMeter3.Size.Width, ucMeter3.Size.Height);
				}
			}
			enableContainer(sId, !hide, !hide);
			updateHiddenMacroInfo(ucMeter2);
		}
	}

