	public static void enableContainer(string sId, bool enabled, bool undo_hidden_by_macro = false)
	{
		lock (_metersLock)
		{
			if (_lstUCMeters == null || !_lstUCMeters.ContainsKey(sId) || !_lstMeterDisplayForms.ContainsKey(sId))
			{
				return;
			}
			ucMeter ucMeter2 = _lstUCMeters[sId];
			frmMeterDisplay frmMeterDisplay2 = _lstMeterDisplayForms[sId];
			bool flag = false;
			flag = ucMeter2.MeterEnabled;
			ucMeter2.MeterEnabled = enabled;
			if (undo_hidden_by_macro)
			{
				ucMeter2.HiddenByMacro = false;
				frmMeterDisplay2.HiddenByMacro = false;
				if (_meters != null && _meters.ContainsKey(sId))
				{
					_meters[sId].HiddenByMacro = false;
				}
			}
			updateHiddenMacroInfo(ucMeter2);
			if (ucMeter2.HiddenByMacro)
			{
				if (ucMeter2.Floating)
				{
					frmMeterDisplay2.Hide();
				}
				else
				{
					ucMeter2.Hide();
					ucMeter2.Repaint();
				}
				ContainerHiddenByMacroHandlers?.Invoke(sId, ucMeter2.HiddenByMacro);
				containerVisible(sId, visible: false);
			}
			else
			{
				if ((!undo_hidden_by_macro && enabled == flag) || !_lstMeterDisplayForms.ContainsKey(ucMeter2.ID))
				{
					return;
				}
				bool flag2 = true;
				frmMeterDisplay2.FormEnabled = enabled;
				if (ucMeter2.Floating)
				{
					if (!enabled)
					{
						frmMeterDisplay2.Hide();
					}
					else
					{
						setMeterFloating(ucMeter2, frmMeterDisplay2);
						flag2 = false;
					}
				}
				else if (!enabled)
				{
					ucMeter2.Hide();
					ucMeter2.Repaint();
				}
				else
				{
					returnMeterFromFloating(ucMeter2, frmMeterDisplay2);
					flag2 = false;
				}
				if (_meters != null && _meters.ContainsKey(sId))
				{
					_meters[sId].Enabled = enabled;
				}
				if (_DXrenderers != null && _DXrenderers.ContainsKey(ucMeter2.ID))
				{
					_DXrenderers[sId].Enabled = enabled;
				}
				ContainerHiddenByMacroHandlers?.Invoke(sId, ucMeter2.HiddenByMacro);
				ContainerEnabledHandlers?.Invoke(sId, enabled);
				if (flag2)
				{
					containerVisible(sId, enabled);
				}
			}
		}
	}

