	public static bool ContainerIsHidden(string sId)
	{
		int num = 20;
		bool value = false;
		bool flag = false;
		while (num > 0)
		{
			flag = _concurrent_hidden_by_macro.TryGetValue(sId, out value);
			if (flag)
			{
				break;
			}
			num--;
		}
		if (flag & value)
		{
			return true;
		}
		for (num = 20; num > 0; num--)
		{
			flag = _concurrent_container_visibility.TryGetValue(sId, out value);
			if (flag)
			{
				break;
			}
		}
		if (flag)
		{
			return !value;
		}
		return false;
	}

