	public static List<string> GetMeterIDsFromSaveData(Dictionary<string, string> data, bool include_ig_ids = false)
	{
		List<string> list = new List<string>();
		if (data == null || data.Count == 0)
		{
			return list;
		}
		foreach (KeyValuePair<string, string> datum in data)
		{
			string key = datum.Key;
			string value = datum.Value;
			if (key.Contains("meterContData_"))
			{
				string item = key.Split('_')[1];
				if (!list.Contains(item))
				{
					list.Add(item);
				}
			}
			else if (key.Contains("meterData_"))
			{
				string item2 = key.Split('_')[1];
				if (!list.Contains(item2))
				{
					list.Add(item2);
				}
			}
			else if (key.Contains("meterIGData_"))
			{
				string item3 = key.Split('_')[1];
				if (include_ig_ids && !list.Contains(item3))
				{
					list.Add(item3);
				}
				string item4 = value.Split('|')[1];
				if (!list.Contains(item4))
				{
					list.Add(item4);
				}
			}
			else
			{
				if (!key.Contains("meterIGSettings_"))
				{
					continue;
				}
				string text = ((key.Split('_').Length != 3) ? key.Split('_')[1] : key.Split('_')[2]);
				if (include_ig_ids && !list.Contains(text))
				{
					list.Add(text);
				}
				lock (_metersLock)
				{
					foreach (KeyValuePair<string, clsMeter> meter in _meters)
					{
						clsMeter value2 = meter.Value;
						foreach (KeyValuePair<string, clsItemGroup> meterGroup in value2.getMeterGroups())
						{
							if (text == meterGroup.Key && !list.Contains(value2.ID))
							{
								list.Add(value2.ID);
							}
						}
					}
				}
			}
		}
		return list;
	}

	public static void Shutdown()
	{
		_cat_queue_system.stopAll();
		MeterScriptEngine.Stop();
		if (_image_fetcher != null)
		{
			_image_fetcher.Shutdown();
		}
		MultiMeterIO.StopConnections();
		removeDelegates();
		MiniSpec.ShutdownAllRX();
		foreach (KeyValuePair<string, DXRenderer> dXrenderer in _DXrenderers)
		{
			dXrenderer.Value.ShutdownDX();
		}
		DisposeImageData();
		_meterThreadRunning = false;
		if (_meterThread != null && _meterThread.IsAlive)
		{
			int num = 0;
			lock (_metersLock)
			{
				foreach (KeyValuePair<string, clsMeter> meter in _meters)
				{
					int num2 = meter.Value.DelayForUpdate();
					if (num2 > num)
					{
						num = num2;
					}
				}
			}
			_meterThread.Join(num + 100);
		}
		foreach (KeyValuePair<string, frmMeterDisplay> lstMeterDisplayForm in _lstMeterDisplayForms)
		{
			lstMeterDisplayForm.Value.Close();
		}
	}

	private static void addDelegates()
	{
		if (!_delegatesAdded && _console != null)
		{
			Console console = _console;
			console.MeterReadingsChangedHandlers = (Console.MeterReadings)Delegate.Combine(console.MeterReadingsChangedHandlers, new Console.MeterReadings(OnMeterReadings));
			Console console2 = _console;
			console2.MoxPreChangeHandlers = (Console.MoxPreChanged)Delegate.Combine(console2.MoxPreChangeHandlers, new Console.MoxPreChanged(OnPreMox));
			Console console3 = _console;
