			Console console4 = _console;
			console4.PowerChangeHanders = (Console.PowerChanged)Delegate.Combine(console4.PowerChangeHanders, new Console.PowerChanged(OnPower));
			Console console5 = _console;
			console5.VFOAFrequencyChangeHandlers = (Console.VFOAFrequencyChanged)Delegate.Combine(console5.VFOAFrequencyChangeHandlers, new Console.VFOAFrequencyChanged(OnVFOA));
			Console console6 = _console;
			console6.VFOBFrequencyChangeHandlers = (Console.VFOBFrequencyChanged)Delegate.Combine(console6.VFOBFrequencyChangeHandlers, new Console.VFOBFrequencyChanged(OnVFOB));
			Console console7 = _console;
			console7.BandChangeHandlers = (Console.BandChanged)Delegate.Combine(console7.BandChangeHandlers, new Console.BandChanged(OnBandChange));
			Console console8 = _console;
			console8.BandPreChangeHandlers = (Console.BandPreChange)Delegate.Combine(console8.BandPreChangeHandlers, new Console.BandPreChange(OnPreBandChange));
