	private static void OnTXFrequencyChanged(double old_frequency, double new_frequency, Band old_band, Band new_band, bool rx2_enabled, bool tx_vfob, double centre_freq)
	{
		if (old_frequency == new_frequency && old_band == new_band)
		{
			return;
		}
		MiniSpec.clsMiniSpec clsMiniSpec = ((!(rx2_enabled & tx_vfob)) ? MiniSpec.GetMiniRX(0) : MiniSpec.GetMiniRX(1));
		if (clsMiniSpec != null)
		{
			clsMiniSpec.CentreFreq = centre_freq;
			clsMiniSpec.TXFrequency = new_frequency;
		}
		lock (_metersLock)
		{
			foreach (KeyValuePair<string, clsMeter> meter in _meters)
			{
				meter.Value.AntennasChanged(Band.FIRST, new_band, -1.0, new_frequency);
			}
		}
	}

	private static void OnAntennaRXChanged(Band b, int antenna, bool old_state, bool new_state)
	{
		if (b >= Band.B160M && b <= Band.B6M && antenna >= 0 && antenna <= 2)
		{
			lock (_antenna_lock)
			{
				_rx_ant[(int)(b - 1)][antenna] = new_state;
			}
			if (old_state != new_state)
			{
				updateAntennaMeters();
			}
