	public static int GetRXAnt(Band b, bool xvtr)
	{
		if (b < Band.B160M || b > Band.B6M)
		{
			return -2;
		}
		int num = (int)(b - 1);
		if (xvtr)
		{
			if (_rx_ant_aux[num][2])
			{
				return 5;
			}
		}
		else
		{
			if (_rx_ant_aux[num][0])
			{
				return 3;
			}
			if (_rx_ant_aux[num][1])
			{
				return 4;
			}
		}
		for (int i = 0; i < 3; i++)
		{
			if (_rx_ant[num][i])
			{
				return i;
			}
		}
		return -1;
	}

