	private static void OnFilterChanged(int rx, Filter oldFilter, Filter newFilter, Band band, int low, int high, string sName)
	{
		updateFilterInfo(rx, newFilter, newFilter, band, low, high, sName);
	}

	private static void updateFilterInfo(int rx, Filter oldFilter, Filter newFilter, Band band, int low, int high, string sName, int max_width = -1, int max_shift = -1)
	{
		lock (_metersLock)
		{
			bool flag = true;
			bool flag2 = true;
			foreach (KeyValuePair<string, clsMeter> item in _meters.Where((KeyValuePair<string, clsMeter> o) => o.Value.RX == rx))
			{
				clsMeter value = item.Value;
				bool flag3 = oldFilter != newFilter || value.FilterMaxWidth != max_width || value.FilterMaxShift != max_shift;
				if (flag)
				{
					flag3 |= value.FilterVfoA != newFilter || value.FilterVfoAName != sName || value.FilterVfoAlow != low || value.FilterVfoAhigh != high;
				}
				if (flag2)
				{
					flag3 |= value.FilterVfoB != newFilter || value.FilterVfoBName != sName || value.FilterVfoBlow != low || value.FilterVfoBhigh != high;
				}
				if (flag3)
				{
					if (flag)
					{
						value.FilterVfoA = newFilter;
						value.FilterVfoAName = sName;
						value.FilterVfoAlow = low;
						value.FilterVfoAhigh = high;
					}
					if (flag2)
					{
						value.FilterVfoB = newFilter;
						value.FilterVfoBName = sName;
						value.FilterVfoBlow = low;
						value.FilterVfoBhigh = high;
					}
					if (max_width != -1 && max_shift != -1)
					{
						value.FilterMaxWidth = max_width;
						value.FilterMaxShift = max_shift;
					}
					value.UpdateFilterDetails(newFilter, sName, low, high, flag, flag2, max_width, max_shift);
				}
			}
		}
	}

