	private static void bandChange(int rx, Band old_band, Band new_band, bool update_button_boxes = false, bool update_band = true)
	{
		lock (_metersLock)
		{
			if (update_band)
			{
				foreach (KeyValuePair<string, clsMeter> meter in _meters)
				{
					clsMeter value = meter.Value;
					if (rx == 1)
					{
						if (value.RX == 1)
						{
							value.BandVfoA = new_band;
							value.BandChanged(old_band, new_band);
						}
					}
					else if (!value.RX2Enabled)
					{
						if (value.RX == 1)
						{
							value.BandVfoB = new_band;
						}
					}
					else if (value.RX == 2)
					{
						value.BandVfoB = new_band;
						value.BandChanged(old_band, new_band);
					}
					value.ZeroOut(bRxReadings: true, bTxReadings: false);
				}
			}
			if (!update_button_boxes || old_band == new_band)
			{
				return;
			}
			foreach (KeyValuePair<string, clsMeter> meter2 in _meters)
			{
				meter2.Value.AntennasChanged(new_band, Band.FIRST, -1.0, -1.0);
			}
		}
	}

