	private static void OnVFOA(Band oldBand, Band newBand, DSPMode oldMode, DSPMode newMode, Filter oldFilter, Filter newFilter, double oldFreq, double newFreq, double oldCentreF, double newCentreF, bool oldCTUN, bool newCTUN, int oldZoomSlider, int newZoomSlider, double offset, int rx)
	{
		if (rx == 1)
		{
			_rx1VHForAbove = newFreq >= _s9Frequency;
			if (oldFreq != newFreq)
			{
				MiniSpec.clsMiniSpec miniRX = MiniSpec.GetMiniRX(0);
				if (miniRX != null)
				{
					miniRX.RXFrequency = newFreq;
				}
			}
		}
		if (oldFreq != newFreq || oldMode != newMode || oldBand != newBand)
		{
			lock (_metersLock)
			{
				foreach (KeyValuePair<string, clsMeter> item in _meters.Where((KeyValuePair<string, clsMeter> o) => o.Value.RX == rx))
				{
					clsMeter value = item.Value;
					if (oldFreq != newFreq)
					{
						value.VfoA = newFreq;
					}
					if (oldMode != newMode)
					{
						value.ModeVfoA = newMode;
					}
					if (oldBand != newBand)
					{
						value.BandVfoA = newBand;
					}
				}
				if (oldFreq != newFreq)
				{
					foreach (KeyValuePair<string, clsMeter> meter in _meters)
					{
						meter.Value.AntennasChanged(newBand, Band.FIRST, newFreq, -1.0);
					}
				}
			}
		}
		if (oldBand != newBand)
		{
			bandChange(rx, oldBand, newBand, update_button_boxes: true, update_band: false);
		}
	}

	private static void OnVFOB(Band oldBand, Band newBand, DSPMode oldMode, DSPMode newMode, Filter oldFilter, Filter newFilter, double oldFreq, double newFreq, double oldCentreF, double newCentreF, bool oldCTUN, bool newCTUN, int oldZoomSlider, int newZoomSlider, double offset, int rx)
	{
		if (rx == 2)
		{
			_rx2VHForAbove = _console.RX2Enabled && newFreq >= _s9Frequency;
			if (oldFreq != newFreq)
			{
				MiniSpec.clsMiniSpec miniRX = MiniSpec.GetMiniRX(1);
				if (miniRX != null)
				{
					miniRX.RXFrequency = newFreq;
				}
			}
		}
		if (oldFreq != newFreq || oldMode != newMode || oldBand != newBand)
		{
			lock (_metersLock)
			{
				foreach (KeyValuePair<string, clsMeter> item in _meters.Where((KeyValuePair<string, clsMeter> o) => o.Value.RX == rx))
				{
					clsMeter value = item.Value;
					if (oldFreq != newFreq)
					{
						value.VfoB = newFreq;
					}
					if (oldMode != newMode)
					{
						value.ModeVfoB = newMode;
					}
					if (oldBand != newBand)
					{
						value.BandVfoB = newBand;
					}
				}
			}
		}
		if (oldBand != newBand)
		{
			bandChange(rx, oldBand, newBand, update_button_boxes: true, update_band: false);
		}
	}

	private static void OnVFOASub(Band oldBand, Band newBand, DSPMode newMode, Filter newFilter, double oldFreq, double newFreq, double newCentreF, bool newCTUN, int newZoomSlider, double offset, int rx)
	{
		MiniSpec.clsMiniSpec miniRX = MiniSpec.GetMiniRX(0, sub_receiver: true);
		if (miniRX != null && oldFreq != newFreq)
		{
			miniRX.RXFrequency = newFreq;
		}
		lock (_metersLock)
		{
			foreach (KeyValuePair<string, clsMeter> item in _meters.Where((KeyValuePair<string, clsMeter> o) => o.Value.RX == 1))
			{
				clsMeter value = item.Value;
				if (oldFreq != newFreq)
				{
					value.VfoSub = newFreq;
				}
				if (oldBand != newBand)
				{
					value.BandVfoASub = newBand;
				}
			}
		}
	}

