	private static void initAllConsoleData()
	{
		List<int> list = new List<int>();
		lock (_metersLock)
		{
			foreach (KeyValuePair<string, clsMeter> meter in _meters)
			{
				if (!list.Contains(meter.Value.RX))
				{
					list.Add(meter.Value.RX);
				}
			}
		}
		foreach (int item in list)
		{
			initConsoleData(item);
		}
	}

	private static void initConsoleData(clsMeter m)
	{
		m.Power = _console.PowerOn;
		m.MOX = _console.MOX;
		m.Split = _console.VFOSplit;
		m.TXVFOb = _console.VFOBTX;
		m.RX2Enabled = _console.RX2Enabled;
		m.MultiRxEnabled = _console.GetSubRX(m.RX);
		m.CWPitch = _console.CWPitch;
		m.ShowCWZero = Display.ShowCWZeroLine;
		m.TXBand = _console.TXBand;
		m.VfoA = _console.VFOAFreq;
		m.ModeVfoA = _console.RX1DSPMode;
		m.BandVfoA = _console.RX1Band;
		m.FilterVfoA = _console.RX1Filter;
		m.FilterVfoAName = getFilterName(1);
		m.MinNotchWidthRX = _console.GetMinimumRXNotchWidth(m.RX);
		m.FilterMaxWidth = _console.MaxFilterWidth;
		m.FilterMaxShift = _console.MaxFilterShift;
		int low = _console.TXFilterLow;
		int high = _console.TXFilterHigh;
		_console.UpdateTXLowHighFilterForMode((_console.RX2Enabled && _console.VFOBTX) ? _console.RX2DSPMode : _console.RX1DSPMode, ref low, ref high);
		m.TXFilterLow = low;
		m.TXFilterHigh = high;
		m.PAProfile = _console.PAProfileName;
		m.TXProfile = _console.TXProfile;
		m.VfoB = _console.VFOBFreq;
		m.VfoSub = _console.VFOASubFreq;
		m.TNFActive = _console.TNFActive;
		if (!_console.RX2Enabled && m.RX == 1)
		{
			m.ModeVfoB = _console.RX1DSPMode;
			m.BandVfoB = _console.RX1BandForVFOB();
			m.FilterVfoB = _console.RX1Filter;
			m.FilterVfoBName = getFilterName(1);
		}
		else
		{
			m.ModeVfoB = _console.RX2DSPMode;
			m.BandVfoB = _console.RX2Band;
			m.FilterVfoB = _console.RX2Filter;
			m.FilterVfoBName = getFilterName(2);
		}
		m.VFOALock = _console.VFOALock;
		m.VFOBLock = _console.VFOBLock;
		m.VFOSync = _console.VFOSync;
		m.TXEQEnabled = _console.TXEQ;
		m.LevelerEnabled = !_console.IsSetupFormNull && _console.SetupForm.TXLevelerOn;
		m.CFCEnabled = _console.CFCEnabled;
		m.CompandEnabled = _console.CPDR;
		m.QuickSplitEnabled = _console.GetQuickSplitEnabled;
		if (m.RX == 1)
		{
			if (_console.BandGENSelected)
			{
				m.BandGroup = BandGroups.GEN;
			}
			if (_console.BandHFSelected)
			{
				m.BandGroup = BandGroups.HF;
			}
			if (_console.BandVHFSelected)
			{
				m.BandGroup = BandGroups.VHF;
			}
			m.FilterVfoAlow = _console.RX1FilterLow;
			m.FilterVfoAhigh = _console.RX1FilterHigh;
			m.RXSpectrumGridMin = Display.SpectrumGridMin;
			m.RXSpectrumGridMax = Display.SpectrumGridMax;
			m.RXWaterfallMin = (int)Display.WaterfallLowThreshold;
			m.RXWaterfallMax = (int)Display.WaterfallHighThreshold;
		}
		else if (m.RX == 2)
		{
			m.BandGroup = m.GetBandGroupFromBand(_console.RX2Band);
			m.FilterVfoAlow = _console.RX2FilterLow;
			m.FilterVfoAhigh = _console.RX2FilterHigh;
			m.FilterVfoBlow = _console.RX2FilterLow;
			m.FilterVfoBhigh = _console.RX2FilterHigh;
			m.RXSpectrumGridMin = Display.RX2SpectrumGridMin;
			m.RXSpectrumGridMax = Display.RX2SpectrumGridMax;
			m.RXWaterfallMin = (int)Display.RX2WaterfallLowThreshold;
			m.RXWaterfallMax = (int)Display.RX2WaterfallHighThreshold;
		}
		m.NR = _console.GetSelectedNR(m.RX);
		m.NB = _console.GetSelectedNB(m.RX);
		m.ANF = _console.GetANF(m.RX);
		m.SNB = _console.GetSNB(m.RX);
		m.AVG = _console.GetAVG(m.RX);
		m.Peak = _console.GetPeak(m.RX);
		m.CTUN = _console.GetCTUN(m.RX);
		m.MON = _console.MON;
		m.Tune = _console.TUN;
		m.TwoTone = _console.TwoTone;
		m.Duplex = _console.DisplayDuplex;
		m.Puresignal = _console.PSA;
		m.QuickPlay = _console.QuickPlay;
		m.QuickRecord = _console.QuickRec;
		m.WaveRecord = _console.WaveRecording(m.RX);
		m.Vac1 = _console.VACEnabled;
		m.Vac2 = _console.VAC2Enabled;
		m.Mute = _console.GetMute(m.RX);
		m.BIN = _console.GetBin(m.RX);
		m.PanSwap = _console.GetPanSwap(m.RX);
		m.DisplayMode = _console.GetDisplayMode(m.RX);
		m.AGCMode = _console.GetAGCMode(m.RX);
		m.AGCAutoMode = _console.GetAGCAuto(m.RX);
		Dictionary<OtherButtonId, bool> dictionary = new Dictionary<OtherButtonId, bool>();
		dictionary.Add(OtherButtonId.MUTE_ALL, _console.GetGeneralSetting(m.RX, OtherButtonId.MUTE_ALL));
		dictionary.Add(OtherButtonId.MIC, _console.GetGeneralSetting(m.RX, OtherButtonId.MIC));
		dictionary.Add(OtherButtonId.COMP, _console.GetGeneralSetting(m.RX, OtherButtonId.COMP));
		dictionary.Add(OtherButtonId.VOX, _console.GetGeneralSetting(m.RX, OtherButtonId.VOX));
		dictionary.Add(OtherButtonId.DEXP, _console.GetGeneralSetting(m.RX, OtherButtonId.DEXP));
		dictionary.Add(OtherButtonId.RX_EQ, _console.GetGeneralSetting(m.RX, OtherButtonId.RX_EQ));
		dictionary.Add(OtherButtonId.TX_EQ, _console.GetGeneralSetting(m.RX, OtherButtonId.TX_EQ));
		dictionary.Add(OtherButtonId.TX_FILTER, _console.GetGeneralSetting(m.RX, OtherButtonId.TX_FILTER));
		dictionary.Add(OtherButtonId.CFC, _console.GetGeneralSetting(m.RX, OtherButtonId.CFC));
		dictionary.Add(OtherButtonId.CFC_EQ, _console.GetGeneralSetting(m.RX, OtherButtonId.CFC_EQ));
		dictionary.Add(OtherButtonId.LEVELER, _console.GetGeneralSetting(m.RX, OtherButtonId.LEVELER));
		dictionary.Add(OtherButtonId.PHASE_ROT, _console.GetGeneralSetting(m.RX, OtherButtonId.PHASE_ROT));
		dictionary.Add(OtherButtonId.PAUSE, _console.GetGeneralSetting(m.RX, OtherButtonId.PAUSE));
		dictionary.Add(OtherButtonId.PEAK_BLOBS, _console.GetGeneralSetting(m.RX, OtherButtonId.PEAK_BLOBS));
		dictionary.Add(OtherButtonId.CURSOR_INFO, _console.GetGeneralSetting(m.RX, OtherButtonId.CURSOR_INFO));
		dictionary.Add(OtherButtonId.SPOTS, _console.GetGeneralSetting(m.RX, OtherButtonId.SPOTS));
