		dictionary.Add(OtherButtonId.FILL_SPECTRUM, _console.GetGeneralSetting(m.RX, OtherButtonId.FILL_SPECTRUM));
		dictionary.Add(OtherButtonId.RIT, _console.GetGeneralSetting(m.RX, OtherButtonId.RIT));
		dictionary.Add(OtherButtonId.XIT, _console.GetGeneralSetting(m.RX, OtherButtonId.XIT));
		dictionary.Add(OtherButtonId.DITHER, _console.GetGeneralSetting(m.RX, OtherButtonId.DITHER));
		dictionary.Add(OtherButtonId.RANDOM, _console.GetGeneralSetting(m.RX, OtherButtonId.RANDOM));
		dictionary.Add(OtherButtonId.SR_48000, _console.GetGeneralSetting(m.RX, OtherButtonId.SR_48000));
		dictionary.Add(OtherButtonId.SR_96000, _console.GetGeneralSetting(m.RX, OtherButtonId.SR_96000));
