	private static string getFilterName(int rx)
	{
		try
		{
			switch (rx)
			{
			case 1:
				if (_console.RX1DSPMode == DSPMode.FIRST || _console.RX1DSPMode == DSPMode.LAST || _console.RX1Filter == Filter.FIRST || _console.RX1Filter == Filter.LAST)
				{
					return "";
				}
				return _console.rx1_filters[(int)_console.RX1DSPMode].GetName(_console.RX1Filter);
			case 2:
				if (_console.RX2DSPMode == DSPMode.FIRST || _console.RX2DSPMode == DSPMode.LAST || _console.RX2Filter == Filter.FIRST || _console.RX2Filter == Filter.LAST)
				{
					return "";
				}
				return _console.rx2_filters[(int)_console.RX2DSPMode].GetName(_console.RX2Filter);
			default:
				return "";
			}
		}
		catch
		{
			return "";
		}
	}

	private static string getFilterName(int rx, Filter f)
	{
		try
		{
			switch (rx)
			{
			case 1:
				if (_console.RX1DSPMode == DSPMode.FIRST || _console.RX1DSPMode == DSPMode.LAST || _console.RX1Filter == Filter.FIRST || _console.RX1Filter == Filter.LAST)
				{
					return f.ToString();
				}
				return _console.rx1_filters[(int)_console.RX1DSPMode].GetName(f);
			case 2:
				if (_console.RX2DSPMode == DSPMode.FIRST || _console.RX2DSPMode == DSPMode.LAST || _console.RX2Filter == Filter.FIRST || _console.RX2Filter == Filter.LAST)
				{
					return f.ToString();
				}
				return _console.rx2_filters[(int)_console.RX2DSPMode].GetName(f);
			default:
				return "";
			}
		}
		catch
		{
			return "";
		}
	}

	private static void OnPower(bool oldPower, bool newPower)
	{
		_power = newPower;
		if (oldPower == newPower)
		{
			return;
		}
		lock (_metersLock)
		{
			foreach (KeyValuePair<string, clsMeter> meter in _meters)
			{
				clsMeter value = meter.Value;
				value.ZeroOut(bRxReadings: true, bTxReadings: true);
				value.Power = newPower;
			}
		}
	}

	private static void OnPreMox(int rx, bool oldMox, bool newMox)
	{
		lock (_metersLock)
		{
			if (_readingIgnore != null && _readingIgnore.ContainsKey(rx))
			{
				_readingIgnore[rx] = true;
			}
		}
	}

	private static void OnMox(int rx, bool oldMox, bool newMox)
	{
		lock (_metersLock)
		{
			List<string> list = new List<string>();
			List<string> list2 = new List<string>();
			foreach (KeyValuePair<string, clsMeter> meter in _meters)
			{
				clsMeter value = meter.Value;
				bool mOX = value.MOX;
				value.MOX = (rx == value.RX) & newMox;
				if (newMox && !oldMox)
				{
					value.ZeroOut(bRxReadings: true, bTxReadings: false);
				}
				else if (!newMox & oldMox)
				{
					value.ZeroOut(bRxReadings: false, bTxReadings: true);
				}
				if (!_lstUCMeters.ContainsKey(value.ID))
				{
					continue;
				}
				ucMeter ucMeter2 = _lstUCMeters[value.ID];
				if (ucMeter2.HiddenByMacro)
				{
					list.Add(value.ID);
					continue;
				}
				if (value.MOX && !mOX)
				{
					if (!ucMeter2.MeterEnabled && ucMeter2.ShowOnTX)
					{
						list2.Add(value.ID);
					}
					if (ucMeter2.MeterEnabled && !ucMeter2.ShowOnTX)
					{
						list.Add(value.ID);
					}
				}
				if (!value.MOX & mOX)
				{
					if (!ucMeter2.MeterEnabled && ucMeter2.ShowOnRX)
					{
						list2.Add(value.ID);
					}
					if (ucMeter2.MeterEnabled && !ucMeter2.ShowOnRX)
					{
						list.Add(value.ID);
					}
				}
			}
			foreach (string item in list2)
			{
				enableContainer(item, enabled: true);
			}
			foreach (string item2 in list)
			{
				enableContainer(item2, enabled: false);
			}
			if (_readingIgnore != null && _readingIgnore.ContainsKey(rx))
			{
				_readingIgnore[rx] = false;
			}
		}
	}

