	public static int QuickestUpdateInterval(int rx, bool mox)
	{
		int num = int.MaxValue;
		lock (_metersLock)
		{
			foreach (KeyValuePair<string, clsMeter> item in _meters.Where((KeyValuePair<string, clsMeter> kvp) => kvp.Value.RX == rx))
			{
				int num2 = item.Value.QuickestUpdateInterval(mox, console_only_refresh: true);
				if (num2 < num)
				{
					num = num2;
				}
			}
		}
		if (num == int.MaxValue)
		{
			num = 250;
		}
		return num;
	}

