	public static void AddMeterContainer(ucMeter ucM, bool bFromRestore = false)
	{
		if (_console == null)
		{
			return;
		}
		lock (_metersLock)
		{
			ucM.Sequence = _uc_sequence;
			_uc_sequence++;
			bool meterEnabled = ucM.MeterEnabled;
			ucM.Console = _console;
			ucM.FloatingDockedClicked += ucMeter_FloatingDockedClicked;
			ucM.DockedMoved += ucMeter_FloatingDockedMoved;
			ucM.SettingsClicked += ucMeter_SettingsClicked;
			frmMeterDisplay frmMeterDisplay2 = new frmMeterDisplay(_console, ucM.RX);
			frmMeterDisplay2.ID = ucM.ID;
			if (ucM.Floating & bFromRestore)
			{
				ucM.Size = new Size(frmMeterDisplay2.Size.Width, frmMeterDisplay2.Size.Height);
			}
			clsMeter clsMeter2 = new clsMeter(ucM.RX, ucM.Name);
			clsMeter2.ID = ucM.ID;
			clsMeter2.Enabled = meterEnabled;
			addRenderer(ucM.ID, ucM.RX, ucM.DisplayContainer, clsMeter2, ucM.BackColor);
			lock (_metersLock)
			{
				_lstMeterDisplayForms.Add(frmMeterDisplay2.ID, frmMeterDisplay2);
				_lstUCMeters.Add(ucM.ID, ucM);
				_meters.Add(clsMeter2.ID, clsMeter2);
				updateHiddenMacroInfo(ucM);
			}
			initConsoleData(ucM.RX);
			if (meterEnabled && ucM.MeterEnabled && (!bFromRestore & !ucM.HiddenByMacro))
			{
				if (ucM.Floating)
				{
					setMeterFloating(ucM, frmMeterDisplay2);
				}
				else
				{
					returnMeterFromFloating(ucM, frmMeterDisplay2);
				}
			}
		}
	}

