	public static void FinishSetupAndDisplay()
	{
		if (_lstUCMeters == null || _lstUCMeters.Count == 0)
		{
			_finishedSetup = true;
			return;
		}
		initAllConsoleData();
		zeroAllMeters();
		_finishedSetup = true;
		lock (_metersLock)
		{
			foreach (KeyValuePair<string, ucMeter> lstUCMeter in _lstUCMeters)
			{
				ucMeter value = lstUCMeter.Value;
				if (_lstMeterDisplayForms.ContainsKey(value.ID) && value.MeterEnabled && !value.HiddenByMacro)
				{
					frmMeterDisplay frm = _lstMeterDisplayForms[value.ID];
					if (value.Floating)
					{
						setMeterFloating(value, frm);
					}
					else
					{
						returnMeterFromFloating(value, frm);
					}
				}
			}
		}
	}

