	private static void setPoisitionOfDockedMeter(ucMeter m)
	{
		if (_console == null)
		{
			return;
		}
		int hDelta = _console.HDelta;
		int vDelta = _console.VDelta;
		if (!m.Floating)
		{
			System.Drawing.Point point = default(System.Drawing.Point);
			switch (m.AxisLock)
			{
			case Axis.RIGHT:
			case Axis.BOTTOMRIGHT:
				point = new System.Drawing.Point(m.DockedLocation.X - m.Delta.X + hDelta, m.DockedLocation.Y - m.Delta.Y + vDelta);
				break;
			case Axis.LEFT:
			case Axis.BOTTOMLEFT:
				point = new System.Drawing.Point(m.DockedLocation.X, m.DockedLocation.Y - m.Delta.Y + vDelta);
				break;
			case Axis.TOPLEFT:
				point = new System.Drawing.Point(m.DockedLocation.X, m.DockedLocation.Y);
				break;
			case Axis.TOP:
				point = new System.Drawing.Point(m.DockedLocation.X - m.Delta.X + hDelta, m.DockedLocation.Y);
				break;
			case Axis.BOTTOM:
				point = new System.Drawing.Point(m.DockedLocation.X - m.Delta.X + hDelta, m.DockedLocation.Y - m.Delta.Y + vDelta);
				break;
			case Axis.TOPRIGHT:
				point = new System.Drawing.Point(m.DockedLocation.X - m.Delta.X + hDelta, m.DockedLocation.Y);
				break;
			}
			if (point.X + m.Width > _console.Width)
			{
				point.X = _console.Width - m.Width;
			}
			if (point.Y + m.Height > _console.Height)
			{
				point.Y = _console.Height - m.Height;
			}
			if (point.X < 0)
			{
				point.X = 0;
			}
			if (point.Y < 0)
			{
				point.Y = 0;
			}
			if (point != m.Location)
			{
				m.Location = point;
			}
		}
	}

	private static void returnMeterFromFloating(ucMeter m, frmMeterDisplay frm)
	{
		if (_console != null)
		{
			frm.Floating = false;
			frm.Hide();
			m.Hide();
			m.Parent = _console;
			m.Anchor = AnchorStyles.None;
			m.RestoreLocation();
			m.Floating = false;
			setPoisitionOfDockedMeter(m);
			m.BringToFront();
			if (!_finishedSetup)
			{
				containerVisible(m.ID, visible: false);
			}
			if ((m.RX != 2 || _console.RX2Enabled || !m.ContainerHidesWhenRXNotUsed) && _finishedSetup)
			{
				m.Show();
				containerVisible(m.ID, visible: true);
			}
		}
	}

	private static void setMeterFloating(ucMeter m, frmMeterDisplay frm)
	{
		if (_console != null && (m.RX != 2 || _console.RX2Enabled || !m.ContainerHidesWhenRXNotUsed))
		{
			m.Hide();
			m.Repaint();
			frm.TakeOwner(m);
			frm.Floating = true;
			m.Floating = true;
			if (!_finishedSetup)
			{
				containerVisible(frm.ID, visible: false);
				return;
			}
			frm.Show();
			containerVisible(frm.ID, visible: true);
		}
	}

	private static void OnRX2EnabledChanged(bool enabled)
	{
		lock (_metersLock)
		{
			if (enabled)
			{
				foreach (KeyValuePair<string, ucMeter> lstUCMeter in _lstUCMeters)
				{
					ucMeter value = lstUCMeter.Value;
					if (_lstMeterDisplayForms.ContainsKey(value.ID) && value.MeterEnabled && !value.HiddenByMacro)
					{
						if (_meters.ContainsKey(value.ID))
						{
							_meters[value.ID].ZeroOut(bRxReadings: true, bTxReadings: true);
						}
						if (value.Floating)
						{
							setMeterFloating(value, _lstMeterDisplayForms[value.ID]);
						}
						else
						{
							returnMeterFromFloating(value, _lstMeterDisplayForms[value.ID]);
						}
					}
				}
			}
			lock (_metersLock)
			{
				foreach (KeyValuePair<string, clsMeter> meter in _meters)
				{
					meter.Value.RX2Enabled = enabled;
				}
			}
		}
		initAllConsoleData();
	}

	private static void OnRX2EnabledPreChanged(bool enabled)
	{
		if (enabled)
		{
			MiniSpec.clsMiniSpec miniRX = MiniSpec.GetMiniRX(1);
			if (miniRX != null)
			{
				miniRX.RXFrequency = _console.VFOBFreq;
				if (_console.VFOBTX)
				{
					miniRX.TXFrequency = _console.TXFreq;
				}
			}
		}
		if (enabled)
		{
			return;
		}
		lock (_metersLock)
		{
			foreach (KeyValuePair<string, ucMeter> item in _lstUCMeters.Where((KeyValuePair<string, ucMeter> o) => o.Value.RX == 2))
			{
				ucMeter value = item.Value;
				if (!_lstMeterDisplayForms.ContainsKey(value.ID))
				{
					continue;
				}
				if (value.ContainerHidesWhenRXNotUsed)
				{
					if (value.Floating)
					{
						_lstMeterDisplayForms[value.ID].Hide();
					}
					else
					{
						value.Hide();
						value.Repaint();
					}
					containerVisible(value.ID, visible: false);
				}
				if (_meters.ContainsKey(value.ID))
				{
					_meters[value.ID].ZeroOut(bRxReadings: true, bTxReadings: true);
				}
			}
		}
	}

	private static void zeroAllMeters()
	{
		lock (_metersLock)
		{
			foreach (KeyValuePair<string, clsMeter> meter in _meters)
			{
				meter.Value.ZeroOut(bRxReadings: true, bTxReadings: true);
			}
		}
	}

	public static bool RestoreSettings(ref Dictionary<string, string> settings)
	{
		MeterScriptEngine.BeginBatch();
		bool result = true;
		try
		{
			foreach (KeyValuePair<string, string> item in settings.Where((KeyValuePair<string, string> o) => o.Key.StartsWith("meterContData_")))
			{
				ucMeter ucMeter2 = new ucMeter();
				if (!ucMeter2.TryParse(item.Value) || MeterExists(ucMeter2.ID))
				{
					continue;
				}
				AddMeterContainer(ucMeter2, bFromRestore: true);
				clsMeter m = MeterFromId(ucMeter2.ID);
				if (m == null)
				{
					continue;
				}
				IEnumerable<KeyValuePair<string, string>> enumerable = settings.Where((KeyValuePair<string, string> o) => o.Key.StartsWith("meterData_" + m.ID));
				if (enumerable != null && enumerable.Count() == 1)
				{
					KeyValuePair<string, string> keyValuePair = enumerable.First();
					clsMeter clsMeter2 = new clsMeter(1, ucMeter2.Name);
					clsMeter2.TryParse(keyValuePair.Value);
					m.Name = clsMeter2.Name;
					m.RX = clsMeter2.RX;
					m.XRatio = clsMeter2.XRatio;
					m.YRatio = clsMeter2.YRatio;
					m.DisplayGroup = clsMeter2.DisplayGroup;
					m.PadX = clsMeter2.PadX;
					m.PadY = clsMeter2.PadY;
					m.Height = clsMeter2.Height;
				}
				foreach (KeyValuePair<string, string> item2 in settings.Where((KeyValuePair<string, string> o) => o.Key.StartsWith("meterIGData_") && o.Value.Contains(m.ID)))
				{
					clsItemGroup ig = new clsItemGroup();
					if (!ig.TryParse(item2.Value))
					{
						continue;
					}
					m.AddMeter(ig.MeterType, ig);
					IEnumerable<KeyValuePair<string, string>> enumerable2 = settings.Where((KeyValuePair<string, string> o) => o.Key.StartsWith("meterIGSettings_2_" + ig.ID));
					if (enumerable2 != null && enumerable2.Count() == 1)
					{
						clsIGSettings clsIGSettings2 = new clsIGSettings();
						if (clsIGSettings2.TryParse2(enumerable2.First().Value))
						{
							m.ApplySettingsForMeterGroup(ig.MeterType, clsIGSettings2, null, ig.Order);
						}
						continue;
					}
					enumerable2 = settings.Where((KeyValuePair<string, string> o) => o.Key.StartsWith("meterIGSettings_" + ig.ID) && !o.Key.StartsWith("meterIGSettings_2_"));
					if (enumerable2 != null && enumerable2.Count() == 1)
					{
						clsIGSettings clsIGSettings3 = new clsIGSettings();
						if (clsIGSettings3.TryParse(enumerable2.First().Value))
						{
							m.ApplySettingsForMeterGroup(ig.MeterType, clsIGSettings3, null, ig.Order);
						}
					}
				}
				m.ZeroOut(bRxReadings: true, bTxReadings: true);
				m.Rebuild();
			}
		}
		catch
		{
			result = false;
		}
		MeterScriptEngine.EndBatch();
		return result;
	}

	public static List<string> GetFormGuidList()
	{
		List<string> list = new List<string>();
		lock (_metersLock)
		{
			foreach (KeyValuePair<string, frmMeterDisplay> lstMeterDisplayForm in _lstMeterDisplayForms)
			{
				frmMeterDisplay value = lstMeterDisplayForm.Value;
				list.Add(value.ID);
			}
			return list;
		}
	}

	public static string ContainerToString(string id)
	{
		Dictionary<string, string> dictionary = new Dictionary<string, string>();
		try
		{
			lock (_metersLock)
			{
				lock (_metersLock)
				{
					dictionary.Add("FileVersion", "1");
					dictionary.Add("ThetisVersion", (_console != null) ? _console.BasicTitleBar : "unknown");
					dictionary.Add("CustomTitle", (_console != null && !_console.IsSetupFormNull) ? _console.SetupForm.CustomTitle : "empty");
					dictionary.Add("DiscordCallsign", (_console != null && !_console.IsSetupFormNull) ? _console.SetupForm.DiscordCallsign : "empty");
					dictionary.Add("TCIOwnCallsign", (_console != null && !_console.IsSetupFormNull) ? _console.SetupForm.TCIOwnCallsign : "empty");
					dictionary.Add("UTCTDateTime", DateTime.UtcNow.ToLongTimeString() + " " + DateTime.UtcNow.ToLongDateString());
					if (_lstUCMeters.TryGetValue(id, out var value))
					{
						dictionary.Add("ContainerData_" + value.ID, value.ToString());
						clsMeter clsMeter2 = MeterFromId(value.ID);
						if (clsMeter2 != null)
						{
							dictionary.Add("MeterData_" + value.ID, clsMeter2.ToString());
							if (_lstMeterDisplayForms.ContainsKey(value.ID))
							{
								frmMeterDisplay frmMeterDisplay2 = _lstMeterDisplayForms[value.ID];
								dictionary.Add("FormData_" + value.ID, $"{frmMeterDisplay2.Left}|{frmMeterDisplay2.Top}|{frmMeterDisplay2.Width}|{frmMeterDisplay2.Height}");
							}
							foreach (KeyValuePair<string, clsItemGroup> meterGroup in clsMeter2.getMeterGroups())
							{
								Dictionary<string, clsMeterItem> dictionary2 = clsMeter2.itemsFromID(meterGroup.Value.ID);
								if (dictionary2 != null)
								{
									foreach (KeyValuePair<string, clsMeterItem> item in dictionary2.Where((KeyValuePair<string, clsMeterItem> o) => o.Value.StoreSettings))
									{
										clsMeterItem value2 = item.Value;
										if (value2 != null && value2.ItemType == clsMeterItem.MeterItemType.ITEM_GROUP)
										{
											dictionary.Add("ItemGroupData_" + item.Value.ID, value2.ToString());
										}
									}
								}
								clsIGSettings settingsForMeterGroup = clsMeter2.GetSettingsForMeterGroup(meterGroup.Value.MeterType, meterGroup.Value.Order);
								if (settingsForMeterGroup != null)
								{
									dictionary.Add("ItemGroupSettings_2_" + meterGroup.Value.ID, settingsForMeterGroup.ToString2());
								}
							}
						}
					}
				}
			}
		}
		catch (Exception ex)
		{
			dictionary.Clear();
			dictionary.Add("err", ex.Message);
		}
		return Common.SerializeToBase64(dictionary);
	}

	public static ucMeter ContainerFromString(string data64, List<string> web_images = null)
	{
		string text = string.Empty;
		try
		{
			Dictionary<string, string> dictionary = Common.DeserializeFromBase64<Dictionary<string, string>>(data64);
			if (!dictionary.ContainsKey("FileVersion"))
			{
				return null;
			}
			if (!int.TryParse(dictionary["FileVersion"], out var result))
			{
				return null;
			}
			if (result < 1)
			{
				return null;
			}
			using IEnumerator<KeyValuePair<string, string>> enumerator = dictionary.Where((KeyValuePair<string, string> o) => o.Key.StartsWith("ContainerData_")).GetEnumerator();
			if (enumerator.MoveNext())
			{
				KeyValuePair<string, string> current = enumerator.Current;
				ucMeter ucMeter2 = new ucMeter();
				bool num = ucMeter2.TryParse(current.Value);
				text = ucMeter2.ID;
				Dictionary<string, string> fourchars = new Dictionary<string, string>();
				if (num)
				{
					string text2 = Guid.NewGuid().ToString();
					string old_ucm_id = ucMeter2.ID;
					ucMeter2.ID = text2;
					text = ucMeter2.ID;
					if (!MeterExists(ucMeter2.ID))
					{
						AddMeterContainer(ucMeter2, bFromRestore: true);
						clsMeter clsMeter2 = MeterFromId(ucMeter2.ID);
						if (clsMeter2 != null)
						{
							IEnumerable<KeyValuePair<string, string>> enumerable = dictionary.Where((KeyValuePair<string, string> o) => o.Key.StartsWith("MeterData_" + old_ucm_id, StringComparison.OrdinalIgnoreCase));
							if (enumerable != null && enumerable.Count() == 1)
							{
								KeyValuePair<string, string> keyValuePair = enumerable.First();
								clsMeter clsMeter3 = new clsMeter(1, ucMeter2.Name);
								clsMeter3.TryParse(keyValuePair.Value);
								clsMeter3.ID = text2;
								clsMeter2.Name = clsMeter3.Name;
								clsMeter2.RX = clsMeter3.RX;
								clsMeter2.XRatio = clsMeter3.XRatio;
								clsMeter2.YRatio = clsMeter3.YRatio;
								clsMeter2.DisplayGroup = clsMeter3.DisplayGroup;
								clsMeter2.PadX = clsMeter3.PadX;
								clsMeter2.PadY = clsMeter3.PadY;
								clsMeter2.Height = clsMeter3.Height;
							}
							IEnumerable<KeyValuePair<string, string>> enumerable2 = dictionary.Where((KeyValuePair<string, string> o) => o.Key.StartsWith("FormData_" + old_ucm_id, StringComparison.OrdinalIgnoreCase));
							if (enumerable2 != null && enumerable2.Count() == 1)
							{
								string[] array = enumerable2.First().Value.Split('|');
								if (array.Length >= 4 && _lstMeterDisplayForms.ContainsKey(text2))
								{
									frmMeterDisplay obj = _lstMeterDisplayForms[text2];
									obj.Left = (int.TryParse(array[0], out var result2) ? result2 : 200);
									obj.Top = (int.TryParse(array[1], out var result3) ? result3 : 200);
									obj.Width = (int.TryParse(array[2], out var result4) ? result4 : 200);
									obj.Height = (int.TryParse(array[3], out var result5) ? result5 : 200);
									Common.ForceFormOnScreen(obj, shrink_to_fit: true);
								}
							}
							IEnumerable<KeyValuePair<string, string>> enumerable3 = dictionary.Where((KeyValuePair<string, string> o) => o.Key.StartsWith("ItemGroupData_", StringComparison.OrdinalIgnoreCase) && o.Value.Contains(old_ucm_id));
							foreach (KeyValuePair<string, string> item in enumerable3)
							{
								clsItemGroup ig = new clsItemGroup();
								if (!ig.TryParse(item.Value))
								{
									continue;
								}
								ig.ParentID = text2;
								clsMeter2.AddMeter(ig.MeterType, ig);
								IEnumerable<KeyValuePair<string, string>> enumerable4 = dictionary.Where((KeyValuePair<string, string> o) => o.Key.StartsWith("ItemGroupSettings_2_" + ig.ID, StringComparison.OrdinalIgnoreCase));
								if (enumerable4 == null || enumerable4.Count() != 1)
								{
									continue;
								}
								clsIGSettings clsIGSettings2 = new clsIGSettings();
								if (clsIGSettings2.TryParse2(enumerable4.First().Value))
								{
									if (ig.MeterType == MeterType.VOICE_RECORD_PLAY_BUTTONS)
									{
										clsIGSettings2.SetSetting<string>("buttonbox_recordplayback_uid", null);
									}
									clsMeter2.ApplySettingsForMeterGroup(ig.MeterType, clsIGSettings2, null, ig.Order, from_setup_form: false, ignore_led_condition: true);
								}
								clsMeter2.Find4Chars(ref fourchars, clsIGSettings2);
								clsMeter2.RemoveMeterType(ig.MeterType, ig.Order);
							}
							foreach (KeyValuePair<string, string> item2 in enumerable3)
							{
								clsItemGroup clsItemGroup2 = new clsItemGroup();
								if (!clsItemGroup2.TryParse(item2.Value))
								{
									continue;
								}
								clsItemGroup2.ParentID = text2;
								string original_ig_id = clsItemGroup2.ID;
								clsItemGroup2.ID = Guid.NewGuid().ToString();
								clsMeter2.AddMeter(clsItemGroup2.MeterType, clsItemGroup2);
								IEnumerable<KeyValuePair<string, string>> enumerable5 = dictionary.Where((KeyValuePair<string, string> o) => o.Key.StartsWith("ItemGroupSettings_2_" + original_ig_id, StringComparison.OrdinalIgnoreCase));
								if (enumerable5 == null || enumerable5.Count() != 1)
								{
									continue;
								}
								clsIGSettings clsIGSettings3 = new clsIGSettings();
								if (!clsIGSettings3.TryParse2(enumerable5.First().Value))
								{
									continue;
								}
								if (clsItemGroup2.MeterType == MeterType.VOICE_RECORD_PLAY_BUTTONS)
								{
									clsIGSettings3.SetSetting<string>("buttonbox_recordplayback_uid", null);
									string[] setting = clsIGSettings3.GetSetting<string[]>("buttonbox_recordplayback_filepaths");
									for (int num2 = 0; num2 < setting.Length; num2++)
									{
										setting[num2] = null;
									}
									clsIGSettings3.SetSetting("buttonbox_recordplayback_filepaths", setting);
									int setting2 = clsIGSettings3.GetSetting("buttonbox_recordplayback_slots", validate: false, 1, 64, 8);
									for (int num3 = 0; num3 < setting2; num3++)
									{
										clsIGSettings3.SetSetting("buttonbox_recordplayback_locked_" + num3, value: false);
									}
								}
								clsMeter2.ApplySettingsForMeterGroup(clsItemGroup2.MeterType, clsIGSettings3, web_images, clsItemGroup2.Order);
							}
							clsMeter2.ZeroOut(bRxReadings: true, bTxReadings: true);
							clsMeter2.Rebuild();
						}
					}
				}
				return ucMeter2;
			}
		}
		catch
		{
			if (!string.IsNullOrEmpty(text))
			{
				try
				{
					RemoveMeterContainer(text);
				}
				catch
				{
				}
			}
		}
		return null;
	}

	public static bool StoreSettings2(ref Dictionary<string, string> a)
	{
		if (a == null)
		{
			return false;
		}
		bool result = true;
		try
		{
			lock (_metersLock)
			{
				foreach (KeyValuePair<string, ucMeter> lstUCMeter in _lstUCMeters)
				{
					a.Add("meterContData_" + lstUCMeter.Value.ID, lstUCMeter.Value.ToString());
					clsMeter clsMeter2 = MeterFromId(lstUCMeter.Value.ID);
					if (clsMeter2 == null)
					{
						continue;
					}
					a.Add("meterData_" + lstUCMeter.Value.ID, clsMeter2.ToString());
					foreach (KeyValuePair<string, clsItemGroup> meterGroup in clsMeter2.getMeterGroups())
					{
						Dictionary<string, clsMeterItem> dictionary = clsMeter2.itemsFromID(meterGroup.Value.ID);
						if (dictionary != null)
						{
							foreach (KeyValuePair<string, clsMeterItem> item in dictionary.Where((KeyValuePair<string, clsMeterItem> o) => o.Value.StoreSettings))
							{
								clsMeterItem value = item.Value;
								if (value != null && value.ItemType == clsMeterItem.MeterItemType.ITEM_GROUP)
								{
									a.Add("meterIGData_" + item.Value.ID, value.ToString());
								}
							}
						}
						clsIGSettings settingsForMeterGroup = clsMeter2.GetSettingsForMeterGroup(meterGroup.Value.MeterType, meterGroup.Value.Order);
						if (settingsForMeterGroup != null)
						{
							a.Add("meterIGSettings_2_" + meterGroup.Value.ID, settingsForMeterGroup.ToString2());
						}
					}
				}
			}
		}
		catch
		{
			result = false;
		}
		return result;
	}

	public static void RecoverContainer(string sId)
	{
		lock (_metersLock)
		{
			if (_lstUCMeters.ContainsKey(sId))
			{
				ucMeter ucMeter2 = _lstUCMeters[sId];
				ucMeter2.Floating = false;
				ucMeter2.MeterEnabled = false;
				enableContainer(sId, enabled: true, undo_hidden_by_macro: true);
				if (ucMeter2.Parent != null)
				{
					_ = ucMeter2.Parent.Size;
					ucMeter2.Location = new System.Drawing.Point(ucMeter2.Parent.ClientRectangle.Width / 2 - ucMeter2.Width / 2, ucMeter2.Parent.ClientRectangle.Height / 2 - ucMeter2.Height / 2);
				}
			}
		}
	}

	public static void RemoveMeterContainer(string sId)
	{
		lock (_metersLock)
		{
			containerVisible(sId, visible: false);
			frmMeterDisplay frmMeterDisplay2 = null;
			if (_lstMeterDisplayForms.ContainsKey(sId))
			{
				frmMeterDisplay2 = _lstMeterDisplayForms[sId];
				frmMeterDisplay2.Hide();
			}
			ucMeter ucMeter2 = null;
			if (_lstUCMeters.ContainsKey(sId))
			{
				ucMeter2 = _lstUCMeters[sId];
				ucMeter2.Hide();
				ucMeter2.Repaint();
				ucMeter2.FloatingDockedClicked -= ucMeter_FloatingDockedClicked;
				ucMeter2.DockedMoved -= ucMeter_FloatingDockedMoved;
				ucMeter2.SettingsClicked -= ucMeter_SettingsClicked;
			}
			removeRenderer(sId);
			if (frmMeterDisplay2 != null)
			{
				frmMeterDisplay2.Close();
				frmMeterDisplay2.Dispose();
				_lstMeterDisplayForms.Remove(sId);
			}
			if (ucMeter2 != null)
			{
				_console.Controls.Remove(ucMeter2);
				_lstUCMeters.Remove(sId);
				int num = 20;
				bool value;
				while (num > 20 && !_concurrent_hidden_by_macro.TryRemove(sId, out value))
				{
					num--;
				}
				num = 20;
				while (num > 20 && !_concurrent_container_visibility.TryRemove(sId, out value))
				{
					num--;
				}
			}
			if (_meters.ContainsKey(sId))
			{
				_meters[sId].RemoveAllMeterTypes();
				_meters.Remove(sId);
			}
		}
	}
}
